INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('易', 'N3', 'easy, ready to, simple, fortune-telling, divination', 'DỊ.DỊCH(dễ,mậu dịch,dị dễ nan khôn)', 'Nhật Vật là DỊ,DỊch.Động vật lúc có mặt trời thì dịch chuyển dễ dàng.賜:Bối Dịch là Tứ(ban thưởng)', ARRAY['エキ','イ'], ARRAY['やさ.しい','やす.い'], 8, 571, (SELECT id FROM radicals WHERE character = '72')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('椅', 'N1', 'chair', 'Ỷ(cái ghế)', 'Mộc Kì,cơ(lạ) là Ỷ ghế騎:Thêm Mã là Kị sĩ', ARRAY['イ'], NULL, 12, 2245, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('為', 'N1', 'do, change, make, benefit, welfare, be of use, reach to, try, practice, cost, serve as, good, advantage, as a result of', 'VI(hành vi)', 'Chủ Bảo Hỏa là Vi hành.Đốt lửa dưới ruộng bậc thang là hành vi phá hoại.偽:Thêm Nhân là Ngụy biện cho hành Vi sai trái.', ARRAY['イ'], ARRAY['ため','な.る','な.す','す.る','たり','つく.る','なり'], 9, 831, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('畏', 'N1', 'fear, majestic, graciously, be apprehensive', 'ÚY(sợ sệt)', 'Điền Y là ÚY kị.', ARRAY['イ'], ARRAY['おそ.れる','かしこま.る','かしこ','かしこ.し'], 9, 2389, (SELECT id FROM radicals WHERE character = '102')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
