INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('逸', 'N1', 'deviate, idleness, leisure, miss the mark, evade, elude, parry, diverge', 'DẬT(chia ra)', 'Sước Miễn( bỏ,khỏi) là Dật lầm lỗi,xổng ra,ẩn dật.Để Miễn thuế phải sống Ẩn DẬT.勉:Thay Lực là Miễn cưỡng.', ARRAY['イツ'], ARRAY['そ.れる','そ.らす','はぐ.れる'], 11, 1524, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('稲', 'N1', 'rice plant', 'ĐẠO(cây lúa)', 'Hòa Trảo Cựu(cũ,lâu:旧)là Đạo lúa.', ARRAY['トウ','テ'], ARRAY['いね','いな-'], 14, 1038, (SELECT id FROM radicals WHERE character = '115')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('茨', 'N1', 'briar, thorn', 'TỲ(gai góc,lều tranh,nhà lá)', 'Thảo Thứ là Tì lều tranh,cỏ gai.CỎ có gai.tiếp theo là loại cỏ Tì, hình dáng trông như cái gai', ARRAY['シ','ジ'], ARRAY['いばら','かや','くさぶき'], 9, 1203, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
