INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('院', 'N4', 'Inst., institution, temple, mansion, school', 'VIỆN(tòa nhà)', 'Phụ Hoàn(đủ,vẹn,xong) là Viện:Hạ viện,y viện.Nơi bạn có thể hoàn toàn hồi phục là bệnh viện Hoàn mỹ đn.', ARRAY['イン'], NULL, 10, 150, (SELECT id FROM radicals WHERE character = '170')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
