INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('渦', 'N1', 'whirlpool, eddy, vortex', 'OA(nước xoáy)', 'Thủy Oa(méo,lệch:咼) là Oa nước xoáy.Qua sông thì gặp dòng XOÁY.過:Thay Sước là QUá khứ.禍:Thay Thị là Họa(tai họa).鍋:Thay Kim là Oa(nồi chảo)', ARRAY['カ'], ARRAY['うず'], 12, 1789, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
