INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('餌', 'N1', 'food, bait, prey, tempting profit', 'NHĨ,NHỊ(đồ ăn động vật,mồi)', 'Nhĩ làm mồi cho NHỊ.151. 半 bán nửa 152. 雙 song đôi 153. 餌 nhĩ mồi154. 綸 luân chỉ 155. 猴 hầu khỉ 156. 虎 hổ hùm', ARRAY['ジ','ニ'], ARRAY['え','えば','えさ','もち'], 14, 2277, (SELECT id FROM radicals WHERE character = '184')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
