INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('英', 'N4', 'England, English, hero, outstanding, calyx', 'ANH(nước Anh,tài năng)', 'Thảo Ương là Anh quốc.THẢO muốn làm việc trên trung ƯƠNG thì phải học TIẾNG ANh.映:Thay Nhật là phản Ánh,điện ảnh.', ARRAY['エイ'], ARRAY['はなぶさ'], 8, 430, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('衛', 'N1', 'defense, protection', 'VỆ(phòng vệ)', 'Hành VI là Vệ sĩ.Khi đi vi hành cần có thị vệ', ARRAY['エイ','エ'], NULL, 16, 400, (SELECT id FROM radicals WHERE character = '144')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
