INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鋭', 'N2', 'pointed, sharpness, edge, weapon, sharp, violent', 'NHUỆ(sắc bén)', 'Kim Đoái(quẻ đoái,thẳng:兌)là Nhuệ sắc,nhọn.', ARRAY['エイ'], ARRAY['するど.い'], 15, 1395, (SELECT id FROM radicals WHERE character = '167')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
