INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('益', 'N1', 'benefit, gain, profit, advantage', 'ÍCH(lợi ích,thêm lên)', 'Một chiếc đĩa có 8 lợi ÍCH.溢:Thêm Thủy là Dật(tràn đầy)', ARRAY['エキ','ヤク'], ARRAY['ま.す'], 10, 674, (SELECT id FROM radicals WHERE character = '108')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('駅', 'N4', 'station', 'DỊCH(nhà ga)', 'Mã Xích là Dịch(nhà ga).Con ngựa馬bị xích trước cửa ga', ARRAY['エキ'], NULL, 14, 724, (SELECT id FROM radicals WHERE character = '187')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('悦', 'N1', 'ecstasy, joy, rapture', 'DUYỆT(đẹp lòng,vui)', 'Tâm ĐOái(đổi,trả:兑) là DUyệt(vui).Trái tim tôi mãn nguyện khi anh trai có 2 cái sừng trên đầu', ARRAY['エツ'], ARRAY['よろこ.ぶ','よろこ.ばす'], 10, 1762, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('謁', 'N1', 'audience, audience (with king)', 'YẾT(ra mắt,yết kiến,xin vào hầu chuyện)', 'Ngôn Hạt là Yết kiến.掲: Thay Thủ là Yết xuất bản.', ARRAY['エツ'], NULL, 15, NULL, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
