INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('延', 'N2', 'prolong, stretching', 'DUYÊN(kéo dài,hoãn,giãn rộng)', 'Duyên Dẫn Chính đi chơi kéo dài.誕:Ngôn Duyên là Đản(sinh ra).', ARRAY['エン'], ARRAY['の.びる','の.べる','の.べ','の.ばす'], 8, 747, (SELECT id FROM radicals WHERE character = '54')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('怨', 'N1', 'grudge, show resentment, be jealous', 'OÁN(oán giận)', 'Uyên (宛:nhỏ nhẹ) bị mất nhà (宀) nên Tâm rất Oán hận.Tịch Tiết Tâm là Oán', ARRAY['エン','オン','ウン'], ARRAY['うら.む','うらみ','うら.めしい'], 9, 2137, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('援', 'N1', 'abet, help, save', 'VIỆN(viện trợ,kéo,dắt)', 'Thủ Viên(bèn,bởi vậy,cho nên:爰)Trảo Nhất Hữu là Viện trợ.媛:Thêm Nữ là Viện(con gái đẹp,kỹ viện).緩:Thêm Mịch là Hoãn(trì hoãn).暖:Thêm Nhật là Noãn(ấm nóng).', ARRAY['エン'], NULL, 12, 312, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('沿', 'N1', 'run alongside, follow along, run along, lie along', 'DUYÊN(dọc theo)', 'Thủy Bát Khẩu là DUyên dọc theo.鉛:Thay Kim là DUyên(chất chì)船: Thay Chu là Thuyền bè.', ARRAY['エン'], ARRAY['そ.う','-ぞ.い'], 8, 1121, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('演', 'N3', 'performance, act, play, render, stage', 'DIỄN(trình diễn)', 'Thủy Dần(năm Dần:寅) là Diễn thuyết.', ARRAY['エン'], NULL, 14, 267, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('炎', 'N1', 'inflammation, flame, blaze', 'VIÊM(viêm nhiễm,bốc cháy)', 'lửa cháy lớn bị bỏng viêm loét khắp người', ARRAY['エン'], ARRAY['ほのお'], 8, 1242, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('煙', 'N3', 'smoke', 'YÊN(khói)', 'Hỏa yên(lấp,chôn:垔.Tây Thổ) là Yên khói.', ARRAY['エン'], ARRAY['けむ.る','けむり','けむ.い'], 13, 1290, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
