INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('猿', 'N1', 'monkey', 'VIÊN(con khỉ,vượn)', 'Khuyển Viên(họ viên:袁) là Viên con khỉ.園:Thay Vi là công Viên.遠:Thay Sước là Viễn(xa).', ARRAY['エン'], ARRAY['さる'], 13, 1772, (SELECT id FROM radicals WHERE character = '94')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('縁', 'N1', 'affinity, relation, connection, edge, border, verge, brink', 'DUYÊN(duyên số)', 'Mịch Kệ Thỉ là Duyên số.sợi dây kéo con nhím và con lợn thành mối lương duyên', ARRAY['エン','-ネン'], ARRAY['ふち','ふち.どる','ゆかり','よすが','へり','えにし'], 15, 1291, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('艶', 'N1', 'glossy, luster, glaze, polish, charm, colorful, captivating', 'DIỄM(bóng bẩy,tươi sáng)', 'Phong(phong phú:豊Khúc Đậu) Sắc là DIễm lệ,bóng bẩy.Màu sắc quả đậu đẹp khúc nào ra khúc nấy', ARRAY['エン'], ARRAY['つや','なま.めかしい','あで.やか','つや.めく','なま.めく'], 19, 2207, (SELECT id FROM radicals WHERE character = '139')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
