INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('応', 'N1', 'apply, answer, yes, OK, reply, accept', 'ỨNG(phản ứng,đáp ứng,ứng đối)', 'Nghiễm Tâm Ứng.TÂM mà để ở NHÀ thì làm gì cũng PHẢN ỨNG chậm...Hoạ sĩ Lê Duy Ứng.', ARRAY['オウ','ヨウ','-ノウ'], ARRAY['あた.る','まさに','こた.える'], 7, 266, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
