INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('欧', 'N2', 'Europe', 'ÂU(châu Âu)', 'Khu Khiếm là Âu châu.Châu Âu là KHU vực không thể THIẾU.殴:Thêm Thù là Ẩu đả', ARRAY['オウ'], ARRAY['うた.う','は.く'], 8, 421, (SELECT id FROM radicals WHERE character = '76')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
