INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('果', 'N3', 'fruit, reward, carry out, achieve, complete, end, finish, succeed', 'QUẢ(kết quả)', 'Điền Mộc là Quả.菓:Thêm Thảo là Quả(bánh kẹo).巣:Thêm 3 Vạch trên là Sào(tổ chim,yến sào).課:Thêm Ngôn là Khóa(niên khóa).裸:Thêm Y là Khỏa thân', ARRAY['カ'], ARRAY['は.たす','はた.す','-は.たす','は.てる','-は.てる','は.て'], 8, 258, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('架', 'N1', 'erect, frame, mount, support, shelf, construct', 'GIÁ(treo,mắc,bắc cầu)', 'Gia Mộc là Giá treo áo quần.賀:Gia Bối là Hạ(chúc mừng).', ARRAY['カ'], ARRAY['か.ける','か.かる'], 9, 1555, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('歌', 'N4', 'song, sing', 'CA(ca hát)', '2 Khả và Khiếm là Ca hát.Cuộc sống sẽ rất buồn chán nếu Thiếu 欠 Khả Năng 可 Ca, Hát 歌.', ARRAY['カ'], ARRAY['うた','うた.う'], 14, 519, (SELECT id FROM radicals WHERE character = '76')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
