INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('稼', 'N1', 'earnings, work, earn money', 'GIÁ(kiếm sống)', 'Hòa Gia là GIá kiếm tiền.Ngày xưa cây Lúa (HÒA) có GIÁ nên cả GIA đình dựa vào đó để KIẾM TIỀN.嫁:Thay Nữ là Giá(lấy chồng)', ARRAY['カ'], ARRAY['かせ.ぐ'], 15, 1264, (SELECT id FROM radicals WHERE character = '115')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
