INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('花', 'N4', 'flower', 'HOA(bông hoa)', 'Thảo Hóa là Hoa.', ARRAY['カ','ケ'], ARRAY['はな'], 7, 578, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('苛', 'N1', 'torment, scold, chastise', 'HÀ(bắt nạt)', 'Thảo Khả là Hà ghen ghét,phiền toái.HÀ có Khả năng BẮT NẠT Thảo.荷:Thêm Nhân là Hà(hành lý).何:Hà cái gì.河:Thay Thủy là Hà sông.', ARRAY['カ'], ARRAY['いじ.める','さいな.む','いらだ.つ','からい','こまかい'], 8, NULL, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('茄', 'BEYOND', 'eggplant', '', '', ARRAY['カ'], NULL, 8, NULL, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('荷', 'N2', 'baggage, shoulder-pole load, bear (a burden), shoulder (a gun), load, cargo, freight', 'HÀ(hành lý)', 'Thảo Hà là Hà hành lý.苛:Bỏ Nhân là Hà(bắt nạt)', ARRAY['カ'], ARRAY['に'], 10, 1230, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
