INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('過', 'N3', 'overdo, exceed, go beyond, error', 'QUÁ(đi qua,sai lầm,làm quá lên)', 'Sước Qua là Quá vượt.Quá Khứ.Đi qua nhà người yêu cũ.渦:Thay Thủy là Qua(vòng xoáy).禍:Thay Thị là tai Họa.鍋:Thay Kim là Oa(nồi,chảo).', ARRAY['カ'], ARRAY['す.ぎる','す.ごす','あやま.ち','あやま.つ','よぎ.る','よ.ぎる'], 12, 285, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
