INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('芽', 'N1', 'bud, sprout, spear, germ', 'NHA(mầm,chồi)', 'Thảo Nha là Nha mầm.146. 芽 nha mống 147. 皼 cổ trống 148. 鉦 chinh chiêng 149. 傾 khuynh nghiêng 150. 仰 ngưỡng ngửa 151. 半 bán nửa 152. 雙 song đôi', ARRAY['ガ'], ARRAY['め'], 8, 1691, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('賀', 'N1', 'congratulations, joy', 'HẠ(chúc mừng)', 'Gia Bối là Hạ mừng.HẠ thấp việc gia công tiền để tổ chức tiệc tùng các kiểu.架:Thay Mộc là Giá(cái giá).', ARRAY['ガ'], NULL, 12, 1056, (SELECT id FROM radicals WHERE character = '154')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('雅', 'N1', 'gracious, elegant, graceful, refined', 'NHÃ(thanh lịch,trang nhã)', 'Nha Chuy là Nhã thanh lịch.Người nhã nhặn thì không dùng răng cắn vào chim', ARRAY['ガ'], ARRAY['みや.び'], 13, 1192, (SELECT id FROM radicals WHERE character = '172')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
