INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('塊', 'N1', 'clod, lump, chunk, clot, mass', 'KHỐI(tảng,miếng,đống)', 'Thổ Quỷ là Khối:Con QUỶ 鬼 từ đất 土 chui ra biến thành KHỐI đá 塊', ARRAY['カイ','ケ'], ARRAY['かたまり','つちくれ'], 13, 1800, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('壊', 'N1', 'demolition, break, destroy', 'HOẠI(bị hư,phá hoại)', '10 con mắt dõi theo sự phá hoại y phục vứt xuống đấtHoài (hoài niệm):懐 thêm tâmphá hoại thêm THổThổ thập võng y là Hoại', ARRAY['カイ','エ'], ARRAY['こわ.す','こわ.れる','やぶ.る'], 16, 727, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
