INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('快', 'N2', 'cheerful, pleasant, agreeable, comfortable', 'KHOÁI(thoải mái,sảng khoái)', 'Tâm quái là Khoái(thích)yêu quái (夬) Khoái ăn tim (忄)決:Thủy quái là Quyết định', ARRAY['カイ'], ARRAY['こころよ.い'], 7, 1074, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('怪', 'N1', 'suspicious, mystery, apparition', 'QUÁI(nghi ngờ,yêu quái,lạ)', 'Tâm Thánh(圣:thần thánh) là yêu Quái.経:Chỉ Thánh là Kinh tế.径:Xích Thánh là Kính(đường kính)', ARRAY['カイ','ケ'], ARRAY['あや.しい','あや.しむ'], 8, 1634, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('悔', 'N1', 'repent, regret', 'HỐI(tiếc,hối hận)', 'Tâm Mỗi(毎) là Hối.con Tim Mỗi ngày đều cảm thấy Hối tiếc', ARRAY['カイ'], ARRAY['く.いる','く.やむ','くや.しい'], 9, 1460, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
