INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('拐', 'N1', 'kidnap, falsify', 'QUẢI(bắt cóc)', 'Thủ Lánh(khác,riêng biệt:另)khẩu lực là QUải (thủ Khẩu Đao???)枴 :Thêm Mộc là cái gậy người già chống.', ARRAY['カイ'], NULL, 8, 1498, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
