INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('皆', 'N3', 'all, everything', 'GIAI(tất cả,mọi người)', 'Tỉ Bạch là Giai mọi người.階:Thêm Phụ là Giai cấp.楷:Thêm Mộc là Giai(cây giai).諧:Thêm Ngôn là Hài hòa.', ARRAY['カイ'], ARRAY['みな','みんな'], 9, 1267, (SELECT id FROM radicals WHERE character = '106')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
