INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('階', 'N2', 'storey, stair, counter for storeys of a building', 'GIAI(giai đoạn)', 'Phụ Giai là Giai đoạn.Bực thềm.BÁCH niên GIAI lão thì phải cười ヒヒ để lộ răng trắng 白.楷:Thay Mộc là cây Giai.諧:thay Ngôn là Hài hòa.', ARRAY['カイ'], ARRAY['きざはし'], 12, 513, (SELECT id FROM radicals WHERE character = '170')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
