INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('劾', 'N1', 'censure, criminal investigation', 'HẶC(hạch tội)', 'Hợi(亥:ất hợi) hằng Hặc đòi HẠI Lực,hợi Hặc: hay hạch tộiHặc giống Khắc(刻)', ARRAY['ガイ'], NULL, 8, 2085, (SELECT id FROM radicals WHERE character = '19')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
