INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('害', 'N3', 'harm, injury', 'HẠI(tổn hại,ghen ghét)', 'Nhà 3 miệng ăn hạiCát(cắt đứt,chia):割', ARRAY['ガイ'], NULL, 10, 358, (SELECT id FROM radicals WHERE character = '40')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('崖', 'N1', 'cliff, bluff, precipice', 'NHAI(vách núi)', 'đứng ở sườn núi ,bên trên là núi cao, dưới là vực, thì chỉ có thể là "Hắc Mộc Nhai"-tiếu ngạo giang hồ.Hắc mộng nhai nhiều giai nhân bên vách núi', ARRAY['ガイ','ゲ','ギ'], ARRAY['がけ','きし','はて'], 11, NULL, (SELECT id FROM radicals WHERE character = '46')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('慨', 'N1', 'rue, be sad, sigh, lament', 'KHÁI(luyến tiếc,cảm khái)', 'Tâm Kí(既:đã qua) là Khái(khẳng khái).Tâm KÍ(Cấn Vô) là Khái(cảm khái,than thở)', ARRAY['ガイ'], ARRAY['なげ.く'], 13, 1875, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('概', 'N1', 'outline, condition, approximation, generally', 'KHÁI(khái quát,phần lớn)', 'Mộc Kí(đã rồi:既) là Khái quát.慨:Thêm Tâm là Khái niệm', ARRAY['ガイ'], ARRAY['おおむ.ね'], 14, 1335, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('涯', 'N1', 'horizon, shore, limit, bound', 'NHAI(bờ bến,thiên nhai)', 'Thủy Hán Giai là Nhai bờ bến.佳:Thay Nhân là Giai nhân崖:Thay Sơn là Nhai(vệ núi)', ARRAY['ガイ'], ARRAY['はて'], 11, 1525, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('蓋', 'N1', 'cover, lid, flap', 'CÁI(cái nắp)', 'Thảo Hạp(hợp:盍Khứ Mãnh)là Cái cái nắp.Cái "nắp" dùng để đậy lên dĩa "皿" ngày xưa "去" được làm từ cỏ', ARRAY['ガイ','カイ','コウ'], ARRAY['ふた','けだ.し','おお.う','かさ','かこう'], 13, 2388, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('街', 'N1', 'boulevard, street, town', 'NHAI(dãy phố)', 'Hành Khuê(cái đong:圭)là Nhai.Hai mảnh đất có con đường đi qua gọi là khu phố.掛:Thay Thủ Bốc là Quải treo.佳:Thay Nhân là Giai nhân', ARRAY['ガイ','カイ'], ARRAY['まち'], 12, 891, (SELECT id FROM radicals WHERE character = '144')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('該', 'N1', 'above-stated, the said, that specific', 'CAI(bao quát,thích hợp)', 'Ngôn Hợi là Cai bao quát.骸:Thay Cốt là thi Hài.', ARRAY['ガイ'], NULL, 13, 1648, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
