INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('垣', 'N1', 'hedge, fence, wall', 'VIÊN(hàng rào)', 'Đắp đất 2 ngày ra khuôn viên hàng rào', ARRAY['エン'], ARRAY['かき'], 9, 1539, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('柿', 'N1', 'persimmon', 'THỊ(cây hồng)', 'Mộc Thị là cây Thị.', ARRAY['シ'], ARRAY['かき'], 9, 1745, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('嚇', 'N1', 'menacing, dignity, majesty, threaten', 'HÁCH(dọa nạt,hăm dọa)', 'Trương Phi Miệng hống HÁCH đỏ bừng 2 má đi dọa nạt người khácHách là Khẩu xích xích', ARRAY['カク'], ARRAY['おど.す'], 17, 2141, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('各', 'N2', 'each, every, either', 'CÁC(đều,mỗi,những)', 'CÁC :Tri Khẩu,Các vị to mồm Lại theo sau mà đến(tri,truy)', ARRAY['カク'], ARRAY['おのおの'], 6, 243, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('拡', 'N1', 'broaden, extend, expand, enlarge', 'KHUẾCH(mở rộng,khuếch đại)', 'Thủ Quảng là Khuếch đại鉱:Thêm Kim là Khoáng sản.', ARRAY['カク','コウ'], ARRAY['ひろ.がる','ひろ.げる','ひろ.める'], 8, 611, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('格', 'N3', 'status, rank, capacity, character, case (law, grammar)', 'CÁCH(tính cách)', 'Mộc Các là tính Cách', ARRAY['カク','コウ','キャク','ゴウ'], NULL, 10, 281, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('核', 'N1', 'nucleus, core, kernel', 'HẠCH(hạt nhân)', 'Mộc Hợi là Hạch nhân.', ARRAY['カク'], NULL, 10, 475, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('殻', 'N1', 'husk, nut shell', 'XÁC(vỏ ốc,vỏ)', 'Xác(壳 ) Thù là Xác.', ARRAY['カク','コク','バイ'], ARRAY['から','がら'], 11, 1892, (SELECT id FROM radicals WHERE character = '79')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('獲', 'N1', 'seize, get, find, earn, acquire, can, may, able to', 'HOẠCH(bắt được,thu hoạch)', 'Khuyển Thảo Chuy Hựu là Hoạch.穫:Thay Hòa là Hoạch(săn bắt).護:Thay Ngôn là bảo Hộ.', ARRAY['カク'], ARRAY['え.る'], 16, 964, (SELECT id FROM radicals WHERE character = '94')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('確', 'N3', 'assurance, firm, tight, hard, solid, confirm, clear, evident', 'XÁC(xác nhận,bền chắc)', 'Thạch Miên CHuy là Xác nhận.Con Chim trốn dưới Mái nhà mà vẫn bị cục Đá ném Chính Xác', ARRAY['カク','コウ'], ARRAY['たし.か','たし.かめる'], 15, 252, (SELECT id FROM radicals WHERE character = '112')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('穫', 'N1', 'harvest, reap', 'HOẠCH(thu hoạch,gặt,cắt lúa)', 'Hòa Thảo Chuy Hựu là Hoạch định.獲:Thay Khuyển là Hoạch(săn bắt).護:Thay Ngôn là bảo HỘ.', ARRAY['カク'], NULL, 18, 1642, (SELECT id FROM radicals WHERE character = '115')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('覚', 'N3', 'memorize, learn, remember, awake, sober up', 'GIÁC(nhớ,cảm giác)', 'Tiểu Mịch Kiến là Giác quan.', ARRAY['カク'], ARRAY['おぼ.える','さ.ます','さ.める','さと.る'], 12, 710, (SELECT id FROM radicals WHERE character = '147')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('角', 'N2', 'angle, corner, square, horn, antlers', '', '', ARRAY['カク'], ARRAY['かど','つの'], 7, 805, (SELECT id FROM radicals WHERE character = '148')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('較', 'N1', 'contrast, compare', 'GIẢO(so sánh)', 'Xa Giao là GIảo,Giác so sánh.Giao lưu 交 (so sánh )xe cộ 車.絞:Thay Mịch là Giảo(vắt,thắt).郊:Thay Ấp là Giao(ngoại ô).', ARRAY['カク','コウ'], ARRAY['くら.べる'], 13, 1172, (SELECT id FROM radicals WHERE character = '159')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('郭', 'N1', 'enclosure, quarters, fortification, red-light district', 'QUÁCH(viền rào,ngoài thành,cái quách)', 'Hưởng Ấp là Quách.thành quách.An hưởng lúc chết.', ARRAY['カク'], ARRAY['くるわ'], 11, 1670, (SELECT id FROM radicals WHERE character = '163')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('閣', 'N1', 'tower, tall building, palace', 'CÁC(nội các)', 'Môn Các là Các:Gác.Nội các.Các vị quan khách đang đứng ngoài cổng', ARRAY['カク'], NULL, 14, 444, (SELECT id FROM radicals WHERE character = '169')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('隔', 'N1', 'isolate, alternate, distance, separate, gulf', 'CÁCH(khoảng cách)', 'Phụ Cách là Cách:ngăn cách,phân chia.融:Thay Trùng là Dung môi.', ARRAY['カク'], ARRAY['へだ.てる','へだ.たる'], 13, 1382, (SELECT id FROM radicals WHERE character = '170')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('革', 'N2', 'leather, skin, reform, become serious', '', '', ARRAY['カク'], ARRAY['かわ'], 9, 249, (SELECT id FROM radicals WHERE character = '177')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('学', 'N5', 'study, learning, science', 'HỌC(học tập)', '', ARRAY['ガク'], ARRAY['まな.ぶ'], 8, 63, (SELECT id FROM radicals WHERE character = '39')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('岳', 'N1', 'point, peak, mountain', 'NHẠC(núi cao)', 'Khâu(gò đồi) SƠn là NHạc(núi ngũ nhạc)', ARRAY['ガク'], ARRAY['たけ'], 8, 1334, (SELECT id FROM radicals WHERE character = '46')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('楽', 'N4', 'music, comfort, ease', 'LẠC,NHẠC(vui vẻ,âm nhạc)', 'thứ màu trắng (BẠCH) làm từ gỗ (MỘC) phát ra 4 tiếng nghe ÂM NHẠC rất VUI VẺ.薬:thêm Thảo là Dược(thuốc)', ARRAY['ガク','ラク','ゴウ'], ARRAY['たの.しい','たの.しむ','この.む'], 13, 373, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('額', 'N2', 'forehead, tablet, plaque, framed picture, sum, amount, volume', 'NGẠCH(kim ngạch,cái trán)', 'Khách(người khách:客Miên Các)Hiệt là Ngạch:cái trán,kim ngạch:giá trị.Đếm số ĐẦU KHÁCH để tính hạn NGẠCH suất cơm nấu hôm nay', ARRAY['ガク'], ARRAY['ひたい'], 18, 407, (SELECT id FROM radicals WHERE character = '181')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('顎', 'N1', 'jaw, chin, gill', 'NGẠC(cái cằm,gò má)', 'Cái cằm là bộ phận thứ 5 nằm dưới con mắt và cái đầu.', ARRAY['ガク'], ARRAY['あご','あぎと'], 18, NULL, (SELECT id FROM radicals WHERE character = '181')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
