INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('割', 'N3', 'proportion, comparatively, divide, cut, separate, split', 'CÁT(làm vỡ,chia hai,cắt đứt,tổn hại)', 'cây đao có Hại là CÁT,cắt đứt tayHẠI: cái mồm phong(丰) phú trong nhà(miên) gây hại,có hạiHại Đao là Cát(cắt đứt)Hại(tổn hại):害Hạt(cai quản):轄Miên Thổ Khẩu Đao là Cát', ARRAY['カツ'], ARRAY['わ.る','わり','わ.り','わ.れる','さ.く'], 12, 318, (SELECT id FROM radicals WHERE character = '18')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('喝', 'N1', 'hoarse, scold', 'HÁT(quát mắng,uống,đe dọa)', 'Đang HÁT thì bị QUÁT vì Miệng có Mùi giữa ban ngàyKhát:渇Hạt(sắc nâu):褐Yết(yết kiến):謁Yết(niêm yết):掲', ARRAY['カツ'], NULL, 11, 1858, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
