INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('侃', 'BEYOND', 'strong, just, righteous, peace-loving', '', '', ARRAY['カン'], ARRAY['つよ.い'], 8, NULL, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('冠', 'N1', 'crown, best, peerless', 'QUÁN,QUAN(đứng đầu,cái mũ,quán quân)', 'QUán:quán quân mới(nguyên) Mịch nguyên thốn', ARRAY['カン'], ARRAY['かんむり'], 9, 1503, (SELECT id FROM radicals WHERE character = '14')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('寒', 'N3', 'cold', 'HÀN(trời lạnh,rét)', 'Dưới mái nhà, gió Hàn vẫn lùa qua dc 3 khe cửa sổ', ARRAY['カン'], ARRAY['さむ.い'], 12, 1456, (SELECT id FROM radicals WHERE character = '40')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('刊', 'N2', 'publish, carve, engrave', 'SAN(chặt,khắc,tước bỏ,xuất bản,nguyệt san)', 'Bụi đời chợ lớn phạm đến đao là san bằng tất cả,bị tước bỏcan đao sanGan(肝tim gan),Hãn(mồ hôi)汗:hãn huyết bảo mã', ARRAY['カン'], NULL, 5, 855, (SELECT id FROM radicals WHERE character = '18')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('勘', 'N1', 'intuition, perception, check, compare, sixth sense', 'KHÁM(so sánh,dò xét,khám xét,xem lại)', '4 lần dùng lực để bóp quả cam thì phải xem lại: KHÁM lại tayThậm(rất,lắm 甚) Lực: là KhámKham(chịu đựng):堪Cam Thất(匹) Lực là Khám', ARRAY['カン'], NULL, 11, 1494, (SELECT id FROM radicals WHERE character = '19')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('勧', 'N1', 'persuade, recommend, advise, encourage, offer', 'KHUYẾN(khuyến khích,khuyến cáo)', 'Khuyến khích người nằm ngang dùng lực chơi chimCHuy lực triệt:Khuyến Quan quyền Khuyến hoan xác có 1 bộ y nhau', ARRAY['カン','ケン'], ARRAY['すす.める'], 13, 1068, (SELECT id FROM radicals WHERE character = '19')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('巻', 'N2', 'scroll, volume, book, part, roll up, wind up, tie, coil, counter for texts (or book scrolls)', 'QUYỂN(cuốn,cuộn)', '2 người kỷ(tự mình) niệm nhau quyển sáchQuyển(Khí quyển) 圏Khoán(chứng khoán)券', ARRAY['カン','ケン'], ARRAY['ま.く','まき','ま.き'], 9, 944, (SELECT id FROM radicals WHERE character = '49')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('喚', 'N1', 'yell, cry, call, scream, summon', 'HOÁN(kêu,gọi,hô hoán)', 'Miệng lớn hô HOÁN tứ phíaHoán(hoán đổi):換', ARRAY['カン'], ARRAY['わめ.く'], 12, 1120, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('堪', 'N1', 'withstand, endure, support, resist', 'KHAM(cam chịu,chịu đựng)', 'THỔ thậm là Kham:để có đc một mảnh đất phải cam chịu bốn thời kì khổ sở', ARRAY['カン','タン'], ARRAY['た.える','たま.る','こら.える','こた.える'], 12, 1953, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('完', 'N3', 'perfect, completion, end', 'HOÀN(hoàn thành,đủ,vẹn,xong)', 'Nguyên 1 ngày trong nhà cũng hoàn thànhMiên nguyên hoàn thành', ARRAY['カン'], NULL, 7, 595, (SELECT id FROM radicals WHERE character = '40')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('官', 'N3', 'bureaucrat, the government, organ', 'QUAN(viên chức)', 'Người bụng to ở trong nhà là làm quan', ARRAY['カン'], NULL, 8, 230, (SELECT id FROM radicals WHERE character = '40')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('寛', 'N1', 'tolerant, leniency, generosity, relax, feel at home, be at ease, broadminded', 'KHOAN(khoan dung,nhân từ)', 'Xem hoa trong nhà thật là khoan khoáiMiên thảo kiến khoan dung', ARRAY['カン'], ARRAY['くつろ.ぐ','ひろ.い','ゆる.やか'], 13, 1377, (SELECT id FROM radicals WHERE character = '40')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('干', 'N2', 'dry, parch, ebb, recede, interfere, intercede', '', '', ARRAY['カン'], ARRAY['ほ.す','ほ.し-','-ぼ.し','ひ.る'], 3, 1349, (SELECT id FROM radicals WHERE character = '51')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('幹', 'N1', 'tree trunk, main part, talent, capability', 'CÁN(phần chính,cốt cán,tài cán,cán bộ,tài năng làm được việc)', 'Nhà của CÁN bộ thì SÁNG sớm lúc nào cũng KHÔ ráo乾乾:Thêm Khất là Can khô', ARRAY['カン'], ARRAY['みき'], 13, 364, (SELECT id FROM radicals WHERE character = '51')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('患', 'N2', 'afflicted, disease, suffer from, be ill', 'HOẠN(bị bệnh,lo,tại hoạn)', 'Xuyến Tâm là Hoạn giả(người bệnh)', ARRAY['カン'], ARRAY['わずら.う'], 11, 796, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('感', 'N3', 'emotion, feeling, sensation', 'CẢM(cảm giác,cảm hóa)', 'Hàm(咸:khắp cả,bao hàm) Tâm là Cảm giác.Qua Nhất Khẩu Tâm là Cảm giác.憾:Thêm Tâm là Hám(đắng,khổn khổ).減:Bỏ tâm thêm Thủy là Giảm(giảm cân,giảm thiểu)', ARRAY['カン'], NULL, 13, 233, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('慣', 'N3', 'accustomed, get used to, become experienced', 'QUÁN(tập quán,quen với)', 'Tâm Quán(貫:dây xâu tiền:nhật quán:1 quan) là QUán(tập quán).Có ruộng và tiền sẽ quán triệt được tất', ARRAY['カン'], ARRAY['な.れる','な.らす'], 14, 1177, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('憾', 'N1', 'remorse, regret, be sorry', 'HÁM(ăn năn,tiếc)', 'Tâm Cảm(感:cảm giác) là Hám(ăn năn).Giảm,hàm:咸:đầy đủ,mặn .Tâm HÁM sắc sẽ phải hối TIẾC', ARRAY['カン'], ARRAY['うら.む'], 16, 1682, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('換', 'N2', 'interchange, period, change, convert, replace, renew', 'HOÁN(đổi,thay thế)', 'Thủ Hoán(rực rỡ: 奐) là Hoán đổi.喚:Thêm khẩu là hô Hoán', ARRAY['カン'], ARRAY['か.える','-か.える','か.わる'], 12, 687, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('敢', 'N1', 'daring, brave, bold, sad, tragic, pitiful', 'CẢM(dũng cảm,tiến lên,bạo dạn,dám)', 'Công Nhĩ Phộc là Cảm.Người làm Công (工) bị Đánh (攵) vào Tai (耳) thì sẽ dũng Cảm đứng lên.厳:Thêm Nghiễm và 2 vạch là Nghiêm túc', ARRAY['カン'], ARRAY['あ.えて','あ.えない','あ.えず'], 12, 1859, (SELECT id FROM radicals WHERE character = '66')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('柑', 'BEYOND', 'citrus, orange', '', '', ARRAY['コン','カン'], NULL, 9, NULL, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('棺', 'N1', 'coffin, casket', 'QUAN(quan tài)', 'Mộc QUan(viên chức,quan lại:官) là Quan tài.', ARRAY['カン'], NULL, 12, 2161, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('款', 'N1', 'goodwill, article, section, friendship, collusion', 'KHOẢN(điều khoản,thành thực,khẩn khoản)', 'Sĩ Thị Khiếm là Khoản.Binh sĩ ở thành Thị không thiếu Điều Khoản gì', ARRAY['カン'], NULL, 12, 1854, (SELECT id FROM radicals WHERE character = '76')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('歓', 'N1', 'delight, joy', 'HOAN(hoan nghênh)', 'Triệt Chuy Khiếm là Hoan hô.権:Thay Mộc là Quyền lợi.勧:Thay Lực là Khuyến khích.', ARRAY['カン'], ARRAY['よろこ.ぶ'], 15, 1065, (SELECT id FROM radicals WHERE character = '76')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('汗', 'N2', 'sweat, perspire', 'HÃN(mồ hôi)', 'Thủy Can là Hãn.Hãn huyết bảo mã.lúc Khô nóng mồ hôi chảy như Nước', ARRAY['カン'], ARRAY['あせ'], 6, 1502, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('漢', 'N4', 'Sino-, China', 'HÁN(chữ Hán)', '難:Thay Chuy là gian Nan嘆:Thay Khẩu là ca Thán.', ARRAY['カン'], NULL, 13, 1487, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('環', 'N1', 'ring, circle, loop', 'HOÀN(vòng quanh,vòng ngọc,hoàn cảnh)', 'Vương Võng Nhất Khẩu Y là Hoàn vòng ngọc.還:Thay Sước là Hoàn trả.', ARRAY['カン'], ARRAY['わ'], 17, 409, (SELECT id FROM radicals WHERE character = '96')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('甘', 'N2', 'sweet, coax, pamper, be content, sugary', '', '', ARRAY['カン'], ARRAY['あま.い','あま.える','あま.やかす','うま.い'], 5, 1248, (SELECT id FROM radicals WHERE character = '99')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('監', 'N1', 'oversee, official, govt office, rule, administer', 'GIÁM(giám sát,coi sóc,giám đốc)', 'Thần Triệt Chủ Mãnh là Giám sát.Một vị thần nằm trên bát đĩa trong coi nhà bếp.濫:Thêm Thủy là Lạm phát.藍:Thêm Thảo là Lam(màu chàm).鑑:Thêm Kim là Giám(gươm).艦:Thêm Châu là chiến Hạm.', ARRAY['カン'], NULL, 15, 408, (SELECT id FROM radicals WHERE character = '108')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('看', 'N1', 'watch over, see', 'KHÁN(xem,đối đãi,khán giả)', 'Thủ MỤc là Khán giả.Khán giả mắt vừa xem tay giơ lên vỗ tay hưởng ứng.', ARRAY['カン'], ARRAY['み.る'], 9, 1060, (SELECT id FROM radicals WHERE character = '109')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('竿', 'BEYOND', 'pole, rod, scale beam, violin neck', '', '', ARRAY['カン'], ARRAY['さお'], 9, 2416, (SELECT id FROM radicals WHERE character = '118')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('管', 'N2', 'pipe, tube, wind instrument, drunken talk, control, jurisdiction', 'QUẢN(quản lý,ống)', 'Trúc Quan là Quản lý.QUAN dùng gậy TRÚC để QUẢN lý mọi người.棺:Thay Mộc là Quan tài.館:Thay Thực là hội Quán.', ARRAY['カン'], ARRAY['くだ'], 14, 517, (SELECT id FROM radicals WHERE character = '118')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('簡', 'N2', 'simplicity, brevity', 'GIẢN(đơn giản)', 'Trúc Gian là Giản thẻ tre.Không GIAN mà toàn làm bằng TRÚC TRE thì thật là đơn GIẢN', ARRAY['カン','ケン'], ARRAY['えら.ぶ','ふだ'], 18, 983, (SELECT id FROM radicals WHERE character = '118')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('緩', 'N1', 'slacken, loosen, relax, lessen, be moderate, ease', 'HOÃN(nới lỏng,hòa hoãn)', 'Mịch VIên(chưng ấy,bèn,VIên thư:爰Mịch Nhất Hữu)là Hoãn nới lỏng.Dây kéo dài trì hoãn việc ban phát cho bằng hữu.暖:Thay Nhật là Noãn(ấm nóng).援:Thay THủ là Viện trợ.媛:Thay Nữ là Viện(gái đẹp,kỹ viện)', ARRAY['カン'], ARRAY['ゆる.い','ゆる.やか','ゆる.む','ゆる.める'], 15, 933, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('缶', 'N2', 'tin can, container, jar radical (no. 121)', '', '', ARRAY['カン'], ARRAY['かま'], 6, 1543, (SELECT id FROM radicals WHERE character = '121')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('肝', 'N1', 'liver, pluck, nerve, chutzpah', 'CAN(lá gan)', 'Nhục Can là Can gan.pp mổ gan khô gs.TTT', ARRAY['カン'], ARRAY['きも'], 7, 1118, (SELECT id FROM radicals WHERE character = '130')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('艦', 'N1', 'warship', 'HẠM(tàu chiến)', 'Chu GIam,Giám(nhà tù,coi sóc: 監Thần Phiệt Nhất Mãnh)là Hạm đội.tàu chiến.', ARRAY['カン'], NULL, 21, 1363, (SELECT id FROM radicals WHERE character = '137')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('莞', 'BEYOND', 'smiling, reed used to cover tatami', '', '', ARRAY['カン'], ARRAY['い'], 10, NULL, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('観', 'N3', 'outlook, look, appearance, condition, view', 'QUAN(quan sát,nhìn)', 'Dùng MẮT QUAN sát vẻ ngoài của con CHIM đang nằm.Quan sát liên hoan chim,権:Thay Mộc là Quyền lợi.勧:Thay Lực là Khuyến cáo.歓:Thay Khiếm là Hoan hỉ.確:Thay Thạch là Xác nhận.', ARRAY['カン'], ARRAY['み.る','しめ.す'], 18, 476, (SELECT id FROM radicals WHERE character = '147')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('貫', 'N1', 'pierce, 8 1/3lbs, penetrate, brace', 'QUÁN(quán triệt)', 'Vô Bối là Quán triệt,Cái dây xâu tiền.Có ruộng và tiền sẽ quán triệt được tất.慣:Thêm Tâm là tập Quán', ARRAY['カン'], ARRAY['つらぬ.く','ぬ.く','ぬき'], 11, 1156, (SELECT id FROM radicals WHERE character = '154')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('還', 'N1', 'send back, return', 'HOÀN(trờ về,trả lại)', 'Sước Võng Nhất Khẩu Y là Hoàn trả.環:Thay Ngọc là Hoàn(vòng tròn)', ARRAY['カン'], ARRAY['かえ.る'], 16, 910, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鑑', 'N1', 'specimen, take warning from, learn from', 'GIÁM(gương mẫu,gương)', 'Kim Giam,Giám là Giám (giám định,gương soi)', ARRAY['カン'], ARRAY['かんが.みる','かがみ'], 23, 1391, (SELECT id FROM radicals WHERE character = '167')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('間', 'N5', 'interval, space', 'GIAN(thời gian)', '', ARRAY['カン','ケン'], ARRAY['あいだ','ま','あい'], 12, 33, (SELECT id FROM radicals WHERE character = '169')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('閑', 'N1', 'leisure', 'NHÀN(nghỉ ngơi)', 'Môn Mộc là Nhàn rỗi,an nhàn.Nhàn rỗi nên trồng cây ở cổng', ARRAY['カン'], NULL, 12, 1994, (SELECT id FROM radicals WHERE character = '169')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('関', 'N3', 'connection, barrier, gateway, involve, concerning', 'QUAN(liên quan)', 'Môn Quan(关) là Quan:liên quan', ARRAY['カン'], ARRAY['せき','-ぜき','かか.わる','からくり','かんぬき'], 14, 70, (SELECT id FROM radicals WHERE character = '169')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('陥', 'N1', 'collapse, fall into, cave in, fall (castle), slide into', 'HÃM(rơi vào bẫy,hãm hại)', 'Phụ Đao Cựu(旧) là Hãm hại,vây hãm.', ARRAY['カン'], ARRAY['おちい.る','おとしい.れる'], 10, 1154, (SELECT id FROM radicals WHERE character = '170')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('韓', 'N2', 'Korea', 'HÀN(hàn quốc)', '20 ngày (十日十) VI(韋)hành của vua HÀN quốc.Cán(幹) bộ Hàn quốc Vi hành.衛:Thay Hành là Vệ tinh.緯:Thay Mịch là Vĩ độ.偉:Thay Nhân là Vĩ nhân.違:Thay Sước là Vi(sai khác).', ARRAY['カン'], ARRAY['から','いげた'], 18, 445, (SELECT id FROM radicals WHERE character = '178')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('館', 'N4', 'building, mansion, large building, palace', 'QUÁN(tòa nhà)', 'Thực Quan là Quán:quán trọ,hội quán.', ARRAY['カン'], ARRAY['やかた','たて'], 16, 613, (SELECT id FROM radicals WHERE character = '184')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('丸', 'N2', 'round, full (month), perfection, -ship, pills, make round, roll up, curl up, seduce, explain away', 'HOÀN(tròn,viên)', '9 Chủ của Hoàn', ARRAY['ガン'], ARRAY['まる','まる.める','まる.い'], 3, 542, (SELECT id FROM radicals WHERE character = '3')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('含', 'N2', 'contain, include, hold in the mouth, bear in mind, understand, cherish', 'HÀM(bao gồm,ngậm)', 'KIm khẩu:Hàm:Ngậm Kim trong mồmKIM(bây giờ: 今)Khẩu là HÀM số.nội hàm', ARRAY['ガン'], ARRAY['ふく.む','ふく.める'], 7, 466, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('岸', 'N2', 'beach', 'NGẠN(bờ biển,bờ)', 'Bờ biển thì chẳng liên Can đến Núi.Sơn Hán Can là Ngạn', ARRAY['ガン'], ARRAY['きし'], 8, 556, (SELECT id FROM radicals WHERE character = '46')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('巌', 'BEYOND', 'rock, crag, boulder', '', '', ARRAY['ガン'], ARRAY['いわ','いわお','けわ.しい'], 20, 1986, (SELECT id FROM radicals WHERE character = '46')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('玩', 'N1', 'play, take pleasure in, trifle with, make sport of', 'NGOẠN(đồ chơi,du ngoạn)', 'Vương Nguyên là Ngoạn(du ngoạn)Vua Nguyên du NGOẠN đó đây', ARRAY['ガン'], ARRAY['もちあそ.ぶ','もてあそ.ぶ'], 8, 2216, (SELECT id FROM radicals WHERE character = '96')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('眼', 'N1', 'eyeball', 'NHÃN(con mắt)', 'Mục Cấn là Nhãn mắt.', ARRAY['ガン','ゲン'], ARRAY['まなこ','め'], 11, 1527, (SELECT id FROM radicals WHERE character = '109')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('岩', 'N2', 'boulder, rock, cliff', 'NHAM(tảng đá,nham thạch)', 'Đá ở dưới núi là dung nham hoá thạch', ARRAY['ガン'], ARRAY['いわ'], 8, 787, (SELECT id FROM radicals WHERE character = '46')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('雁', 'BEYOND', 'wild goose', '', '', ARRAY['ガン'], ARRAY['かり','かりがね'], 12, 2192, (SELECT id FROM radicals WHERE character = '172')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('頑', 'N1', 'stubborn, foolish, firmly', 'NGOAN(bướng bỉnh,ngoan cố)', 'Nguyên Hiệt là Ngoan cố,ương ngạnh.Cái đầu nguyên sơ thể hiện sự ngoan cường mạnh mẽ', ARRAY['ガン'], ARRAY['かたく.な'], 13, 1247, (SELECT id FROM radicals WHERE character = '181')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('顔', 'N3', 'face, expression', 'NHAN(khuôn mặt)', 'Lập Hán Sam Hiệt là Nhan:khuông mặt,dung nhan.', ARRAY['ガン'], ARRAY['かお'], 18, 676, (SELECT id FROM radicals WHERE character = '181')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('願', 'N3', 'petition, request, vow, wish, hope', 'NGUYỆN(xin,cầu nguyện)', 'Nguyên(cánh đồng,thảo nguyên:原)Hiệt là Nguyện:muốn,ao ước.Nguyên viết ước NGUYỆN vào tờ Giấy.', ARRAY['ガン'], ARRAY['ねが.う','-ねがい'], 19, 894, (SELECT id FROM radicals WHERE character = '181')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('企', 'N1', 'undertake, scheme, design, attempt, plan', 'XÍ(Kế hoạch)', 'Nhân Chỉ(dừng lại) Xí là có Xí(kế hoạch)', ARRAY['キ'], ARRAY['くわだ.てる','たくら.む'], 6, 278, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('伎', 'N1', 'deed, skill', 'KĨ(Tài. Con nhà nghề.Kỹ xảo)', 'Nhân Chi KỶ:kỹ năng.tài', ARRAY['ギ','キ'], ARRAY['わざ','わざおぎ'], 6, NULL, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('危', 'N3', 'dangerous, fear, uneasy', 'NGUY(lo sợ,nguy hiểm,nghi ngờ)', 'Nguy:nguy hiểm: chữ ÁCH(厄:hán tiết: tai ương) và cái mũ', ARRAY['キ'], ARRAY['あぶ.ない','あや.うい','あや.ぶむ'], 6, 606, (SELECT id FROM radicals WHERE character = '26')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('喜', 'N3', 'rejoice, take pleasure in', 'HỈ(mừng,vui mừng,việc tốt lành)', 'Cát Thảo Khẩu:Hỉ :miệng nói lời may mắn và trao nhẫn cỏ:HỈ', ARRAY['キ'], ARRAY['よろこ.ぶ','よろこ.ばす'], 12, 769, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
