INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('既', 'N1', 'previously, already, long ago', 'KÍ(đã,rồi)', 'Cấn Kí(nấc:旡) là Kí.cho dù có lấn CẤN hoài cái việc tăng KÍ thì kí cũng ĐÃ tăng RỒI.慨:Thêm Tâm là Khái(khẳng khái).概:Thêm Mộc là Khái niệm.', ARRAY['キ'], ARRAY['すで.に'], 10, 1081, (SELECT id FROM radicals WHERE character = '71')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('期', 'N3', 'period, time, date, term', 'KÌ(kì hạn,ắt thế, mong mỏi)', 'Kì(cái đó:其) Nguyệt là Kì hạn.', ARRAY['キ','ゴ'], NULL, 12, 117, (SELECT id FROM radicals WHERE character = '74')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
