INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('軌', 'N1', 'rut, wheel, track, model, way of doing', 'QUỸ(quỹ đạo)', 'Xa Cửu là Quỹ đạo.XE (車) chạy 9 (九) vòng QUỸ (軌) đạo', ARRAY['キ'], NULL, 9, 1480, (SELECT id FROM radicals WHERE character = '159')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('輝', 'N1', 'radiance, shine, sparkle, gleam, twinkle', 'HUY(chiếu sáng)', 'Quang Quân là Huy sáng sủa,rực rỡ.', ARRAY['キ'], ARRAY['かがや.く'], 15, 1259, (SELECT id FROM radicals WHERE character = '159')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('飢', 'N1', 'hungry, starve', 'CƠ(đói khát)', 'Thực Kỉ là Cơ:đói khát.CƠ thể đói quá ăn luôn cả GHẾ.', ARRAY['キ'], ARRAY['う.える'], 10, 1659, (SELECT id FROM radicals WHERE character = '184')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('騎', 'N1', 'equestrian, riding on horses, counter for equestrians', 'KỊ(cưỡi ngựa)', 'Mã Kì(lạ:奇Đại Khả)là Kị mã:cưỡi ngựa.Người lớn có khả năng cưỡi ngựa là kị binh', ARRAY['キ'], NULL, 18, 1696, (SELECT id FROM radicals WHERE character = '187')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鬼', 'N1', 'ghost, devil', '', '', ARRAY['キ'], ARRAY['おに','おに-'], 10, 1557, (SELECT id FROM radicals WHERE character = '194')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('亀', 'N1', 'tortoise, turtle', 'QUY(rùa)', 'Đầu nhọn có đuôi, giáp trên giáp dưới縄:thay Mịch là Thằng(sợi dây)', ARRAY['キ','キュウ','キン'], ARRAY['かめ'], 11, 1353, (SELECT id FROM radicals WHERE character = '5')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('偽', 'N1', 'falsehood, lie, deceive, pretend, counterfeit, forgery', '', '', ARRAY['ギ','カ'], ARRAY['いつわ.る','にせ','いつわ.り'], 11, 1171, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('儀', 'N1', 'ceremony, rule, affair, case, a matter', 'NGHI(dáng,làm mẫu,đồ lễ,lễ nghi)', 'nhân dương ngã(我) là NGHI lễNghĩa(nghĩa khí:義) Nghị(hội nghị:議) Nghi Hi(hi sinh:犠)', ARRAY['ギ'], NULL, 15, 739, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('宜', 'N1', 'best regards, good', 'NGHI(tốt,thích đáng,nên)', 'Thả trong ngôi Nhà tiện NGHI', ARRAY['ギ'], ARRAY['よろ.しい','よろ.しく'], 8, 1766, (SELECT id FROM radicals WHERE character = '40')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('戯', 'N1', 'frolic, play, sport', 'HÍ(đùa giỡn)', 'Hư(không có thực,hư ảo,hư không) Qua là Hí.Hư:Hô Nghiệp(业)', ARRAY['ギ','ゲ'], ARRAY['たわむ.れる','ざ.れる','じゃ.れる'], 15, 1880, (SELECT id FROM radicals WHERE character = '62')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('技', 'N2', 'skill, art, craft, ability, feat, performance, vocation, arts', 'KỸ(kỹ thuật)', 'Thủ Chi là Kỹ thuật.Tay chi tiết thể hiện kỹ thuật', ARRAY['ギ'], ARRAY['わざ'], 7, 434, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('擬', 'N1', 'mimic, aim (a gun) at, nominate, imitate', 'NGHĨ(phỏng theo)', 'Thủ Nghi(疑:nghi ngờ)Chủy ất thỉ sơ là Nghĩ.Còn nghi ngờ gì nữa hãy bắt tay làm theo những gì bạn NGHĨ.凝:Thêm Băng là Ngưng đọng.', ARRAY['ギ'], ARRAY['まが.い','もど.き'], 17, 1990, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('欺', 'N1', 'deceit, cheat, delude', 'KHI(lừa dối)', 'Kì,Ki(cái đó:其) Khiếm là KHi lừa dối.KHI đến Kì mà Thiếu nợ thì hay LỪA DỐI', ARRAY['ギ'], ARRAY['あざむ.く'], 12, 1541, (SELECT id FROM radicals WHERE character = '76')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('犠', 'N1', 'sacrifice', 'Hy(hy sinh)', 'Ngưu Nghĩa(công lý:義,dương Ngã(ta,tôi:我)) là Hy sinh.儀:Thay Nhân là Nghi lễ.議:Thay Ngôn là hội Nghị.', ARRAY['ギ','キ'], ARRAY['いけにえ'], 17, 1189, (SELECT id FROM radicals WHERE character = '93')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('疑', 'N3', 'doubt, distrust, be suspicious, question', 'NGHI(nghi ngờ)', 'Chủy ất thỉ sơ là Nghi ngờ.擬:Thêm Thủ là Nghĩ(làm theo).凝:Thêm Băng là Ngưng đọng.', ARRAY['ギ'], ARRAY['うたが.う'], 14, 283, (SELECT id FROM radicals WHERE character = '103')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('祇', 'BEYOND', 'national or local god, peaceful, great', '', '', ARRAY['ギ','キ','シ'], ARRAY['くにつかみ','ただ','まさに'], 8, 2169, (SELECT id FROM radicals WHERE character = '113')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('義', 'N1', 'righteousness, justice, morality, honor, loyalty, meaning', 'NGHĨA(nghĩa vụ,bất nghĩa)', 'Dương Ngã(ta:我Triệt Qua Quyết)là Nghĩa:Bất nghĩa.Con cừu vì chính nghĩa mã bị ngã', ARRAY['ギ'], NULL, 13, 415, (SELECT id FROM radicals WHERE character = '123')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('誼', 'BEYOND', 'friendship, intimacy', '', '', ARRAY['ギ'], ARRAY['よしみ','よい'], 15, NULL, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('議', 'N3', 'deliberation, consultation, debate, consideration', 'NGHỊ(hội nghị)', 'Ngôn Nghĩa(lẻ phải,công lý:義Dương Ngã)là Nghị trường.Dị nghị:phản đối.儀:Thay Nhân là Nghi lễ.犠:Thay Ngưu là Hi sinh.', ARRAY['ギ'], NULL, 20, 25, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('掬', 'BEYOND', 'scoop up water with the hand', '', '', ARRAY['キク','コク'], ARRAY['きく.す','むす.ぶ','すく.う','たなごころ'], 11, NULL, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('菊', 'N1', 'chrysanthemum', 'CÚC(hoa cúc)', 'Thảo Bao Mễ là Cúc hoa cúc.Ngày xưa hoa cúc đc trồng bao quanh lúa', ARRAY['キク'], NULL, 11, 1287, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鞠', 'BEYOND', 'ball', '', '', ARRAY['キク','キュウ'], ARRAY['まり'], 17, NULL, (SELECT id FROM radicals WHERE character = '177')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('吉', 'N1', 'good luck, joy, congratulations', '&nbsp;CÁT(may mắn,tốt lành)', 'học trò đi chúc tết(bằng lời nói) là CÁT lợi cát anh(may mắn)', ARRAY['キチ','キツ'], ARRAY['よし'], 6, 711, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('喫', 'N2', 'consume, eat, drink, smoke, receive (a blow)', 'KHIẾT(ăn uống,nhận vào)', 'người KHIẾT đan(đao to búa lớn,đất đai nhiều):Khẩu Khế,có khế ước miệng thoải mái "ăn uống"Khế(khế ước)契:thêm khẩu là KHiết đan', ARRAY['キツ'], ARRAY['の.む'], 12, 1347, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('桔', 'BEYOND', 'used in plant names', '', '', ARRAY['キツ','ケツ'], NULL, 10, NULL, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('橘', 'BEYOND', 'mandarin orange', '', '', ARRAY['キツ'], ARRAY['たちばな'], 16, 2053, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('詰', 'N2', 'packed, close, pressed, reprove, rebuke, blame', 'CẬT(nhồi,nhét,thẩm tra,cật lực)', 'Ngôn Cát là Cật vặn hỏi.Phát ngôn như nhét Cát vào mồm người khác', ARRAY['キツ','キチ'], ARRAY['つ.める','つ.め','-づ.め','つ.まる','つ.む'], 13, 1020, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('砧', 'BEYOND', 'fulling block', '', '', ARRAY['チン'], ARRAY['きぬた'], 10, NULL, (SELECT id FROM radicals WHERE character = '112')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('杵', 'BEYOND', 'wooden pestle', '', '', ARRAY['ショ','ソ'], ARRAY['きね'], 8, 2355, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('却', 'N1', 'instead, on the contrary, rather, step back, withdraw, retreat', 'KHƯỚC(ngược lại,khước từ)', 'Khứ tiết là khước mặt sơn quán,khước từCước(cú đá):脚', ARRAY['キャク'], ARRAY['かえ.って','しりぞ.く','しりぞ.ける'], 7, 959, (SELECT id FROM radicals WHERE character = '26')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('客', 'N3', 'guest, visitor, customer, client', 'KHÁCH(khách hàng)', 'Miên Các là Khách:Các vị khách đang ngồi trong nhà', ARRAY['キャク','カク'], NULL, 9, 557, (SELECT id FROM radicals WHERE character = '40')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('脚', 'N1', 'skids, leg, undercarriage, lower part, base', 'CƯỚC(cái chân)', 'Nhục Khước(khước từ,ngược lại)là Cước chân.', ARRAY['キャク','キャ','カク'], ARRAY['あし'], 11, 1228, (SELECT id FROM radicals WHERE character = '130')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('虐', 'N1', 'tyrannize, oppress', 'NGƯỢC(ngược đãi,áp chế)', 'Chữ E giống con dao. Lấy dao chặt chân con hổ 虎 là ngược đãi nó.', ARRAY['ギャク'], ARRAY['しいた.げる'], 9, 1464, (SELECT id FROM radicals WHERE character = '141')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('逆', 'N2', 'inverted, reverse, opposite, wicked', 'NGHỊCH(ngược lại)', 'Sước Thảo Triệt là Nghịch đảo.trái塑:Thêm Nguyệt Thổ là Tố(đắp tượng).遡:Thêm Sước Nhục là Tố(ngược dòng).', ARRAY['ギャク','ゲキ'], ARRAY['さか','さか.さ','さか.らう'], 9, 683, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('丘', 'N1', 'hill, knoll', 'KHÂU(cái gò,đống đất nhỏ)', 'ngọn đồi rất gần với mặt đất', ARRAY['キュウ'], ARRAY['おか'], 5, 1405, (SELECT id FROM radicals WHERE character = '1')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('久', 'N2', 'long time, old story', 'CỬU(Lâu,đợi)', 'ク (KƯ) thêm cây gậy thì thành vĩnh Cửu', ARRAY['キュウ','ク'], ARRAY['ひさ.しい'], 3, 688, (SELECT id FROM radicals WHERE character = '4')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('休', 'N5', 'rest, day off, retire, sleep', 'HƯU(Tốt lành. Nghỉ ngơi. Thôi nghỉ. Về nghỉ. Cái tờ bỏ vợ gọi là hưu thư)', 'Người 亻ngồi dưới gốc Cây 木 để Nghỉ Ngơi 休.', ARRAY['キュウ'], ARRAY['やす.む','やす.まる','やす.める'], 6, 642, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('及', 'N1', 'reach out, exert, exercise, cause', 'CẬP(kịp,đến,bằng,cùng,phổ cập,và)', 'Phổ CẬP cho 3 người', ARRAY['キュウ'], ARRAY['およ.ぶ','およ.び','および','およ.ぼす'], 3, 544, (SELECT id FROM radicals WHERE character = '29')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('吸', 'N3', 'suck, imbibe, inhale, sip', 'HẤP(hít,hút,bú)', '3 thằng Hấp(hít,hút) hít bồ đà người run lập cập(3 ng:cập:kịp,đến,bằng,cùng,phổ cậpKhẩu Cập là Hấp', ARRAY['キュウ'], ARRAY['す.う'], 6, 1054, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('宮', 'N1', 'Shinto shrine, constellations, palace, princess', 'CUNG(cung điện,đền)', 'Miên Lữ là CUng điện', ARRAY['キュウ','グウ','ク','クウ'], ARRAY['みや'], 10, 367, (SELECT id FROM radicals WHERE character = '40')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('弓', 'N1', 'bow, bow (archery, violin)', '', '', ARRAY['キュウ'], ARRAY['ゆみ'], 3, 1802, (SELECT id FROM radicals WHERE character = '57')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('急', 'N4', 'hurry, emergency, sudden, steep', 'CẤP(gấp,vội vàng,kíp)', 'Sô(cỏ khô: 刍)(đao ký,kệ) Tâm là Cấp(khẩn cấp)', ARRAY['キュウ'], ARRAY['いそ.ぐ','いそ.ぎ','せ.く'], 9, 309, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('救', 'N1', 'salvation, save, help, rescue, reclaim', 'CỨU(cứu giúp)', 'Cầu(yêu cầu:求) Phộc là CỨu giúp.Ông Phộc (攵) Cầu (求) Cứu (救).球:Thêm Vương là địa Cầu', ARRAY['キュウ'], ARRAY['すく.う'], 11, 799, (SELECT id FROM radicals WHERE character = '66')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('朽', 'N1', 'decay, rot, remain in seclusion', 'HỦ(mục nát,hủ tục)', 'Mộc Khảo(丂) là Hủ tục bắt vợ.cây này đã sống 5 năm rồi nên giờ nó bị mục nát...', ARRAY['キュウ'], ARRAY['く.ちる'], 6, 1891, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('求', 'N3', 'request, want, wish for, require, demand', 'CẦU(yêu cầu,tìm,xin)', 'Thời xưa lập đàn cầu mưa 10 ngày mới có nước.球:Thêm Vương là địa Cầu.救:Thêm Phốc là CỨu(cấp cứu)', ARRAY['キュウ','グ'], ARRAY['もと.める'], 7, 220, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('汲', 'BEYOND', 'draw (water), ladle, scoop, pump', '', '', ARRAY['キュウ'], ARRAY['く.む'], 7, NULL, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('泣', 'N1', 'cry, weep, moan', 'KHẤP(khóc)', 'Thủy Lập Khấp khóc.Thủy đứng khóc.', ARRAY['キュウ'], ARRAY['な.く'], 8, 1380, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('灸', 'BEYOND', 'moxa cautery, chastisement', '', '', ARRAY['キュウ','ク'], ARRAY['やいと'], 7, NULL, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('球', 'N3', 'ball, sphere', 'CẦU(hình cầu)', 'Ngọc Cầu(求:cầu xin) là Cầu vồng.Góc Nhìn: ông Vua (王) Cầu nguyện (求)==&gt; được sống lâu như quả địa Cầu (球)', ARRAY['キュウ'], ARRAY['たま'], 11, 302, (SELECT id FROM radicals WHERE character = '96')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('究', 'N4', 'research, study', 'CỨU(nghiên cứu,tìm tòi)', 'Huyệt Cửu là Cứu nghiên cứu.phải là nghiên cứu 9 năm trong hang hợp hơn', ARRAY['キュウ','ク'], ARRAY['きわ.める'], 7, 368, (SELECT id FROM radicals WHERE character = '116')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('窮', 'N1', 'hard up, destitute, suffer, perplexed, cornered', 'CÙNG(cùng cực,hết)', 'Huyệt Cung(thân mình:躬Thân Cung)là CÙng cực.Bắn cung vào thân, chết nằm dưới huyệt sâu tận cùng', ARRAY['キュウ','キョウ'], ARRAY['きわ.める','きわ.まる','きわ.まり','きわ.み'], 15, 1756, (SELECT id FROM radicals WHERE character = '116')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('笈', 'BEYOND', 'backpack bookcase', '', '', ARRAY['キュウ'], NULL, 9, NULL, (SELECT id FROM radicals WHERE character = '118')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('級', 'N1', 'class, rank, grade', 'CẤP(cấp bậc)', 'Mịch Cập là Cấp bậc.', ARRAY['キュウ'], NULL, 9, 785, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('糾', 'N1', 'twist, ask, investigate, verify', 'CỦ(xem xét)', '4 sợi dây làm nên quy củ.収:Thay Hựu là Thu nhập叫:Thay Khẩu là KHiếu(hét,la mắng)', ARRAY['キュウ'], ARRAY['ただ.す'], 9, 1820, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('給', 'N3', 'salary, wage, gift, allow, grant, bestow on', 'CẤP(cung cấp)', 'Mịch Hợp là Cấp cung cấp.Tập hợp các Sợi Tơ lại để Cung Cấp cho xí nghiệp dệt vải', ARRAY['キュウ'], ARRAY['たま.う','たも.う','-たま.え'], 12, 615, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('旧', 'N2', 'old times, old things, old friend, former, ex-', 'CỰU(kỳ cựu,cũ)', 'Nhất Nhật CỰu児:Thêm Nhân là Nhi đồng.', ARRAY['キュウ'], ARRAY['ふる.い','もと'], 5, 549, (SELECT id FROM radicals WHERE character = '72')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('牛', 'N4', 'cow', '', '', ARRAY['ギュウ'], ARRAY['うし'], 4, 1202, (SELECT id FROM radicals WHERE character = '93')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('去', 'N4', 'gone, past, quit, leave, elapse, eliminate, divorce', 'KHỨ(lìa bỏ,quá khứ,đã qua)', 'Chôn chuyện quá KHỨ,riêng tư xuống đất đi', ARRAY['キョ','コ'], ARRAY['さ.る','-さ.る'], 5, 440, (SELECT id FROM radicals WHERE character = '28')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('居', 'N3', 'reside, to be, exist, live with', 'CƯ(ở,hiện diện,tích chứa,ẩn cư)', 'Thi Cổ là Cư(ẩn cư)Con ma cư trú trong nhà cổ', ARRAY['キョ','コ'], ARRAY['い.る','-い','お.る'], 8, 836, (SELECT id FROM radicals WHERE character = '44')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('巨', 'N2', 'gigantic, big, large, great', 'CỰ(khổng lồ,lớn)', 'Chứ C to + chứ U quay ngược vào thành cự không dấu距:Thêm Túc là CỰ(cự li)拒:Thêm Thủ là Cự(kháng cự)', ARRAY['キョ'], NULL, 5, 892, (SELECT id FROM radicals WHERE character = '48')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('拒', 'N1', 'repel, refuse, reject, decline', 'CỰ(cự tuyệt,chống cự)', 'Thủ Cự(to) là Cự tuyệt.距:Thêm Túc là CỰ ly', ARRAY['キョ','ゴ'], ARRAY['こば.む'], 8, 863, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('拠', 'N1', 'foothold, based on, follow, therefore', 'CỨ(chứng cứ)', 'Thủ Xử(xử lý:処) là Cứ.Muốn xử lí 処 trong tay 扌 phải có chứng cứ 拠', ARRAY['キョ','コ'], ARRAY['よ.る'], 8, 858, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('挙', 'N1', 'raise, plan, project, behavior, actions', 'CỬ(cử hành,tuyển cử)', 'Quang Thủ là Cử hành誉:Thêm Ngôn DỰ(danh dự)', ARRAY['キョ'], ARRAY['あ.げる','あ.がる','こぞ.る'], 10, 257, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('虚', 'N1', 'void, emptiness, unpreparedness, crack, fissure, untruth', 'HƯ(hư không,khuyết)', 'Hô Nghiệp là Hư không.chức danh ảo.戯:Thêm Qua là Hí(du hí)', ARRAY['キョ','コ'], ARRAY['むな.しい','うつ.ろ'], 11, 1454, (SELECT id FROM radicals WHERE character = '141')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('許', 'N3', 'permit, approve', 'HỨA(tha thứ,cho phép)', 'Ngôn Ngọ là Hứa tha thứ.lời đã HỨA thì phải nhất NGÔN kí xuất tứ mã (NGỌ) nan truy', ARRAY['キョ'], ARRAY['ゆる.す','もと'], 11, 720, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('距', 'N1', 'long-distance, spur, fetlock', 'CỰ(cự li,cựa gà,tiêu cự)', 'Túc Cự,Há(lớn:巨)là Cự li,cựa gà.拒:Thay Thủ là kháng CỰ', ARRAY['キョ'], ARRAY['へだ.たる','けづめ'], 12, 1191, (SELECT id FROM radicals WHERE character = '157')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
