INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('競', 'N2', 'emulate, compete with, bid, sell at auction, bout, contest, race', 'CẠNH(cạnh tranh,ganh đua)', 'Lập Huynh x2 là Cạnh tranh', ARRAY['キョウ','ケイ'], ARRAY['きそ.う','せ.る','くら.べる'], 20, 610, (SELECT id FROM radicals WHERE character = '117')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('共', 'N3', 'together, both, neither, all, and, alike, with', 'CỘNG(cùng nhau,chung,cộng sự)', 'Cộng là 8 nhánh cỏ', ARRAY['キョウ'], ARRAY['とも','とも.に','-ども'], 6, 174, (SELECT id FROM radicals WHERE character = '12')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('凶', 'N1', 'villain, evil, bad luck, disaster', 'HUNG(dữ,ác,không tốt lành)', 'Há miệng đớp người tài giỏi(NGHỆ) là hung ác:cùng hung cực ác Vân Trung Hạc:Khảm nghệ là hung ácHung(ngực) :胸', ARRAY['キョウ'], NULL, 4, 1673, (SELECT id FROM radicals WHERE character = '17')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('協', 'N2', 'co-, cooperation', 'HIỆP(hòa hợp,giúp đỡ,hào hiệp,hiệp lực)', '3 nhân 10 hiệp lực sức mạnh', ARRAY['キョウ'], NULL, 8, 121, (SELECT id FROM radicals WHERE character = '24')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('匡', 'BEYOND', 'correct, save, assist', '', '', ARRAY['キョウ','オウ'], ARRAY['すく.う','ただ.す'], 6, 2176, (SELECT id FROM radicals WHERE character = '22')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
