INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('叫', 'N2', 'shout, exclaim, yell', 'KHIẾU(thét,kêu lên,gào)', 'Mồm kêu 4 tiếng :”mang rượu ra đê :sakebuKhóc khiếu(kêu gào):mồm 4', ARRAY['キョウ'], ARRAY['さけ.ぶ'], 6, 1426, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('喬', 'BEYOND', 'high, boasting', '', '', ARRAY['キョウ'], ARRAY['たか.い'], 12, 1962, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('境', 'N2', 'boundary, border, region', 'CẢNH(biên giới)', 'Đứng trên vùng đất ranh giới để ngắm CẢNHThổ lập nhật nhân Cảnh giới', ARRAY['キョウ','ケイ'], ARRAY['さかい'], 14, 346, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('峡', 'N1', 'gorge, ravine', 'HẠP(eo biển,hẻm núi)', 'khe núi không còn hẹp(狭い ）vì ko có chó.狭:Hiệp(hẹp)挟:Hiệp(kẹp)峡:Hạp(hẻm núi)', ARRAY['キョウ','コウ'], ARRAY['はざま'], 9, 1833, (SELECT id FROM radicals WHERE character = '46')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('強', 'N4', 'strong', 'CƯỜNG(mạnh,khỏe)', 'Cung Tư Trùng là CƯờng.Dùng cung tên bắn chết 4 (tư) con côn trùng khỏe mạnh', ARRAY['キョウ','ゴウ'], ARRAY['つよ.い','つよ.まる','つよ.める','し.いる','こわ.い'], 11, 112, (SELECT id FROM radicals WHERE character = '57')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('恐', 'N3', 'fear, dread, awe', 'KHỦNG(sợ hãi,khủng hoãng)', 'Công Phàm(thường) Tâm là KHủng hoảng.PHÀM là người làm CÔNG thì TÂM lúc nào cũng KHỦNG hoảng, lo sợ bị thất nghiệp', ARRAY['キョウ'], ARRAY['おそ.れる','おそ.る','おそ.ろしい','こわ.い','こわ.がる'], 10, 878, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('恭', 'N1', 'respect, reverent', 'CUNG(cung kính)', 'Công Tâm là Cung kính', ARRAY['キョウ'], ARRAY['うやうや.しい'], 10, 1737, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('挟', 'N2', 'pinch, between', 'HIỆP(kẹp)', 'Tay ông Chồng Đại HIỆP bị KẸP.狭:thêm Khuyển là Hiệp(hẹp).峡:Thêm Sơn là Hạp(hẻm núi).', ARRAY['キョウ','ショウ'], ARRAY['はさ.む','はさ.まる','わきばさ.む','さしはさ.む'], 9, 1870, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('教', 'N4', 'teach, faith, doctrine', 'GIÁO(giáo dục)', 'Hiếu Phộc là Giáo dục.ĐÁNH KHẺ để GIÁO dục con, chỉ mong sao con lấy chữ HIẾU làm Đầu.', ARRAY['キョウ'], ARRAY['おし.える','おそ.わる'], 11, 166, (SELECT id FROM radicals WHERE character = '66')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('橋', 'N2', 'bridge', 'KIỀU(cây cầu,muốn sang thì bắc cầu kiều)', 'Mộc Kiều(cao:喬) là Kiều(cầu).矯:Thêm Thỉ là Kiểu(nắn thẳng)', ARRAY['キョウ'], ARRAY['はし'], 16, 553, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('況', 'N2', 'condition, situation', 'HUỐNG(tình huống)', 'Thủy Huynh là Huống.Huynh gặp tình huống khó vã cả mồ hôi', ARRAY['キョウ'], ARRAY['まし.て','いわ.んや','おもむき'], 8, 490, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('狂', 'N1', 'lunatic, insane, crazy, confuse', 'CUỒNG(cuồng nhiệt,ngông cuồng)', 'Khuyển Vương là Cuồng dâm.Vua là con chó cuồng dâm.', ARRAY['キョウ'], ARRAY['くる.う','くる.おしい','くるお.しい'], 7, 1425, (SELECT id FROM radicals WHERE character = '94')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('狭', 'N1', 'cramped, narrow, contract, tight', 'HIỆP(hẹp)', 'thằng Chó giả Đại hiệp nhưng lòng dạ Hẹp hòi.挟:Thay Thủ là Hiệp(kẹp).峡:Thay Sơn là Hạp(hẻm núi).', ARRAY['キョウ','コウ'], ARRAY['せま.い','せば.める','せば.まる','さ'], 9, 1346, (SELECT id FROM radicals WHERE character = '94')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('矯', 'N1', 'rectify, straighten, correct, reform, cure, control, pretend, falsify', 'KIỂU(nắn thẳng)', 'Thỉ Kiều(cao)là Kiểu(làm thẳng ra).thúy KIỀU chỉ thích trai THẲNG như MŨI TÊN thôi.橋: Thay Mộc là Kiều cầu.', ARRAY['キョウ'], ARRAY['た.める'], 17, 2105, (SELECT id FROM radicals WHERE character = '111')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('胸', 'N2', 'bosom, breast, chest, heart, feelings', 'HUNG(ngực)', 'Nhục Hung(náo loạn,hung nô:匈Bao Hung)là Hung ngực.', ARRAY['キョウ'], ARRAY['むね','むな-'], 10, 1144, (SELECT id FROM radicals WHERE character = '130')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('脅', 'N1', 'threaten, coerce', 'HIẾP(đe dọa,sườn)', '3 Lực Nhục là Hiếp đe dọa.協:Thay Thập là Hiệp lực.脇:Thay Nhục là Hiếp(cái nách).', ARRAY['キョウ'], ARRAY['おびや.かす','おど.す','おど.かす'], 10, 1183, (SELECT id FROM radicals WHERE character = '130')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('興', 'N1', 'entertain, revive, retrieve, interest, pleasure', 'HƯNG(hưng thịnh)', 'Cửu Đồng Bát là Hưng thịnh.', ARRAY['コウ','キョウ'], ARRAY['おこ.る','おこ.す'], 16, 734, (SELECT id FROM radicals WHERE character = '134')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
