INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('郷', 'N1', 'home town, village, native place, district', 'HƯƠNG(làng quê,quê hương)', 'Hợi(亥) bỏ đầu Cấn Ấp là Hương (quê hương)', ARRAY['キョウ','ゴウ'], ARRAY['さと'], 11, 1077, (SELECT id FROM radicals WHERE character = '163')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鏡', 'N1', 'mirror, speculum, barrel-head, round rice-cake offering', 'KÍNH(cái gương)', 'Kim Cánh(trọn,hết,xong:竟Lập Kiến)là Kính(gương).境:Thay Thổ là hoàn Cảnh biên giới.', ARRAY['キョウ','ケイ'], ARRAY['かがみ'], 19, 1506, (SELECT id FROM radicals WHERE character = '167')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('響', 'N1', 'echo, sound, resound, ring, vibrate', 'HƯỞNG(ảnh hưởng,tiếng,vang)', 'Hương(quê hương:郷) Âm là Hưởng:tiếng,vang vọng.Âm thanh quê hương ảnh hưởng đến tôi', ARRAY['キョウ'], ARRAY['ひび.く'], 20, 502, (SELECT id FROM radicals WHERE character = '180')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('饗', 'BEYOND', 'banquet', '', '', ARRAY['キョウ'], ARRAY['う.ける','もてな.す'], 22, 2347, (SELECT id FROM radicals WHERE character = '184')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('驚', 'N1', 'wonder, be surprised, frightened, amazed', 'KINH(kinh ngạc,giật mình)', 'Kính(tôn kính:敬) Mã là Kinh ngạc.警:Thay Ngôn là Cảnh sát.', ARRAY['キョウ'], ARRAY['おどろ.く','おどろ.かす'], 22, 1141, (SELECT id FROM radicals WHERE character = '187')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('仰', 'N1', 'face-up, look up, depend, seek, respect, revere, drink, take', 'NGƯỠNG, NHẠNG(Ngửa, ngửa mặt lên gọi là ngưỡng)', 'Nhân Ngang(卬) :Ngưỡng:tôi là tôi CP', ARRAY['ギョウ','コウ'], ARRAY['あお.ぐ','おお.せ','お.っしゃる','おっしゃ.る'], 6, 1573, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('凝', 'N1', 'congeal, freeze, stiff, be absorbed in', 'NGƯNG(đọng lại,ngưng tụ,đông đặc)', 'Nghi ngờ thêm băng là ngưng đọngBăng Nghi(chủy ất thỉ sơ)= Ngưng NGhi(疑) thêm tay là Nghĩ(làm theo) 擬', ARRAY['ギョウ'], ARRAY['こ.る','こ.らす','こご.らす','こご.らせる','こご.る'], 16, 1712, (SELECT id FROM radicals WHERE character = '15')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('尭', 'BEYOND', 'high, far', '', '', ARRAY['ギョウ'], ARRAY['たか.い'], 8, 2136, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('暁', 'N1', 'daybreak, dawn, in the event', 'HIỂU(sáng sớm,bình minh)', 'Nhật Nghiêu(vua Nghiêu: 尭) là Hiểu.30 NGÀY ĐI tìm HIỂU bình minh.焼:Thêm Hỏa là THiêu đốt.', ARRAY['ギョウ','キョウ'], ARRAY['あかつき','さと.る'], 12, 1924, (SELECT id FROM radicals WHERE character = '72')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('業', 'N4', 'business, vocation, arts, performance', 'NGHIỆP(sự nghiệp)', '业 Thảo Vị là Nghiệp vụ.', ARRAY['ギョウ','ゴウ'], ARRAY['わざ'], 13, 43, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('局', 'N3', 'bureau, board, office, affair, conclusion, court lady, lady-in-waiting, her apartment', 'CỤC(bộ phận)', 'Thi Cú,Câu là CụcCÂU CÚ đọc cho người chết phải có bố CỤC rõ ràng', ARRAY['キョク'], ARRAY['つぼね'], 7, 286, (SELECT id FROM radicals WHERE character = '44')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('曲', 'N3', 'bend, music, melody, composition, pleasure, injustice, fault, curve, crooked, perverse, lean', 'KHÚC(bản nhac,uốn cong,khúc đoạn)', 'Kẻ vở ra 6 ô để viết khúc nhạc', ARRAY['キョク'], ARRAY['ま.がる','ま.げる','くま'], 6, 810, (SELECT id FROM radicals WHERE character = '73')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('極', 'N2', 'extreme, pole, extremely, very, highly, most, end, settlement, conclusion, highest rank', 'CỰC(rất,cực đỉnh,cùng cực,xấu nhất)', 'Mộc Khí,Cức(亟:kíp,gấp.Khẩu Hủ Hựu Nhất) là cực đoan.1bàn tay nuôi 5 cái miệng với một cái cây thì thật khổ cực', ARRAY['キョク','ゴク'], ARRAY['きわ.める','きわ.まる','きわ.まり','きわ.み','き.める','-ぎ.め','き.まる'], 12, 460, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
