INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('僅', 'N1', 'a wee bit', 'CẨn,CẬN(chỉ, ít ỏi, vẻn vẹn,tiệm cận:gần tới,còn chút xíu)', 'NHÂN CẬN:người bôi trát(堇:Cách thổ,sao vàng cách thổ bôi thuốc) rất Cẩn thận.Nhân cách thổ:cận', ARRAY['キン','ゴン'], ARRAY['わず.か'], 12, NULL, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('勤', 'N3', 'diligence, become employed, serve', 'CẦN(siêng,chuyên cần,ân cần)', 'Cận(菫 hoa violet) lực:CẦN hoa violet cần sức lực để vượt qua cơn bãoCần(勤) Cẩn(謹) Cận(僅:lượng nhỏ) giống nhau chung Cận(堇:Bôi trát :Cách thổ)', ARRAY['キン','ゴン'], ARRAY['つと.める','-づと.め','つと.まる','いそ.しむ'], 12, 830, (SELECT id FROM radicals WHERE character = '19')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
