INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('緊', 'N1', 'tense, solid, hard, reliable, tight', 'KHẨN(gấp,khẩn cấp)', 'Hựu Thần Mịch là Khẩn cấp.堅:Thay Thổ là Kiên cố.腎:Thay Nhục là quả Thận.賢:Thay Bối là HIền(khôn ngoan)', ARRAY['キン'], ARRAY['し.める','し.まる'], 15, 677, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
