INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('駒', 'N1', 'pony, horse, colt', 'CÂU(ngựa con)', 'Mã Cú,Câu là Câu(ngựa con).ngựa rất Cú vì bị nói Câu "ngựa non háu đá có ngày đứt cương".拘:Thay Thủ là Câu nệ,bắt giữ.', ARRAY['ク'], ARRAY['こま'], 15, 1452, (SELECT id FROM radicals WHERE character = '187')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
