INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('繰', 'N1', 'winding, reel, spin, turn (pages), look up, refer to', 'SÀO,TAO(kéo tơ)', 'Mịch Táo(chim kêu ríu rít:喿:Phẩm Mộc)là Sào,Tao,Tảo ươm tơ.操:Thêm Thủ là Thao tác.藻:Thêm Thảo THủy là Tảo biển.燥:Thay Hỏa là Táo(khô ráo).', ARRAY['ソウ'], ARRAY['く.る'], 19, 872, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('桑', 'N1', 'mulberry', 'TANG(cây dâu)', '3 thằng hựu đánh tang cây dâu', ARRAY['ソウ'], ARRAY['くわ'], 10, 1650, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鍬', 'BEYOND', 'hoe with long blade at acute angle', '', '', ARRAY['ショウ','シュウ'], ARRAY['くわ','すき'], 17, NULL, (SELECT id FROM radicals WHERE character = '167')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('勲', 'N1', 'meritorious deed, merit', 'HUÂN(công trạng,huân chương)', 'HUÂN chương lao Động cho người có CÔNG tạo ra LửaLao động (動) toát mồ hôi (灬) thì phải được tặng thưởng huân(勲) chương rồiĐỘng trên Hỏa là Huân chương', ARRAY['クン'], ARRAY['いさお'], 15, 1513, (SELECT id FROM radicals WHERE character = '19')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('君', 'N3', 'mister, you, ruler, male name suffix', 'QUÂN(vua,người chủ nhà,phu quân,quân tử,phụ quân:phụ thân)', 'phu QUÂN:mồm giống mõm heo(ham ăn giống heo)Mõm Heo mồm Quân', ARRAY['クン'], ARRAY['きみ','-ぎみ'], 7, 947, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('薫', 'N1', 'send forth fragrance, fragrant, be scented, smoke (tobacco)', 'HUÂN(thơm,đầm ấm)', 'Thảo Trọng Hỏa là Huân thơm.đốt cỏ nặng sẽ ra Huân khói thơm.勲:Thay Lực là Huân chương.', ARRAY['クン'], ARRAY['かお.る'], 16, 1849, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('訓', 'N2', 'instruction, Japanese character reading, explanation, read', 'HUẤN(huấn luyện)', 'Ngôn Xuyên là Huấn luyện.Ngôn từ tuôn ra như sông là lời giáo huấn.', ARRAY['クン','キン'], ARRAY['おし.える','よ.む','くん.ずる'], 10, 1134, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('群', 'N2', 'flock, group, crowd, herd, swarm, cluster', 'QUẦN(bầy đàn,tốp,nhóm,tập hợp)', 'Quân Dương là QUần hùng.郡:Thay Ấp là Quận huyện', ARRAY['グン'], ARRAY['む.れる','む.れ','むら','むら.がる'], 13, 1012, (SELECT id FROM radicals WHERE character = '123')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('軍', 'N2', 'army, force, troops, war, battle', 'QUÂN(quân đội)', 'Mịch Xa là Quân đội.Xe có phủ bên trên là xe quân đội.輝:Thêm Quang là Huy(ánh sáng).揮:Thêm Thủ là chỉ Huy.', ARRAY['グン'], ARRAY['いくさ'], 9, 189, (SELECT id FROM radicals WHERE character = '159')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('郡', 'N1', 'county, district', 'QUẬN(quận,khu)', 'Quân Ấp là QUận.群:Thay Dương là Quần đảo.', ARRAY['グン'], ARRAY['こおり'], 10, 965, (SELECT id FROM radicals WHERE character = '163')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
