INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('祁', 'BEYOND', 'intense, large', '', '', ARRAY['キ','ケ'], NULL, 7, NULL, (SELECT id FROM radicals WHERE character = '113')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('係', 'N3', 'person in charge, connection, duty, concern oneself', 'HỆ(Quan hệ)<br><br>', 'mối quan HỆ giữa ng vs ng qua sợi chỉ (phim sợi chỉ đỏ)', ARRAY['ケイ'], ARRAY['かか.る','かかり','-がかり','かか.わる'], 9, 232, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('傾', 'N2', 'lean, incline, tilt, trend, wane, sink, ruin, bias', 'KHUYNH(nghiêng,dốc hết,khuynh hướng)', 'Khoảnh khắc Đầu có khuynh hướng tiến hoá độ nghiêng như tt nxpNhân khoảnh(khoảnh khắc,goro) là KHUYNHđầu nghiêng khoảnh khắc nhớ tới ăn uống bằng muỗng', ARRAY['ケイ'], ARRAY['かたむ.く','かたむ.ける','かたぶ.く','かた.げる','かし.げる'], 13, 938, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('刑', 'N1', 'punish, penalty, sentence, punishment', 'HÌNH(hình phạt,kết tội,hình sự)', 'Khai Đao là dụng HÌNH Hình(hình dạng):形', ARRAY['ケイ'], NULL, 6, 864, (SELECT id FROM radicals WHERE character = '18')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('兄', 'N4', 'elder brother, big brother', 'HUYNH(anh trai)', 'Khẩu nhân:anh trai', ARRAY['ケイ','キョウ'], ARRAY['あに'], 5, 1219, (SELECT id FROM radicals WHERE character = '10')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('啓', 'N1', 'disclose, open, say', 'KHẢI(mở,nói,chỉ bảo)', 'vừa đánh(攵) vừa nói(口) mới khai sáng(khải) được những kẻ không bao giờ ra khỏi cửa nhà(戸)Hộ Phốc Khẩu là Khải', ARRAY['ケイ'], ARRAY['ひら.く','さと.す'], 11, 1403, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('圭', 'BEYOND', 'square jewel, corner, angle, edge', '', '', ARRAY['ケイ','ケ'], NULL, 6, 1837, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('型', 'N2', 'mould, type, model', 'HÌNH(khuôn mẫu)', 'Khuôn hình làm từ đấtKiên can,khai đao thổ Hình', ARRAY['ケイ'], ARRAY['かた','-がた'], 9, 482, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('契', 'N1', 'pledge, promise, vow', 'KHẾ(khế ước)', 'Ông chủ cầm đao to làm Khế ước.Thêm Khẩu là KHIẾT đan(ăn uống,nhận vào)', ARRAY['ケイ'], ARRAY['ちぎ.る'], 9, 898, (SELECT id FROM radicals WHERE character = '37')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('形', 'N3', 'shape, form, style', 'HÌNH(hình dạng)', 'Khai(幵) Sam là HÌnh dạng.刑:Bỏ Sam thêm đao là HÌnh phạt.型:Hình(địa hình)', ARRAY['ケイ','ギョウ'], ARRAY['かた','-がた','かたち','なり'], 7, 418, (SELECT id FROM radicals WHERE character = '59')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('径', 'N1', 'diameter, path, method', 'KÍNH(đường kính)', 'Xích Thánh(圣 :thần thánh) là KÍnh', ARRAY['ケイ'], ARRAY['みち','こみち','さしわたし','ただちに'], 8, 1435, (SELECT id FROM radicals WHERE character = '60')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('恵', 'N1', 'favor, blessing, grace, kindness', 'HUỆ(ân huệ)', 'Thập Tư là Huệ.10 (THẬp) lần suy nghĩ (TƯ) về ân HUỆ đó穂:thêm Hòa là Tuệ(bông lúa)', ARRAY['ケイ','エ'], ARRAY['めぐ.む','めぐ.み'], 10, 925, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('慶', 'N1', 'jubilation, congratulate, rejoice, be happy', 'KHÁNH(mừng,phước,khánh thành)', 'Lộc(hươu) bỏ Chuỷ thêm mịch tâm truy là Khánh thành', ARRAY['ケイ'], ARRAY['よろこ.び'], 15, 1300, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('慧', 'BEYOND', 'wise', '', '', ARRAY['ケイ','エ'], ARRAY['さとい'], 15, 2168, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('憩', 'N1', 'recess, rest, relax, repose', 'KHẾ(nghỉ ngơi)', 'Thiệt Tức(息:hơi thở,tức ngực) là Khế.Cái thở là cái lưỡi Khế(nghỉ ngơi)', ARRAY['ケイ'], ARRAY['いこ.い','いこ.う'], 16, 1731, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('掲', 'N1', 'put up (a notice), put up, hoist, display, hang out, publish, describe', 'YẾT(xuất bản,giơ cao,dựng cờ.Yết Kiêu)', 'Thủ Hạt( 曷:gì)Nhật Mùi là Yết(niêm yết).謁:Thêm Ngôn là yết kiến', ARRAY['ケイ'], ARRAY['かか.げる'], 11, 899, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('携', 'N1', 'portable, carry (in hand), armed with, bring along', 'HUỀ(dìu dắt,mang theo,đề huề:hợp tác)', 'Thủ Tuyến(thịt béo:隽,Truy Nãi)là Huề.', ARRAY['ケイ'], ARRAY['たずさ.える','たずさ.わる'], 13, 1017, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('敬', 'N2', 'awe, respect, honor, revere', 'KÍNH(tôn kính)', 'Cẩu(cẩu thả:苟:Thảo Câu) Phộc là Kính trọng.Bị đánh khẽ khi CẨU thả (苟) k dùng lối nói cung KÍNH với người lớn.驚:Thêm Mã là Kinh ngạc.警:Thêm Ngôn là Cảnh sát.', ARRAY['ケイ','キョウ'], ARRAY['うやま.う'], 12, 1078, (SELECT id FROM radicals WHERE character = '66')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('景', 'N3', 'scenery, view', 'CẢNH(cảnh sắc)', 'Nhật KInh là Cảnh sắc.Mặt trời mọc trên KINH đô là một CẢNH rất đẹp.影:Thêm Sam là Ảnh(cái bóng).憬:Thêm Tâm là Cảnh tỉnh', ARRAY['ケイ'], NULL, 12, 419, (SELECT id FROM radicals WHERE character = '72')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('桂', 'BEYOND', 'Japanese Judas-tree, cinnamon tree', '', '', ARRAY['ケイ'], ARRAY['かつら'], 10, 1651, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('渓', 'N1', 'mountain stream, valley', 'KHÊ(khe nước,khe núi)', 'Thủy Trảo Phu là Khê.Thuỷ lấy Chồng ở THUNG LŨNG hương KHÊ.鶏:Thay Điểu là Kê(con gà)', ARRAY['ケイ'], ARRAY['たに','たにがわ'], 11, 2063, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('稽', 'N1', 'think, consider', 'KÊ(khổ luyện,xét,khấu đầu,cãi cọ)', 'Hòa Khuyển Chủy Nhật là Kê khổ luyện.', ARRAY['ケイ'], ARRAY['かんが.える','とど.める'], 15, 2372, (SELECT id FROM radicals WHERE character = '115')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('系', 'N1', 'lineage, system', 'HỆ(hệ thống,buộc,treo)', 'Triệt Mịch là Hệ thống.Các sợi tơ treo theo 1 hệ thống.係:Thêm Nhân là quan Hệ.孫:Thêm Tử là Tôn(cháu).遜:Thêm Sước ,Tử là khiêm TỐn.', ARRAY['ケイ'], NULL, 7, 567, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('経', 'N3', 'sutra, longitude, pass thru, expire, warp', 'KINH(kinh tế,trải qua)', 'Mịch Thánh là KInh tế.Đường Tăng tới vùng đất Thánh lấy Kinh.', ARRAY['ケイ','キョウ','キン'], ARRAY['へ.る','た.つ','たていと','はか.る','のり'], 11, 79, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('継', 'N1', 'inherit, succeed, continue, patch, graft (tree)', 'KẾ(thừa kế)', 'Mịch L Mễ là Kế thừa.kế bên chỉ là lúa.断:Thay Cân là Đoạn tuyệt.', ARRAY['ケイ'], ARRAY['つ.ぐ','まま-'], 13, 743, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('茎', 'N1', 'stalk, stem', 'HÀNH(cuống,thân)', 'Thảo Thánh là Hành cuống.', ARRAY['ケイ','キョウ'], ARRAY['くき'], 8, 2013, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('蛍', 'N1', 'lightning-bug, firefly', 'HUỲNH(đom đóm)', 'Tiểu Mịch Trùng là Huỳnh đom đóm.huỳnh quang@@', ARRAY['ケイ'], ARRAY['ほたる'], 11, 2031, (SELECT id FROM radicals WHERE character = '142')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('計', 'N4', 'plot, plan, scheme, measure', 'KẾ(đo,kế hoạch)', 'Ngôn Thập là Kế hoạch.', ARRAY['ケイ'], ARRAY['はか.る','はか.らう'], 9, 228, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('詣', 'N1', 'visit a temple, arrive, attain', 'NGHỆ(đi chùa,đền đầu năm)', 'Ngôn Chỉ là Nghệ hành hương.chỉ tay nói cho kẻ hành hương biết kia là NGHỆ an', ARRAY['ケイ','ゲイ'], ARRAY['けい.する','まい.る','いた.る','もう.でる'], 13, NULL, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('警', 'N3', 'admonish, commandment', 'CẢNH(khuyến cáo)', 'Kính(cung kính: 敬Cẩu(cẩu thả: 苟 Thảo Cú) Phộc) Ngôn là Cảnh tỉnh,khuyến cáo,răn bảo.驚:Thay Mã là Kinh ngạc', ARRAY['ケイ'], ARRAY['いまし.める'], 19, 366, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('軽', 'N2', 'lightly, trifling, unimportant', 'KHINH(nhẹ,khinh rẻ)', 'Xa Thánh là Khinh nhẹ.Xe chở Thánh nên đừng có Khinh.', ARRAY['ケイ','キョウ','キン'], ARRAY['かる.い','かろ.やか','かろ.んじる'], 12, 790, (SELECT id FROM radicals WHERE character = '159')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鶏', 'N1', 'chicken', 'KÊ(con gà)', 'Trảo Phụ Điểu là Kê gà.Phu (夫) quân chẳng cắt móng tay (爪)Gà (鶏) bày ra cái vặt ngay cái đùi.鶴:Thay Miên Chuy là con Hạc.', ARRAY['ケイ'], ARRAY['にわとり','とり'], 19, 1901, (SELECT id FROM radicals WHERE character = '196')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('芸', 'N2', 'technique, art, craft, performance, acting, trick, stunt', 'VÂN,NGHỆ?(gieo,rắc,cỏ thơm,nghệ thuật)', 'Thảo Vân là Vân gieo,rắc.伎芸:Kĩ Vân:Nghệ thuật.', ARRAY['ゲイ','ウン'], ARRAY['う.える','のり','わざ'], 7, 719, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('迎', 'N3', 'welcome, meet, greet', 'NGHÊNH(đón tiếp,nghênh đón)', 'SƯớc Ngang(ta:卬)là Nghênh đón.ra đường nghênh đón công Phượng.抑:Thay Thủ là Ức(đè nén).仰:thay Nhân là Ngưỡng mộ.', ARRAY['ゲイ'], ARRAY['むか.える'], 7, 625, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鯨', 'N1', 'whale', 'KÌNH(cá voi)', 'Ngư Kinh là Kình:cá voi.cá ở kinh đô là con cá kình', ARRAY['ゲイ'], ARRAY['くじら'], 19, 1486, (SELECT id FROM radicals WHERE character = '195')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('劇', 'N2', 'drama, play', 'KỊCH(vở kịch,quá lắm,trò đùa,hài kịch)', 'Vở KỊCH 7 con heo cầm đao ngày tếtHô THỉ đao là Kịch', ARRAY['ゲキ'], NULL, 15, 662, (SELECT id FROM radicals WHERE character = '18')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('戟', 'BEYOND', 'halbert, arms', '', '', ARRAY['ゲキ'], ARRAY['ほこ'], 12, NULL, (SELECT id FROM radicals WHERE character = '62')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('撃', 'N1', 'beat, attack, defeat, conquer', 'KÍCH(công kích)', 'Thù(軗:cái cần xe) THủ là Kích.TAY(手) cầm THÙ(殳) công KÍCH(撃) XE(車) địch.', ARRAY['ゲキ'], ARRAY['う.つ'], 15, 473, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('激', 'N1', 'violent, get excited, enraged, chafe, incite', 'KÍCH,KHÍCH(dữ dội,xói,kích thích,gắt)', 'Thủy Bạch Phương Phốc là Kích thích.', ARRAY['ゲキ'], ARRAY['はげ.しい'], 16, 560, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('隙', 'N1', 'crevice, fissure, discord, opportunity, leisure', 'KHÍCH(khe hở)', 'Phụ Tiểu Nhật Tiểu là Khích:khe hở.Bức tường có 2 lỗ nhỏ nhìn rõ ánh mặt trời', ARRAY['ゲキ','キャク','ケキ'], ARRAY['すき','す.く','す.かす','ひま'], 13, NULL, (SELECT id FROM radicals WHERE character = '170')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('桁', 'N1', 'beam, girder, spar, unit or column (accounting)', 'HÀNH(cột số,cột gỗ)', 'Mộc hành là Hành.Đếm chữ số bằng cây hành.五桁ごけたNGŨ HÀNH:số 5 chữ số.', ARRAY['コウ'], ARRAY['けた'], 10, NULL, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('傑', 'N1', 'greatness, excellence', 'KIỆT(giỏi lạ,kiệt xuất)', 'quái kiệt sài gòn hay lẫn lộn,bị suyễn mà còn leo cây', ARRAY['ケツ'], ARRAY['すぐ.れる'], 13, 1926, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('欠', 'N3', 'lack, gap, fail, yawning radical (no. 76)', '', '', ARRAY['ケツ','ケン'], ARRAY['か.ける','か.く'], 4, 860, (SELECT id FROM radicals WHERE character = '76')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('決', 'N3', 'decide, fix, agree upon, appoint', 'QUYẾT(quyết định)', 'Thủy Quái là QUyết định.Quyết 決 tâm tiêu diệt Thuỷ 氵Quái 夬', ARRAY['ケツ'], ARRAY['き.める','-ぎ.め','き.まる','さ.く'], 7, 71, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('潔', 'N1', 'undefiled, pure, clean, righteous, gallant', 'KHIẾT(trong sạch,liêm khiết)', 'Thủy Kiết(絜:sạch sẽ) là Khiết trong sạch', ARRAY['ケツ'], ARRAY['いさぎよ.い'], 15, 1595, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('穴', 'N1', 'hole, aperture, slit, cave, den', '', '', ARRAY['ケツ'], ARRAY['あな'], 5, 1366, (SELECT id FROM radicals WHERE character = '116')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('結', 'N1', 'tie, bind, contract, join, organize, do up hair, fasten', 'KẾT(kết quả,buộc,thắt nút dây)', 'Mịch Cát là Kết quả.', ARRAY['ケツ','ケチ'], ARRAY['むす.ぶ','ゆ.う','ゆ.わえる'], 12, 162, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
