INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('顕', 'N1', 'appear, existing', 'HIỂN(rõ,vẻ vang,vinh hiển)', 'Nhật Nghiệp Hiệt là Hiển hách,vẻ vang.Hiển hiện rõ trong đầu rằng mỗi ngày đều cần phải xếp hàng', ARRAY['ケン'], ARRAY['あきらか','あらわ.れる'], 18, 1536, (SELECT id FROM radicals WHERE character = '181')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('験', 'N4', 'verification, effect, testing', 'NGHIỆM(thử nghiệm)', 'Mã Thiêm là Nghiệm:thí nghiệm.Dùng ngựa thí nghiệm', ARRAY['ケン','ゲン'], ARRAY['あかし','しるし','ため.す','ためし'], 18, 410, (SELECT id FROM radicals WHERE character = '187')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('元', 'N4', 'beginning, former time, origin', 'NGUYÊN(căn bản,mới,nguồn)', '2 chân là NGuyên nhân dân tệ', ARRAY['ゲン','ガン'], ARRAY['もと'], 4, 192, (SELECT id FROM radicals WHERE character = '10')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('原', 'N3', 'meadow, original, primitive, field, plain, prairie, tundra, wilderness', 'NGUYÊN(cánh đồng,thảo nguyên,nguyên tử..)', 'Thảo NGUYÊN được bao trùm bởi những sườn núi nhỏ màu trắng', ARRAY['ゲン'], ARRAY['はら'], 10, 172, (SELECT id FROM radicals WHERE character = '27')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('厳', 'N1', 'stern, strictness, severity, rigidity', 'NGHIÊM(nghiêm ngặt,nghiêm túc)', 'nghiêm túc,dũng Cảm(敢).Nếu k nghiêm khắc sẽ véo tai đánh vào mông cột dưới sườn núi 3 hôm', ARRAY['ゲン','ゴン'], ARRAY['おごそ.か','きび.しい','いか.めしい','いつくし'], 17, 638, (SELECT id FROM radicals WHERE character = '27')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('幻', 'N1', 'phantasm, vision, dream, illusion, apparition', 'ẢO(ảo giác,dối giả)', 'Yêu cái J mà k biết là ảo tưởng', ARRAY['ゲン'], ARRAY['まぼろし'], 4, 1564, (SELECT id FROM radicals WHERE character = '52')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('弦', 'N1', 'bowstring, chord, hypotenuse', 'HUYỀN(dây cung)', 'CUng Huyền là Huyền.dây cung màu đen huyền bí', ARRAY['ゲン'], ARRAY['つる'], 8, 1773, (SELECT id FROM radicals WHERE character = '57')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('減', 'N2', 'dwindle, decrease, reduce, decline, curtail, get hungry', 'GIẢM(giảm xuống)', 'Thủy Hàm(khắp cả,đều:咸) là Giảm cân.感:Thay Tâm là Cảm giác.憾:Thêm Tâm là Hám(đắng,khốn khổ,ăn năn.hám ăn)', ARRAY['ゲン'], ARRAY['へ.る','へ.らす'], 12, 261, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('源', 'N1', 'source, origin', 'NGUYÊN(nguồn)', 'Thủy Nguyên là Nguyên nguồn.Trên thảo NGUYÊN có NƯỚC(氵) chảy từ trên những ngọn đồi NHỎ(小) màu Trắng(白).願:Thay Hiệt là Nguyện ước.', ARRAY['ゲン'], ARRAY['みなもと'], 13, 738, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('玄', 'N1', 'mysterious, occultness, black, deep, profound', '', '', ARRAY['ゲン'], ARRAY['くろ','くろ.い'], 5, 1409, (SELECT id FROM radicals WHERE character = '95')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('現', 'N3', 'present, existing, actual', 'HIỆN(xuất hiện)', 'Ngọc Kiến là Hiện hữu.Ngày xưa thấy vua xuất hiện mọi người kéo nhau đi xem( giờ cũng vậy mà )', ARRAY['ゲン'], ARRAY['あらわ.れる','あらわ.す','うつつ','うつ.つ'], 11, 85, (SELECT id FROM radicals WHERE character = '96')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('絃', 'BEYOND', 'string, cord, samisen music', '', '', ARRAY['ゲン'], ARRAY['いと'], 11, NULL, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('舷', 'N1', 'gunwale', 'HUYỀN(mạn thuyền)', 'Chu Huyền là Huyền mạn thuyền.những điều huyền 玄 bí của thời chu 舟 đã được khắc lên mạng thuyền 舷', ARRAY['ゲン'], ARRAY['ふなばた','ふなべり'], 11, NULL, (SELECT id FROM radicals WHERE character = '137')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
