INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('幸', 'N3', 'happiness, blessing, fortune', 'HẠNH(hạnh phúc,may)', 'Trải qua 10 lần Cay đắng mới có được HẠNH phúc執:Thêm Hoàn(tròn) là CHấp(chấp hành)達:Thêm Sước là Đạt(Thành đạt)', ARRAY['コウ'], ARRAY['さいわ.い','さち','しあわ.せ'], 8, 786, (SELECT id FROM radicals WHERE character = '51')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('広', 'N4', 'wide, broad, spacious', 'QUẢNG(rộng)', 'Mình tôi trog căn nhà thật là rộng rãi鉱:Thêm Kim là Khoáng(khoáng sản)拡:Thêm Thủ là Khuếch(khuếch đại)', ARRAY['コウ'], ARRAY['ひろ.い','ひろ.まる','ひろ.める','ひろ.がる','ひろ.げる'], 5, 263, (SELECT id FROM radicals WHERE character = '53')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
