INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('康', 'N1', 'ease, peace', 'KHANG(yên vui,an khang,khỏe mạnh)', 'Nghiễm Lệ,Đãi(kịp,phụ thuộc,nô lệ) là An Khang.Nô lệ có nhà thì an khang,yên vui', ARRAY['コウ'], NULL, 11, 760, (SELECT id FROM radicals WHERE character = '53')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('弘', 'BEYOND', 'vast, broad, wide', '', '', ARRAY['コウ','グ'], ARRAY['ひろ.い'], 5, 1059, (SELECT id FROM radicals WHERE character = '57')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('恒', 'N1', 'constancy, always', 'HẰNG(luôn luôn,thường,không đổi,hằng số)', 'Tâm Nhất Đán là Hằng số.Tâm Tuyên(trình bày) là Hằng số.1001 con tim HẰNG ngày chờ mong垣:Thêm Thổ là Viên(hàng rào)', ARRAY['コウ'], ARRAY['つね','つねに'], 9, 1314, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('慌', 'N1', 'disconcerted, be confused, lose one''s head', 'HOẢNG(vội vã)', 'Tâm Thảo Vong Xuyên Hoảng hốt.Tâm Hoang(荒:hoang vắng) là Hoảng(hoảng hốt,vội vã).Con TIM mà ở nơi HOANG vắng thì lúc nào cũng HOẢNG sợ', ARRAY['コウ'], ARRAY['あわ.てる','あわ.ただしい'], 12, 1826, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('抗', 'N1', 'confront, resist, defy, oppose', 'KHÁNG(kháng nghị,chống cự)', 'Thủ Kháng(cao,quá:亢) là Kháng chiến.坑:Thêm Thổ là Khanh(cái hố,chôn sống)', ARRAY['コウ'], ARRAY['あらが.う'], 7, 666, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('拘', 'N1', 'arrest, seize, concerned, adhere to, despite', 'CÂU(bắt,can dự)', 'Thủ Câu,cú là Câu.Kẻ dù cho nói lời có câu cú thì tay vẫn bị bắt', ARRAY['コウ'], ARRAY['かか.わる'], 8, 1336, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('控', 'N1', 'withdraw, draw in, hold back, refrain from, be moderate', 'KHỐNG(hạn chế,khống chế,dẫn )', 'Thủ Không(rỗng,bầu trời:空) là Khống chế.Một tay khống chế cả bầu trời.', ARRAY['コウ'], ARRAY['ひか.える','ひか.え'], 11, 1000, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
