INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('更', 'N3', 'grow late, night watch, sit up late, of course, renew, renovate, again, more and more, further', 'CANH(đổi,càng hơn,canh giờ.1 đêm 5 canh)', '硬:Thêm Thạch là Ngạnh(ương ngạnh).梗:Thêm Mộc là Ngạnh(tắc nghẽn).便:Thêm Nhân là Tiện lợi', ARRAY['コウ'], ARRAY['さら','さら.に','ふ.ける','ふ.かす'], 7, 861, (SELECT id FROM radicals WHERE character = '73')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
