INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('梗', 'N1', 'for the most part, close up, flower stem', 'NGẠNH(xơ cứng,tắc nghẽn)', 'Mộc Canh(canh 5) là Ngạnh(bệnh).Canh tác Cây trên vùng đất ương NGẠNH.硬:Thạch là ương Ngạnh.便:thêm Nhân là TIện lợi', ARRAY['コウ','キョウ'], ARRAY['ふさぐ','やまにれ','おおむね'], 11, NULL, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('構', 'N3', 'posture, stance, appearance, build, set up', 'CẤU(cấu tạo)', 'Mộc Cấu(冓 ) là Cấu tạo.購:Thêm Bối là Cấu(mua bán)溝:Thêm Thủy là Câu(hào nước)', ARRAY['コウ'], ARRAY['かま.える','かま.う'], 14, 316, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
