INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('溝', 'N1', 'gutter, ditch, sewer, drain, 10**32', 'CÂU(mương,rãnh)', 'Thủy Cấu là Câu mương,rảnh.購:Thay Bối là Cấu(mua bán)構:Thay Mộc là Cấu tạo', ARRAY['コウ'], ARRAY['みぞ'], 13, 1736, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('甲', 'N1', 'armor, high (voice), A grade, first class, former, instep, carapace', 'GIÁP(can thứ nhất)', 'Điền Cổn là GIáp.押:Thêm Thủ là Áp lực.ấn.岬:Thêm Sơn là GIáp(vệ núi)', ARRAY['コウ','カン'], ARRAY['きのえ'], 5, 1073, (SELECT id FROM radicals WHERE character = '102')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('皇', 'N1', 'emperor', 'HOÀNG(vua)', 'Bạch Vương là Hoàng đế.', ARRAY['コウ','オウ'], NULL, 9, 721, (SELECT id FROM radicals WHERE character = '106')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('硬', 'N2', 'stiff, hard', 'NGẠNH(cứng,ương ngạnh)', 'Thạch Canh(đổi,5canh) là Ngạnh cứng.梗:Thay Mộc là Ngạnh(tắc nghẽn).便:Thay Nhân là Tiện lợi.', ARRAY['コウ'], ARRAY['かた.い'], 12, 1101, (SELECT id FROM radicals WHERE character = '112')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('稿', 'N1', 'draft, copy, manuscript, straw', 'CẢO(bản thảo)', 'Hòa Cao là CẢo bản thảo.', ARRAY['コウ'], ARRAY['わら','したがき'], 15, 1400, (SELECT id FROM radicals WHERE character = '115')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('紅', 'N2', 'crimson, deep red', 'HỒNG(đỏ đậm)', 'Mịch Công là Hồng(màu hồng)', ARRAY['コウ','ク'], ARRAY['べに','くれない','あか.い'], 9, 1299, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('紘', 'BEYOND', 'large', '', '', ARRAY['コウ'], ARRAY['おおづな','つな','つなぐ'], 10, 1685, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('絞', 'N1', 'strangle, constrict, wring', 'GIẢO(bóp,thắt,vắt)', 'Mịch Giao là Giảo vắt.Sợi dây giao nhau là điểm thắt siết bóp..', ARRAY['コウ'], ARRAY['しぼ.る','し.める','し.まる'], 12, 1288, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('綱', 'N1', 'hawser, class (genus), rope, cord, cable', 'CƯƠNG(dây,dây cương)', 'Mịch Cương là CƯơng dây cương.Dùng Dây Cương để leo Đồi núi.剛:Thay Đao là Cương cứng.鋼:Thay Kim là CƯơng thép.', ARRAY['コウ'], ARRAY['つな'], 14, 1053, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('耕', 'N2', 'till, plow, cultivate', 'CANH(canh tác,cày ruộng)', 'Lỗi Tỉnh là Canh tác,cày ruộng.', ARRAY['コウ'], ARRAY['たがや.す'], 10, 1568, (SELECT id FROM radicals WHERE character = '127')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
