INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('航', 'N2', 'navigate, sail, cruise, fly', 'HÀNG(hàng không,hàng hải)', 'Chu Kháng(cao,qúa,kháng chiến:亢Đầu Kỉ)là Hàng không.', ARRAY['コウ'], NULL, 10, 665, (SELECT id FROM radicals WHERE character = '137')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('荒', 'N2', 'laid waste, rough, rude, wild', 'HOANG(bỏ hoang,hoang dã)', 'Cảnh hoang tàn bên dòng sông cỏ cây chết cả慌:Thêm Tâm là Hoảng hốt.', ARRAY['コウ'], ARRAY['あ.らす','あ.れる','あら.い','すさ.ぶ','すさ.む','あ.らし'], 9, 1099, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('行', 'N5', 'going, journey, carry out, conduct, act, line, row, bank', '', '', ARRAY['コウ','ギョウ','アン'], ARRAY['い.く','ゆ.く','-ゆ.き','-ゆき','-い.き','-いき','おこな.う','おこ.なう'], 6, 20, (SELECT id FROM radicals WHERE character = '144')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('衡', 'N1', 'equilibrium, measuring rod, scale', 'HÀNH(cân bằng)', 'Hành Giác Đại là Hành cán cân công lý.Sừng trâu to cân bằng.', ARRAY['コウ'], NULL, 16, 1847, (SELECT id FROM radicals WHERE character = '144')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('講', 'N2', 'lecture, club, association', 'GIẢNG(giảng bài)', 'Ngôn Cấu(冓)là Giảng bài,thuyết trình.CẤU (冓) là phòng kín. Ngồi trong nơi kín đáo dùng NGÔN từ GIẢNG giải cho nhau điều hay lẽ phải.構:Thay Mộc là Cấu tạo.購:Thay Bối là Cấu(mua bán).溝:Thay Thủy là Câu(cái hào nước).', ARRAY['コウ'], NULL, 17, 653, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('貢', 'N1', 'tribute, support, finance', 'CỐNG(cống hiến)', 'Công Bối là Cống hiến.Tiền công để cống nạp', ARRAY['コウ','ク'], ARRAY['みつ.ぐ'], 10, 956, (SELECT id FROM radicals WHERE character = '154')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('購', 'N1', 'subscription, buy', 'CẤU(mua vào)', 'Bối Cấu là Cấu mua sắm.構:Thay Mộc là Cấu tạo.溝:Thay Thủy là Câu(hào nước).講:Thay Ngôn là Giảng(giảng nghĩa).', ARRAY['コウ'], NULL, 17, 945, (SELECT id FROM radicals WHERE character = '154')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('郊', 'N2', 'outskirts, suburbs, rural area', 'GIAO(ngoại ô)', 'Giao Ấp là Giao ngoại ô.Giao nhau giữa bức tường thành là vùng ngoại ô', ARRAY['コウ'], NULL, 9, 1304, (SELECT id FROM radicals WHERE character = '163')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('酵', 'N1', 'fermentation', 'DIẾU(lên men)', 'Dậu Hiếu là Diếu lên men.Ủ rượu lên men thể hiện sự hiếu thảo.教:Thay Phộc là Giáo dục.', ARRAY['コウ'], NULL, 14, 1862, (SELECT id FROM radicals WHERE character = '164')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鉱', 'N2', 'mineral, ore', 'KHOÁNG(quặng,mỏ)', 'Kim Quảng là Khoáng quặng.Chỗ rộng có nhiều kim loại là nơi có khoáng sản.拡:Thay Thủ là Khuếch đại.', ARRAY['コウ'], ARRAY['あらがね'], 13, 1376, (SELECT id FROM radicals WHERE character = '167')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鋼', 'N1', 'steel', 'CƯƠNG(chất thép)', 'Kim Cương là Thép.Luyện Kim thành thép cương cứng.綱:Thay Mịch là Cương(dây thừng).剛:Thay Đao là Cương(cứng).', ARRAY['コウ'], ARRAY['はがね'], 16, 1246, (SELECT id FROM radicals WHERE character = '167')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('閤', 'BEYOND', 'small side gate', '', '', ARRAY['コウ'], ARRAY['くぐりど'], 14, NULL, (SELECT id FROM radicals WHERE character = '169')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('降', 'N3', 'descend, precipitate, fall, surrender', 'GIÁNG(xuống xe,mưa rơi)', 'Phụ Tri Niên là GIáng mưa rơi.', ARRAY['コウ','ゴ'], ARRAY['お.りる','お.ろす','ふ.る','ふ.り','くだ.る','くだ.す'], 10, 596, (SELECT id FROM radicals WHERE character = '170')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('項', 'N1', 'paragraph, nape of neck, clause, item, term (expression)', 'HẠNG(hạng mục,thứ hạng)', 'Công Hiệt là Hạng:gáy,thứ hạng.Đầu làm công việc liên quan tới các hạng mục', ARRAY['コウ'], ARRAY['うなじ'], 12, 884, (SELECT id FROM radicals WHERE character = '181')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
