INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('栽', 'N1', 'plantation, planting', 'TÀI(trồng cây)', 'Thập qua Mộc là Tài trồng cây.載:Thêm Xa là vận Tải.裁:Thêm Y là Tài(phán xét).戴:Thêm Dị(khác) là Đới (nhận).', ARRAY['サイ'], NULL, 10, 1496, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('歳', 'N3', 'year-end, age, occasion, opportunity', 'TUẾ(tuổi,năm)', 'Chỉ Tiểu Tuất(tuổi chó:戌) là Tuế tuổi.', ARRAY['サイ','セイ'], ARRAY['とし','とせ','よわい'], 13, 269, (SELECT id FROM radicals WHERE character = '77')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('済', 'N3', 'settle (debt, etc.), relieve (burden), finish, come to an end, excusable, need not', 'TẾ(làm xong,kinh tế)', 'Thủy Tề là Tế', ARRAY['サイ','セイ'], ARRAY['す.む','-ず.み','-ずみ','す.まない','す.ます','-す.ます','すく.う','な.す','わたし','わた.る'], 11, 168, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('災', 'N1', 'disaster, calamity, woe, curse, evil', 'TAI(tai họa)', 'Xuyên Hỏa là Tai họa.Ngày xưa lửa và sông nước đc xem là mối tai hoạ', ARRAY['サイ'], ARRAY['わざわ.い'], 7, 976, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('采', 'N1', 'dice, form, appearance, take, gather, coloring', 'THÁI(phong thái,hái,ngắt)', 'Trảo Mộc là Thái.菜:Thêm Thảo là Thái(rau).採:Thêm thủ là Thái(hái,ngắt).彩:thêm Sam là Thái(sắc thái).', ARRAY['サイ'], ARRAY['と.る','いろどり'], 8, NULL, (SELECT id FROM radicals WHERE character = '165')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('犀', 'BEYOND', 'rhinoceros', '', '', ARRAY['サイ','セイ'], NULL, 12, 2426, (SELECT id FROM radicals WHERE character = '93')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('砕', 'N1', 'smash, break, crush, familiar, popular', 'TOÁI(bẻ vụn)', 'Thạch Cửu Thập là Toái phá vỡ.Đập tan nát 9,10 cục đá phiền toái.枠:Thay Mộc là cái Khung.粋:Thay Mễ là tinh Túy.酔:thay Dậu là Túy(say).', ARRAY['サイ'], ARRAY['くだ.く','くだ.ける'], 9, 1579, (SELECT id FROM radicals WHERE character = '112')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('砦', 'BEYOND', 'fort, stronghold, entrenchments', '', '', ARRAY['サイ'], ARRAY['とりで'], 11, 2304, (SELECT id FROM radicals WHERE character = '112')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('祭', 'N2', 'ritual, offer prayers, celebrate, deify, enshrine, worship', 'TẾ(lễ hội,tế lễ)', 'nghi lễ TẾ MA(マ) được chỉ THỊ vào chiều TỐI.際:Thêm Phụ là quốc Tế.察:Thêm Miên là cảnh Sát.擦:Thêm Thủ,Miên là ma Sát.', ARRAY['サイ'], ARRAY['まつ.る','まつ.り','まつり'], 11, 1124, (SELECT id FROM radicals WHERE character = '113')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('斎', 'N1', 'purification, Buddhist food, room, worship, avoid, alike', 'TRAI(ăn chay,trai giới)', 'Tề thêm Thị là Trai giới:ăn chay.', ARRAY['サイ'], ARRAY['とき','つつし.む','ものいみ','い.む','いわ.う','いつ.く'], 11, 1155, (SELECT id FROM radicals WHERE character = '67')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('細', 'N2', 'dainty, get thin, taper, slender, narrow, detailed, precise', 'TẾ(thon,chi tiết)', 'Mịch ĐIền là tinh Tế.', ARRAY['サイ'], ARRAY['ほそ.い','ほそ.る','こま.か','こま.かい'], 11, 537, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('菜', 'N2', 'vegetable, side dish, greens', 'THÁI(rau)', 'Thảo Thái,Thải(hái,ngắt:采Trảo Mộc)là Thái rau.採:Thay Thủ là Thái(hái,ngắt).彩:Thay Sam là sắc Thái.', ARRAY['サイ'], ARRAY['な'], 11, 1327, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('裁', 'N1', 'tailor, judge, decision, cut out (pattern)', 'TÀI(phán quyết,trọng tài,cắt áo)', 'Thập Qua Y là Tài phán quyết.Công việc của thằng trọng tài là mặc y phục rồi chỉ chạy qua chạy lại tren đất ( sân bóng).栽:Thay Mộc là Tài(trồng cây).載:Thay Xa là vận Tải.戴:Thay Dị là Đái,ĐỚi (đội mũ).', ARRAY['サイ'], ARRAY['た.つ','さば.く'], 12, 297, (SELECT id FROM radicals WHERE character = '145')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('載', 'N1', 'ride, board, get on, place, spread, 10**44, record, publish', 'TẢI(đăng báo,upload)', 'Thập Qua Xa là Tải lên,up lên.Xe đi qua chở đất là xe Tải.栽:Thay Mộc là Tài(trồng cây).裁:Thay Y là Tài(phán xét).戴:Thay Đái,Đới là Đái,ĐỚi nhận.', ARRAY['サイ'], ARRAY['の.せる','の.る'], 13, 825, (SELECT id FROM radicals WHERE character = '159')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('際', 'N3', 'occasion, side, edge, verge, dangerous, adventurous, indecent, time, when', 'TẾ(giao tiếp,giao tế)', 'Phụ Tế(cúng tế,liên hoan:祭) là Tế:giao tiếp.', ARRAY['サイ'], ARRAY['きわ','-ぎわ'], 14, 183, (SELECT id FROM radicals WHERE character = '170')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('剤', 'N1', 'dose, medicine, drug', 'TỄ(dịch tễ,thuốc tễ)', 'Tề(斉) cầm dao doạ tễ lấy thuốcTẾ(kinh tế):済Tề đao là tễ', ARRAY['ザイ','スイ','セイ'], ARRAY['かる','けず.る'], 10, 1151, (SELECT id FROM radicals WHERE character = '18')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
