INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('斬', 'N2', 'beheading, kill, murder', 'TRẢM(chém,dứt)', 'Xa Cân là TRảm.暫:Thêm Nhật là Tạm thời.漸:Thêm Thủy là Tiệm cận.', ARRAY['ザン','サン','セン','ゼン'], ARRAY['き.る'], 11, 2132, (SELECT id FROM radicals WHERE character = '69')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
