INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('残', 'N3', 'remainder, leftover, balance', 'TÀN(còn lại)', 'Tàn dư Qua 2 cuộc chiến tranh là bomb.xác chết.銭:Thêm Kim là Tiền bạc  践:Thêm Túc là thực Tiễn  浅:Thêm Thủy là Thiển cận.桟: Thay Mộc là Sạn(sàn lót gỗ,giá để đồ).', ARRAY['ザン','サン'], ARRAY['のこ.る','のこ.す','そこな.う','のこ.り'], 10, 380, (SELECT id FROM radicals WHERE character = '78')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
