INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('識', 'N3', 'discriminating, know, write', 'THỨC(nhận thức)', 'Ngôn Âm Qua là Thức biết.職:Thay Nhĩ là chức vụ.織:Thay Mịch là Chức(dệt vải).35. 識 thức biết 36. 知 tri hay 37. 木 mộc cây 38. 根 căn rễ 39. 易 dị dễ 40. 難 nan khôn,khó.', ARRAY['シキ'], ARRAY['し.る','しる.す'], 19, 496, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
