INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('殊', 'N1', 'particularly, especially, exceptionally', 'THÙ(đặc thù,khác,rất,lắm)', 'Đãi Chu là THù.đặc THÙ chết đi thành màu đỏ thẫm.株:Thêm Mộc là Chu(cổ phần,cổ phiếu)', ARRAY['シュ'], ARRAY['こと'], 10, 1361, (SELECT id FROM radicals WHERE character = '78')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
