INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('種', 'N3', 'species, kind, class, variety, seed', 'CHỦNG(chủng loại,giống loài)', 'Hòa Trọng là Chủng loại.Gieo Lúa cần chọn CHỦNG loại có TRọng lượng cao', ARRAY['シュ'], ARRAY['たね','-ぐさ'], 14, 461, (SELECT id FROM radicals WHERE character = '115')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('腫', 'N1', 'tumor, swelling', 'THŨNG(sưng lên,phù ,nề)', 'Nhục Trọng là Thũng phù thũng.種:Thay Hòa là Chủng loại.', ARRAY['シュ','ショウ'], ARRAY['は.れる','は.れ','は.らす','はれもの'], 13, 2145, (SELECT id FROM radicals WHERE character = '130')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('趣', 'N1', 'purport, gist, elegance, interest, proceed to, tend, become', 'THÚ(thú vui)', 'Tẩu Thủ là Thú vui.Lấy 取る hứng thú làm động lực chạy走る cho nhanh', ARRAY['シュ'], ARRAY['おもむき','おもむ.く'], 15, 1153, (SELECT id FROM radicals WHERE character = '156')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
