INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('受', 'N3', 'accept, undergo, answer (phone), take, get, catch, receive', 'THỤ(nhận,chịu,vâng,đựng chứa,thi đỗ)', 'lại (HỰU) nhận (THỤ) được cái khăn (MỊCH) thêu hình móng tay (TRẢO)Thêm Tay là Thụ(trao cho):授', ARRAY['ジュ'], ARRAY['う.ける','-う.け','う.かる'], 8, 136, (SELECT id FROM radicals WHERE character = '29')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('呪', 'N1', 'spell, curse, charm, malediction', 'CHÚ(thần chú,nguyền rủa,lời nguyền)', 'anh trai TÔn ngộ không mồm bị dính thần CHÚ', ARRAY['ジュ','シュ','シュウ','ズ'], ARRAY['まじな.う','のろ.い','まじな.い','のろ.う'], 8, 2131, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('寿', 'N2', 'longevity, congratulations, one''s natural life', 'THỌ(sống lâu)', 'Sống thọ phải chống 3 gậy thì thốn lắm', ARRAY['ジュ','ス','シュウ'], ARRAY['ことぶき','ことぶ.く','ことほ.ぐ'], 7, 1245, (SELECT id FROM radicals WHERE character = '41')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
