INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('樹', 'N1', 'timber, trees, wood, establish, set up', 'THỤ(cây to,cổ thụ)', 'Mộc Thụ(đứng thẳng:尌 trú Thốn) là Thụ.鼓:Trú Chi là Cổ(cái trống).Cây cổ Thụ có 10 hạt Đậu là rất thiếu Thốn.', ARRAY['ジュ'], ARRAY['き'], 16, 988, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('需', 'N1', 'demand, request, need', 'NHU(nhu cầu)', 'Vũ Nhi là Nhu cầu.', ARRAY['ジュ'], NULL, 14, 935, (SELECT id FROM radicals WHERE character = '173')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
