INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('周', 'N2', 'circumference, circuit, lap', 'CHU(khắp,vòng,xung quanh)', 'Quynh chứa Thổ Khẩu.Lưu ý:k phải chữ Cát吉', ARRAY['シュウ'], ARRAY['まわ.り'], 8, 562, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('宗', 'N1', 'religion, sect, denomination, main point, origin, essence', 'TÔN,TÔNG(tôn giáo)', 'ở dưới mái nhà thì không được kì thị chuyện tôn giáoMiên thị tôn giáo', ARRAY['シュウ','ソウ'], ARRAY['むね'], 8, 997, (SELECT id FROM radicals WHERE character = '40')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('就', 'N1', 'concerning, settle, take position, depart, study, per', 'TỰU(thành tựu)', '就職TỰU CHỨC: Việc làmCả dòng họ VƯU (尤) đỗ qua to trên KINH đô thật là thành TỰU đáng ngạc nhiên', ARRAY['シュウ','ジュ'], ARRAY['つ.く','つ.ける'], 12, 624, (SELECT id FROM radicals WHERE character = '43')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
