INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('秀', 'N1', 'excel, excellence, beauty, surpass', 'TÚ(ưu tú,tú tài)', 'Hòa Nãi,Ái(bèn,hoặc là:乃)là Tú tài.誘:Thêm Ngôn là Dụ(mời).透:Thêm Sước là THấu(trong suốt).', ARRAY['シュウ'], ARRAY['ひい.でる'], 7, 848, (SELECT id FROM radicals WHERE character = '115')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('秋', 'N4', 'autumn', 'THU(mùa thu)', 'Hòa Hỏa là Thu vàng.', ARRAY['シュウ'], ARRAY['あき','とき'], 9, 635, (SELECT id FROM radicals WHERE character = '115')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
