INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('習', 'N4', 'learn', 'TẬP(học tập)', 'Vũ Bạch là Tập Cận bình.', ARRAY['シュウ','ジュ'], ARRAY['なら.う','なら.い'], 11, 706, (SELECT id FROM radicals WHERE character = '124')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
