INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('蹴', 'N1', 'kick', 'XÚC(đá)', 'Túc Tựu(nên,tới,theo:就Kinh Vưu)là Xúc đá.(đá banh).', ARRAY['シュク','シュウ'], ARRAY['け.る'], 19, 2377, (SELECT id FROM radicals WHERE character = '157')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
