INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('酬', 'N1', 'repay, reward, retribution', 'THÙ(báo đáp,mời rượu)', 'Dậu Châu là Thù báo đáp,trả thù.Sang CHÂU âu buôn Rượu 10 năm sau QUAY VỀ BÁO THÙ', ARRAY['シュウ','シュ','トウ'], ARRAY['むく.いる'], 13, 1515, (SELECT id FROM radicals WHERE character = '164')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
