INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('醜', 'N1', 'ugly, unclean, shame, bad looking', 'XÚ(xấu hổ,xấu xí)', 'Dậu Quỷ là Xú xấu hổ.Quỷ uống rượu thì xấu xa tột độ', ARRAY['シュウ'], ARRAY['みにく.い','しこ'], 17, 2074, (SELECT id FROM radicals WHERE character = '164')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('住', 'N4', 'dwell, reside, live, inhabit', 'TRỤ, TRÚ(cư trú)', 'NGƯỜI ĐỨNG (ィ) cạnh ÔNG CHỦ (主）thì luôn có chỗ TRÚ (住) thân', ARRAY['ジュウ','ヂュウ','チュウ'], ARRAY['す.む','す.まう','-ず.まい'], 7, 270, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('充', 'N1', 'allot, fill', 'SUNG(đầy đủ,sung túc)', 'Đầu Duẩn:đầu thành thực thì sống sung túc', ARRAY['ジュウ'], ARRAY['あ.てる','み.たす'], 6, 949, (SELECT id FROM radicals WHERE character = '10')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
