INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('従', 'N1', 'accompany, obey, submit to, comply, follow, secondary, incidental, subordinate', 'TÒNG,TÙNG(tuân theo,xuất giá tòng phu,phục tùng)', 'Xích Thảo CHỉ là TÒNG,TÙNG.縦:Thêm Mịch là Tung(trục tung)', ARRAY['ジュウ','ショウ','ジュ'], ARRAY['したが.う','したが.える','より'], 10, 601, (SELECT id FROM radicals WHERE character = '60')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('柔', 'N2', 'tender, weakness, gentleness, softness', 'NHU(mềm,nhu đạo)', 'Mâu Mộc Nhu đạo.', ARRAY['ジュウ','ニュウ'], ARRAY['やわ.らか','やわ.らかい','やわ','やわ.ら'], 9, 1187, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('汁', 'N1', 'soup, juice, broth, sap, gravy, pus', 'CHẤP,TRẤP,HIỆP(nước cốt,súp)', 'Thủy Thập là Trấp.Nấu Mười lần Nước thì ra được nồi Súp', ARRAY['ジュウ'], ARRAY['しる','-しる','つゆ'], 5, 1843, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
