INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('獣', 'N1', 'animal, beast', 'THÚ(thú vật)', 'Tiểu Điền Nhất Khẩu Khuyển là Thú vật', ARRAY['ジュウ'], ARRAY['けもの','けだもの'], 16, 1714, (SELECT id FROM radicals WHERE character = '94')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('縦', 'N1', 'vertical, length, height, self-indulgent, wayward', 'TUNG(chiều dọc,tung hoành)', 'Mịch Tòng(làm theo:従:Xích Thảo Sơ)là Tung hoành.', ARRAY['ジュウ'], ARRAY['たて'], 16, 1258, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('重', 'N4', 'heavy, important, esteem, respect, heap up, pile up, nest of boxes, -fold', 'TRỌNG(nặng)', 'Thiên Lí là Trọng nặng.種:Thêm Hòa là Chủng loại.衝:Thêm Hành là Xung đột.腫:Thêm Nhục là Thũng(khối u).', ARRAY['ジュウ','チョウ'], ARRAY['え','おも.い','おも.り','おも.なう','かさ.ねる','かさ.なる','おも'], 9, 193, (SELECT id FROM radicals WHERE character = '166')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('銃', 'N1', 'gun, arms', 'SÚNG(khẩu súng)', 'Kim Sung là Súng là súng ống.統:Thay Mịch là truyền Thống.', ARRAY['ジュウ'], ARRAY['つつ'], 14, 1013, (SELECT id FROM radicals WHERE character = '167')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('叔', 'N1', 'uncle, youth', 'THÚC(chú,thúc thúc)', 'Đứa nhỏ trở lại gọi bề trên là thúcThục(hiền thục):thêm Thủy:淑Tịch(lặng im):寂', ARRAY['シュク'], NULL, 8, 1950, (SELECT id FROM radicals WHERE character = '29')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
