INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('縮', 'N1', 'shrink, contract, shrivel, wrinkle, reduce', 'SÚC(rút ngắn,co rút)', 'Mịch Túc(chỗ trọ:宿)là Súc rút ngắn.Ở trong nhà có 100 người cùng nhau làm ngắn sợi dây', ARRAY['シュク'], ARRAY['ちぢ.む','ちぢ.まる','ちぢ.める','ちぢ.れる','ちぢ.らす'], 17, 909, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('粛', 'N1', 'solemn, quietly, softly', 'TÚC(nghiêm kính)', 'Duật Mễ là Túc nghiêm túc.', ARRAY['シュク','スク'], ARRAY['つつし.む'], 11, 1549, (SELECT id FROM radicals WHERE character = '129')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('塾', 'N1', 'cram school, private school', 'THỤC(trường tư,tư thục)', 'Hưởng Hoàn Thổ là tư THỤCđứa trẻ đội mũ chạy vòng tròn trên bãi đất', ARRAY['ジュク'], NULL, 14, 1297, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('熟', 'N1', 'mellow, ripen, mature, acquire skill', 'THỤC(Kỹ càng,chín,có kinh nghiệm@@)', 'Thục(từng cái,một trong,bất kỳ:孰) Hỏa là Thục chín塾:Thay Thổ là tư thục', ARRAY['ジュク'], ARRAY['う.れる'], 15, 1415, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
