INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('術', 'N3', 'art, technique, skill, means, trick, resources, magic', 'THUẬT(y thuật,phép thuật,kỹ thuật)', 'Phép thuật làm mọc cây giữa đường.述:Thay Sước là Thuật lại.', ARRAY['ジュツ'], ARRAY['すべ'], 11, 350, (SELECT id FROM radicals WHERE character = '144')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('述', 'N2', 'mention, state, speak, relate', 'THUẬT(kể lại)', 'Sước Mộc CHủ là Thuật lại,trình bày.Thuật lại đường đi ra hồ.術:Thay Hành là Thuật(kỹ thuật).', ARRAY['ジュツ'], ARRAY['の.べる'], 8, 379, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('俊', 'N1', 'sagacious, genius, excellence', 'TUẤN(Tài giỏi, tài trí&nbsp;)', 'người TUẤN kiệt là ng bước chậm(夂) và thành thực(duẫn: 允khư nhân)Nhân duẩn tri là TUẤN', ARRAY['シュン'], NULL, 9, 1007, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
