INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('除', 'N3', 'exclude, division (x/3), remove, abolish, cancel, except', 'TRỪ(loại trừ)', 'Phụ Dư là Trừ :loại trừ,ngoại trừ.徐:Thay Xích là Từ từ từ.叙:Thay Hựu là Tự(kể lại).', ARRAY['ジョ','ジ'], ARRAY['のぞ.く','-よ.け'], 10, 594, (SELECT id FROM radicals WHERE character = '170')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
