INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('沼', 'N1', 'marsh, lake, bog, swamp, pond', 'CHIỂU(đầm lầy)', 'Thủy Triệu là Chiểu(đầm lầy).詔:Thay Ngôn là Chiếu vua ban.照:Chiếu sáng', ARRAY['ショウ'], ARRAY['ぬま'], 8, 1467, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('消', 'N3', 'extinguish, blow out, turn off, neutralize, cancel', 'TIÊU(tắt,biến mất)', 'Thủy Tiêu,Tiếu(giống) là Tiêu biến.硝:Thêm Thạch là diêm Tiêu.', ARRAY['ショウ'], ARRAY['き.える','け.す'], 10, 345, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
