INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('湘', 'BEYOND', 'name of Chinese river, the Sagami river', '', '', ARRAY['ショウ'], NULL, 12, 1909, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('焼', 'N2', 'bake, burning', 'THIÊU(nướng)', 'Hỏa Nghiêu(Cao,vua Nghiêu:尭)là Thiêu đốt.Ngày 30 đi đốt lửa.暁:Thay Nhật là Hiểu(bình minh)', ARRAY['ショウ'], ARRAY['や.く','や.き','や.き-','-や.き','や.ける'], 12, 982, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('焦', 'N1', 'char, hurry, impatient, irritate, burn, scorch, singe', 'TIÊU(cháy hết,tiêu điều,bị cháy)', 'Chuy Hỏa là Tiêu điều.Chim cháy Tiêu.樵:Thêm Mộc là Tiều phu.礁:Thêm Thạch là Tiều(đá ngầm)', ARRAY['ショウ'], ARRAY['こ.げる','こ.がす','こ.がれる','あせ.る','じ.れる','じ.らす'], 12, 973, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('照', 'N2', 'illuminate, shine, compare, bashful', 'CHIẾU(chiếu sáng)', 'Chiêu(sáng sủa,rõ rệt:昭) Hỏa là Chiếu sáng.詔:Thêm Ngôn là Chiếu vua ban沼:Thêm Thủy là Chiểu(ao đầm)', ARRAY['ショウ'], ARRAY['て.る','て.らす','て.れる'], 13, 1004, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('症', 'N1', 'symptoms, illness', 'CHỨNG(triệu chứng)', 'Nạch Chính là Chứng bệnh.証:Thay Ngôn là CHứng minh', ARRAY['ショウ'], NULL, 10, 1111, (SELECT id FROM radicals WHERE character = '104')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('省', 'N2', 'government ministry, conserve, omit', 'TỈNH(xem xét)', 'Thiểu Mục là Tỉnh xem xét.MẮT mà THIẾU ngủ thì k TỈNH đc', ARRAY['セイ','ショウ'], ARRAY['かえり.みる','はぶ.く'], 9, 548, (SELECT id FROM radicals WHERE character = '109')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('硝', 'N1', 'nitrate, saltpeter', 'TIÊU(diêm tiêu,muối diêm)', 'Thạch Tiêu là diêm Tiêu.', ARRAY['ショウ'], NULL, 12, 2154, (SELECT id FROM radicals WHERE character = '112')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('礁', 'N1', 'reef, sunken rock', 'TIỀU(đá ngầm)', 'Thạch CHuy Hỏa là Tiều.Thạch Tiêu(cháy,đốt:焦)là Tiều đá ngầm.樵:Thay Mộc là Tiều phu', ARRAY['ショウ'], NULL, 17, 1977, (SELECT id FROM radicals WHERE character = '112')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('祥', 'N1', 'auspicious, happiness, blessedness, good omen, good fortune', 'TƯỜNG(điềm lành,phúc)', 'Thị DƯơng là Tường(điềm tốt)', ARRAY['ショウ'], ARRAY['さいわ.い','きざ.し','よ.い','つまび.らか'], 10, 1273, (SELECT id FROM radicals WHERE character = '113')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('称', 'N1', 'appellation, praise, admire, name, title, fame', 'XƯNG,XỨNG(tên,đặt tựa,danh xưng)', 'Hòa Triệt Tiểu là Xưng tên.', ARRAY['ショウ'], ARRAY['たた.える','とな.える','あ.げる','かな.う','はか.り','はか.る','ほめ.る'], 10, 985, (SELECT id FROM radicals WHERE character = '115')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('章', 'N2', 'badge, chapter, composition, poem, design', 'CHƯƠNG(đoạn văn)', 'Lập Tảo là CHương hồi.sáng sớm đứng nhận huân chương.障:Thêm Phụ là Chướng ngại.彰:Thêm Sam là CHương(rực rỡ).', ARRAY['ショウ'], NULL, 11, 990, (SELECT id FROM radicals WHERE character = '117')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('笑', 'N3', 'laugh', 'TIẾU(cười,tiếu lâm)', 'Trúc Yêu là Tiếu cười.', ARRAY['ショウ'], ARRAY['わら.う','え.む'], 10, 913, (SELECT id FROM radicals WHERE character = '118')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
