INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('衝', 'N1', 'collide, brunt, highway, opposition (astronomy), thrust, pierce, stab, prick', 'XUNG(đụng độ,xung đột)', 'Hành Trọng là Xung đột.腫:Thay Nhục là THũng(khối u).種:Thay Hòa là Chủng loại.', ARRAY['ショウ'], ARRAY['つ.く'], 15, 972, (SELECT id FROM radicals WHERE character = '144')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
