INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('訟', 'N1', 'sue, accuse', 'TỤNG(kiện tụng)', 'Ngôn Công là Tụng kiện tụng.kiện TỤNG ở Công đường.松:Thay Mộc là cây TÙng.', ARRAY['ショウ'], NULL, 11, 1061, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('証', 'N1', 'evidence, proof, certificate', 'CHỨNG(chứng cứ)', 'Ngôn CHính là CHứng cứ.lời nói （言）đúng chính xác ( 正）được đưa ra làm CHỨNG.症:Thay Nạch là CHứng bệnh.', ARRAY['ショウ'], ARRAY['あかし'], 12, 306, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('詔', 'N1', 'imperial edict', 'CHIẾU(lệnh vua)', 'Ngôn Triệu là CHiếu lệnh vua ban.Triệu hồi bằng CHIẾU chỉ.照:Thêm Nhật Hỏa là CHiếu sáng.沼:Thay Thủy là CHiểu(ao đầm).', ARRAY['ショウ'], ARRAY['みことのり'], 12, 2239, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('詳', 'N1', 'detailed, full, minute, accurate, well-informed', 'TƯỜNG(tường tận)', 'Ngôn Dương là Tường rõ ràng.洋:Thay Thủy là DƯơng(phương Tây).祥:Thay Thị là cát Tường.', ARRAY['ショウ'], ARRAY['くわ.しい','つまび.らか'], 13, 1178, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('象', 'N2', 'elephant, pattern after, imitate, image, shape, sign (of the times)', 'TƯỢNG(con voi,ấn tượng)', 'Đắp TƯỢNG hình đầu Muỗi thân Lợn.像:Thêm Nhân là Tượng(hình tượng)', ARRAY['ショウ','ゾウ'], ARRAY['かたど.る'], 12, 394, (SELECT id FROM radicals WHERE character = '152')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('賞', 'N2', 'prize, reward, praise', 'THƯỞNG(giải thưởng)', 'Thượng Bối là Thưởng giải thưởng.Nhân Viên đội Mũ lên nhận THƯỞNG.償:Thêm Nhân là bồi Thường.', ARRAY['ショウ'], ARRAY['ほ.める'], 15, 426, (SELECT id FROM radicals WHERE character = '154')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鐘', 'N1', 'bell, gong, chimes', 'CHUNG(cái chuông)', 'Kim Đồng(trẻ con:童Lập Lí)là Chung cái chuông.Trẻ con nhi đồng chơi chuông kim loại憧:Thay Tâm là Sung(mong ước).瞳:Thay Mục là Đồng tử.', ARRAY['ショウ'], ARRAY['かね'], 20, 1681, (SELECT id FROM radicals WHERE character = '167')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('障', 'N1', 'hinder, hurt, harm', 'CHƯỚNG(ngăn trở,gió chướng,che,ngăn)', 'Phụ Chương(hồi,sách:章Âm Thập)là Chướng ngại.彰:Thay Sam là Chương(rực rỡ).', ARRAY['ショウ'], ARRAY['さわ.る'], 14, 742, (SELECT id FROM radicals WHERE character = '170')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鞘', 'BEYOND', 'sheath, case, margin, difference, shells (of beans)', '', '', ARRAY['ショウ','ソウ'], ARRAY['さや'], 16, NULL, (SELECT id FROM radicals WHERE character = '177')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
