INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('丈', 'N2', 'length, ten shaku, measure, Mr., Ms., height, stature, all (one has), only, that''s all, merely', 'TRƯỢNG(Thước đo)', 'rang rộng tay chân ra đo chiều cao', ARRAY['ジョウ'], ARRAY['たけ','だけ'], 3, 1375, (SELECT id FROM radicals WHERE character = '1')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('丞', 'BEYOND', 'help', '', '', ARRAY['ジョウ','ショウ'], ARRAY['すく.う','たす.ける'], 6, NULL, (SELECT id FROM radicals WHERE character = '1')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('乗', 'N3', 'ride, power, multiplication, record, counter for vehicles, board, mount, join', 'THỪA(Lên xe)', 'LEO LÊN cây đứng chặt những cành THỪA', ARRAY['ジョウ','ショウ'], ARRAY['の.る','-の.り','の.せる'], 9, 377, (SELECT id FROM radicals WHERE character = '4')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('冗', 'N1', 'superfluous, uselessness', 'NHŨNG(lộn xộn,thừa)', 'Mịch KỶ:mịch(trùm khăn) ngồi ghế tham nhũng', ARRAY['ジョウ'], NULL, 4, 1782, (SELECT id FROM radicals WHERE character = '14')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('剰', 'N1', 'surplus, besides', 'THẶNG(thừa,thặng dư)', 'Thừa đao là dư đao là THẶNG dư THỪA ĐAO là THẶNG', ARRAY['ジョウ'], ARRAY['あまつさえ','あま.り','あま.る'], 11, 1448, (SELECT id FROM radicals WHERE character = '18')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('城', 'N2', 'castle', 'THÀNH(thành lũy)', 'Tường THÀNH thì luôn làm bằng ĐẤT', ARRAY['ジョウ','セイ'], ARRAY['しろ'], 9, 795, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('場', 'N4', 'location, place', 'TRƯỜNG,TRÀNG(chỗ,nơi chốn,từ trường)', 'Trường 場 là khu Đất 土 có nhiều Dương 昜 khíthổ dương là trường', ARRAY['ジョウ','チョウ'], ARRAY['ば'], 12, 52, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('壌', 'N1', 'lot, earth, soil', 'NHƯỠNG(đất trồng trọt,thổ nhưỡng)', 'cô Nương (嬢) đó bỏ nghề làm gái (女) về quê làm Thổ (土) NhưỡngNhưỡng (lên men):醸Nhượng (nhượng bộ):譲Nương(cô gái):嬢Thổ lục...', ARRAY['ジョウ'], ARRAY['つち'], 16, 1407, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('嬢', 'N1', 'lass, girl, Miss, daughter', 'NƯƠNG(con gái,nàng) giống nương(娘)', 'cô nương mặc 6 bộ y phụcNhưỡng(thổ nhưỡng):thổ tương( 襄):壌Nhưỡng(lên men):dậu tương:醸Nhượng(nhượng bộ):ngôn tương:譲', ARRAY['ジョウ'], ARRAY['むすめ'], 16, 2059, (SELECT id FROM radicals WHERE character = '38')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('常', 'N3', 'usual, ordinary, normal, common, regular, continually, always, long-lasting', 'THƯỜNG(thường,luôn,bình thường)', 'Thượng Cân là Thường(bình thường)', ARRAY['ジョウ'], ARRAY['つね','とこ-'], 11, 293, (SELECT id FROM radicals WHERE character = '50')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('情', 'N3', 'feelings, emotion, passion, sympathy, circumstances, facts', 'TÌNH(tình cảm)', 'Tâm Thanh TÌnh.con tim màu xanh là có tình cảm', ARRAY['ジョウ','セイ'], ARRAY['なさ.け'], 11, 235, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('条', 'N1', 'article, clause, counter for articles, clauses, paragraphs, etc., twig, item, stripe, streak', 'ĐIỀU(điều kiện,điều khoản)', 'Tri mộc là Điều kiện.', ARRAY['ジョウ','チョウ','デキ'], ARRAY['えだ','すじ'], 7, 363, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('杖', 'BEYOND', 'staff, cane', '', '', ARRAY['ジョウ'], ARRAY['つえ'], 7, 2387, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('浄', 'N1', 'clean, purify, cleanse, exorcise, Manchu Dynasty', 'TỊNH(thanh tịnh,sạch)', 'Thủy Tranh là Tịnh.Đất Nước không còn chiến Tranh trở thành nơi thanh TỊNH.静:Thay Thanh là Tĩnh lặng.', ARRAY['ジョウ','セイ'], ARRAY['きよ.める','きよ.い'], 9, 1383, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('状', 'N3', 'status quo, conditions, circumstances, form, appearance', 'TRẠNG(trạng thái)', 'Tường Khuyển là Trạng thái.Trạng thái: chó đái bờ tường', ARRAY['ジョウ'], NULL, 7, 298, (SELECT id FROM radicals WHERE character = '94')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('畳', 'N2', 'tatami mat, counter for tatami mats, fold, shut up, do away with', 'ĐIỆP(chiếu,gấp lại,đv đo chiếu tatami)', 'Điền Mịch Thả là Điệp chiếu tatami.', ARRAY['ジョウ','チョウ'], ARRAY['たた.む','たたみ','かさ.なる'], 12, 1665, (SELECT id FROM radicals WHERE character = '102')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('穣', 'BEYOND', 'good crops, prosperity, 10**28', '', '', ARRAY['ジョウ'], ARRAY['わら','ゆたか'], 18, 2464, (SELECT id FROM radicals WHERE character = '115')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('蒸', 'N2', 'steam, heat, sultry, foment, get musty', 'CHƯNG(bốc hơi,hơi nước)', 'Thảo Tử Hỏa là Chưng cất.Bọn nó đang HẤP bánh CHƯNG của con LIỄU trên bãi CỎ', ARRAY['ジョウ','セイ'], ARRAY['む.す','む.れる','む.らす'], 13, 1552, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('譲', 'N1', 'defer, turnover, transfer, convey', 'NHƯỢNG(chuyển nhượng,nhường)', 'Ngôn Tương(襄)là Nhượng bộ.嬢:Thay Nữ là Nương(cô gái).醸:Thay Dậu là Nhưỡng(lên men).壌:Thay Thổ là thổ Nhưỡng.', ARRAY['ジョウ'], ARRAY['ゆず.る'], 20, 984, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('醸', 'N1', 'brew, cause', 'NHƯỠNG(lên men)', 'cô nương đang lên men rượu.嬢:Thay Nữ là Nương(cô gái).譲:Thay Ngôn là Nhượng bộ.壌:Thay Thổ là thổ Nhưỡng.', ARRAY['ジョウ'], ARRAY['かも.す'], 20, 1838, (SELECT id FROM radicals WHERE character = '164')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('錠', 'N1', 'lock, fetters, shackles', 'ĐĨNH(thoi vàng,cái khóa)', 'Kim Định là Đĩnh(đĩnh vàng:thoi vàng).綻:Thay Mịch là Trán(đường khâu)', ARRAY['ジョウ'], NULL, 16, 1934, (SELECT id FROM radicals WHERE character = '167')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('嘱', 'N1', 'entrust, request, send a message', 'CHÚC(tới thuộc về tới,di chúc)', 'Vua VŨ(禹:Trùng và Nhựu) để lại di CHÚC bằng mồm và thây người chếtKhẩu Thuộc(Phụ thuộc)属 là Chúc', ARRAY['ショク'], ARRAY['しょく.する','たの.む'], 15, 1903, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('埴', 'BEYOND', 'clay', '', '', ARRAY['ショク'], ARRAY['はに','へな'], 11, 2150, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('飾', 'N1', 'decorate, ornament, adorn, embellish', 'SỨC(trang trí)', 'Người có của ăn của để (食) ở thành thị (市) thường thích làm đẹp, trang trí, đeo trang SỨC', ARRAY['ショク'], ARRAY['かざ.る','かざ.り'], 13, 1193, (SELECT id FROM radicals WHERE character = '184')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('拭', 'N1', 'wipe, mop, swab', 'THỨC(lau chùi)', 'Thủ Thức(nghi thức,cách:式 ) là THức.試:Thêm Ngôn là Thí nghiệm.', ARRAY['ショク','シキ'], ARRAY['ぬぐ.う','ふ.く'], 9, 2421, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('植', 'N2', 'plant', 'THỰC(thực vật,trồng)', 'Mộc Trực là Thực.Trực tiếp trồng cây.殖:Thêm Đãi là Thực dân', ARRAY['ショク'], ARRAY['う.える','う.わる'], 12, 699, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('殖', 'N1', 'augment, increase, multiply, raise', 'THỰC(sinh sôi,tăng)', 'Đãi Trực là Thực.Chính quyền thực dân trực tiếp làm tăng ngừoi chết.植:Thêm Mộc là Thực(trồng cây)', ARRAY['ショク'], ARRAY['ふ.える','ふ.やす'], 12, 1362, (SELECT id FROM radicals WHERE character = '78')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('燭', 'BEYOND', 'light, candlepower', '', '', ARRAY['ソク','ショク'], ARRAY['ともしび'], 17, NULL, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('織', 'N1', 'weave, fabric', 'CHỨC(dệt vải)', 'Mịch Âm QUa là CHức dệt vải.識:Thay Ngôn là tri Thức.職:Thay Nhĩ là CHức vụ', ARRAY['ショク','シキ'], ARRAY['お.る','お.り','おり','-おり','-お.り'], 18, 608, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('職', 'N3', 'post, employment, work', 'CHỨC(nghề nghiệp)', 'Nhĩ Âm Qua là Chức vụ.Dùng tai lắng nghe âm thanh của vũ khí va chạm vào nhau là CHỨC vụ của người lính.識:Thay Ngôn là tri Thức.織:thay Mịch là Chức(dệt vải).', ARRAY['ショク','ソク'], NULL, 18, 305, (SELECT id FROM radicals WHERE character = '128')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('色', 'N4', 'color', '', '', ARRAY['ショク','シキ'], ARRAY['いろ'], 6, 621, (SELECT id FROM radicals WHERE character = '139')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
