INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('食', 'N5', 'eat, food', '', '', ARRAY['ショク','ジキ'], ARRAY['く.う','く.らう','た.べる','は.む'], 9, 328, (SELECT id FROM radicals WHERE character = '184')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('辱', 'N1', 'embarrass, humiliate, shame', 'NHỤC(xấu hổ)', 'Thần Thốn là Nhục.Thần mà bị thốn thì đúng là Nhục.震:Thay Vũ là địa Chấn.振:Thay Thủ là CHấn động.娠:Thay Nữ là Thần(mang thai).唇:Thay Khẩu là Thần(son môi).', ARRAY['ジョク'], ARRAY['はずかし.める'], 10, 1769, (SELECT id FROM radicals WHERE character = '161')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('尻', 'N2', 'buttocks, hips, butt, rear', 'CỪU(cái mông)', 'hình ảnh doggy bằng mông trước cửaThi cửu cừu mông', ARRAY['コウ'], ARRAY['しり'], 5, 1692, (SELECT id FROM radicals WHERE character = '44')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('伸', 'N2', 'expand, stretch, extend, lengthen, increase', 'THÂN(Duỗi. Làm cho phải lẽ.)', 'Thân người duỗi thẳng申:Thân,tuổi thânNhân Thân là THân', ARRAY['シン'], ARRAY['の.びる','の.ばす','の.べる','の.す'], 7, 730, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('信', 'N3', 'faith, truth, fidelity, trust', 'TÍN(Không sai lời hẹn,tin tức,thạch tín)', 'Người Nói lời giữ lấy lời :TÍN', ARRAY['シン'], NULL, 9, 208, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('侵', 'N1', 'encroach, invade, raid, trespass, violate', 'XÂM(Xâm lấn,xâm chiến)', 'người trở lại lấy khăn phủ lên đầu heo(kệ) là kẻ đi xâm chiếmNGƯỜI mà k NGỦ (寝) trong nhà dễ bị XÂM hại.Xâm tẩm(浸:thẩm thấu) tẩm(ngủ寝)', ARRAY['シン'], ARRAY['おか.す'], 9, 1025, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('唇', 'N1', 'lips', 'THẦN(đôi môi)', 'Thần 辰 khẩu:THẦN(môi) thái miệng thể hiện trên môigiờ thìn và cái mồm là đôi môi(Thần)', ARRAY['シン'], ARRAY['くちびる'], 10, 1992, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('娠', 'N1', 'with child, pregnancy', 'THẦN(có thai,chửa)', 'nữ sinh có Thần vào giờ thìn', ARRAY['シン'], NULL, 10, 1623, (SELECT id FROM radicals WHERE character = '38')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('寝', 'N3', 'lie down, sleep, rest, bed, remain unsold', 'TẨM(ngủ)', 'Thị Tẩm vào trong nhà 宀 đi yo 彐 giường (丬) trùm khăn 冖 lại 又 rồi ngủ 寝 chung với hoàng thượng :V', ARRAY['シン'], ARRAY['ね.る','ね.かす','い.ぬ','みたまや','や.める'], 13, 1034, (SELECT id FROM radicals WHERE character = '40')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('審', 'N1', 'hearing, judge, trial', 'THẨM(thẩm tra,xét rõ,xét hỏi)', 'Trong nhà có phiên(lần lượt:番) toà phúc thẩm', ARRAY['シン'], ARRAY['つまび.らか','つぶさ.に'], 15, 412, (SELECT id FROM radicals WHERE character = '40')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('心', 'N4', 'heart, mind, spirit, heart radical (no. 61)', '', '', ARRAY['シン'], ARRAY['こころ','-ごころ'], 4, 157, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('慎', 'N1', 'humility, be careful, discreet, prudent', 'THẬN(thận trọng,cẩn thận)', 'Tâm Chân(真:Chân thật)  là Thận trọng.Con tim chân thật thì rất cẩn thận.鎮:Thêm KIm là Trấn(trấn áp).', ARRAY['シン'], ARRAY['つつし.む','つつ.ましい','つつし','つつし.み'], 13, 999, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('振', 'N1', 'shake, wave, wag, swing', 'CHẤN(vẫy,lúc lắc,chấn chỉnh)', 'Thủ Thần là CHấn.giờ thìn tay phấn chấn娠:Thêm Nữ là Thần(mang thai)', ARRAY['シン'], ARRAY['ふ.る','ふ.れる','ふ.るう'], 10, 614, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('新', 'N4', 'new', 'TÂN(mới)', 'Thân(người thân:亲:lập mộc) Cân là Tân.薪:Thêm Thảo là Tân(củi)', ARRAY['シン'], ARRAY['あたら.しい','あら.た','あら-','にい-'], 13, 51, (SELECT id FROM radicals WHERE character = '69')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
