INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('浸', 'N1', 'immersed, soak, dip, steep, moisten, wet, dunk', 'TẨM(thấm ướt),ngâm', 'Thủy Kệ Mịch Hựu là Tẩm ướp.侵:Thay Nhân là Xâm lược', ARRAY['シン'], ARRAY['ひた.す','ひた.る','つ.かる'], 10, 1447, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('深', 'N3', 'deep, heighten, intensify, strengthen', 'THÂM(sâu,rất,lắm)', 'Thủy Mịch Nhân Mộc là Thâm sâu.Vứt cái CÂY xuống nước để đo độ sâu của lòng sông', ARRAY['シン'], ARRAY['ふか.い','-ぶか.い','ふか.まる','ふか.める','み-'], 11, 484, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('申', 'N3', 'have the honor to, sign of the monkey, 3-5PM, ninth sign of Chinese zodiac', 'THÂN(nói,xưng tên,Chi Thân)', 'Điền Cổn Thân tý thìn.伸:Thêm Nhân là Thân(duỗi thẳng).紳:Thêm Mịch là Thân(đàn ông).神:Thêm Thị là Thần thánh.', ARRAY['シン'], ARRAY['もう.す','もう.し-','さる'], 5, 492, (SELECT id FROM radicals WHERE character = '102')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('真', 'N4', 'true, reality, Buddhist sect', 'CHÂN(chân thật)', 'Thập Cụ là Chân thật.鎮:Thêm Kim là Trấn áp.慎:Thêm Tâm là Thận trọng.', ARRAY['シン'], ARRAY['ま','ま-','まこと'], 10, 279, (SELECT id FROM radicals WHERE character = '109')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
