INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('薪', 'N1', 'fuel, firewood, kindling', 'TÂN(củi)', 'Thảo Tân là Tân củi.Cỏ mới dùng làm củi', ARRAY['シン'], ARRAY['たきぎ','まき'], 16, 2182, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('親', 'N4', 'parent, intimacy, relative, familiarity, dealer (cards)', 'THÂN(thân thiện)', 'Lập Mộc Kiến là Thân THiện.đứng(lập) trên cây (mộc) nhìn xem người thân của mình ở đâu.新:Thay Cân là Tân mới.薪:Thêm Thảo là Tân củi.', ARRAY['シン'], ARRAY['おや','おや-','した.しい','した.しむ'], 16, 406, (SELECT id FROM radicals WHERE character = '147')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
