INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('酔', 'N1', 'drunk, feel sick, poisoned, elated, spellbound', 'TÚY(say rượu)', 'Dậu Cửu Thập là Túy quyền.9,10 chén rượu thì chẳng say tuý quyền.粋:Thay Mễ là tinh Túy.砕:Thay Thạch là Toái(phá vỡ).枠:Thay Mộc là cái Khung.', ARRAY['スイ'], ARRAY['よ.う','よ.い','よ'], 11, 1640, (SELECT id FROM radicals WHERE character = '164')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
