INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('随', 'N1', 'follow, though, notwithstanding, while, during, both, all, obey, submit to, comply, at the mercy of (the waves)', 'TÙY(đi theo)', 'Phụ Sước Hữu là Tùy tùng,đi theo.髄:Thay Cốt là Tủy(xương).', ARRAY['ズイ'], ARRAY['まにま.に','したが.う'], 12, 1396, (SELECT id FROM radicals WHERE character = '170')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
