INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('数', 'N3', 'number, strength, fate, law, figures', 'SỐ(con số)', 'Mễ Nữ Phộc là SỐ liệu.Người PHỤ NỮ là người phải ghi SỔ sách số GẠO trong nhà', ARRAY['スウ','ス','サク','ソク','シュ'], ARRAY['かず','かぞ.える','しばしば','せ.める','わずらわ.しい'], 13, 148, (SELECT id FROM radicals WHERE character = '66')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
