INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('杉', 'N1', 'cedar, cryptomeria', 'SAM(cây thông Nhật,cây tuyết tùng)', 'Mộc Sam là Sam.cây trông giống tóc đuôi SAM là cây tuyết tùng', ARRAY['サン'], ARRAY['すぎ'], 7, 1095, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
