INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('裾', 'N1', 'cuff, hem, foot of mountain', 'CỨ(vạt áo,gấu áo,gấu quần)', 'Y Cư(ở,ẩn cư:居Thi Cổ)là Cứ,Cư vạt áo.据:Thay Thủ là CƯ(lắp đặt).', ARRAY['キョ','コ'], ARRAY['すそ'], 13, 2334, (SELECT id FROM radicals WHERE character = '145')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('澄', 'N1', 'lucidity, be clear, clear, clarify, settle, strain, look grave', 'TRỪNG(lắng trong,thanh trừng)', 'Thủy Đăng(lên,đăng ký:登.Bát Đậu) là Trừng lắng trong.Nước lọc đậu trở lại là lắng trong,thanh trừng.', ARRAY['チョウ'], ARRAY['す.む','す.ます','-す.ます'], 15, 1722, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
