INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('畝', 'N1', 'furrow, thirty tsubo, ridge, rib', 'MẪU(100m2)', 'Đầu ĐIền Cửu là Mẫu ruộng.', ARRAY['ボウ','ホ','モ','ム'], ARRAY['せ','うね'], 10, 2327, (SELECT id FROM radicals WHERE character = '102')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('是', 'N1', 'just so, this, right, justice', 'THỊ(đúng,phải)', 'Nhật SƠ là THị.Hàng ngày chạy tìm chuyện thị phi để làm chủ đề.堤:Thêm THổ là Đê(con đê).題:Thêm Hiệt là Đề(vấn đề).提:Thêm Thủ là Đề án', ARRAY['ゼ','シ'], ARRAY['これ','この','ここ'], 9, 1045, (SELECT id FROM radicals WHERE character = '72')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('凄', 'N1', 'uncanny, weird, threatening, horrible', 'THÊ(thê thảm: kinh khủng,kinh dị)', 'băng THÊ(妻:phụ nữ nô lệ.kkk) tử mà Lạnh lùng như Băng thì thật là KINH KHỦNG,THÊ thảm. Sugoi', ARRAY['セイ','サイ'], ARRAY['さむ.い','すご.い','すさ.まじい'], 10, 2313, (SELECT id FROM radicals WHERE character = '15')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('制', 'N3', 'system, law, rule', 'CHẾ(làm,cầm,quy chế,hạn chế)', 'Cầm dao khống chế 制 con bò 牛 nằm yên trên cái cân', ARRAY['セイ'], NULL, 8, 108, (SELECT id FROM radicals WHERE character = '18')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('勢', 'N2', 'forces, energy, military strength', 'THẾ(thế lực,uy thế)', 'Người có THẾ lực: Người có nhiều đất đi vòng tròn mãi ko hếtcông tử bạc liêuNhiệt(nhiệt độ):熱', ARRAY['セイ','ゼイ'], ARRAY['いきお.い','はずみ'], 13, 260, (SELECT id FROM radicals WHERE character = '19')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('姓', 'N2', 'surname', 'TÍNH(họ,dòng họ)', 'Đặc TÍNH của PHỤ NỮ là SINH sản', ARRAY['セイ','ショウ'], NULL, 8, 1628, (SELECT id FROM radicals WHERE character = '38')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('征', 'N1', 'subjugate, attack the rebellious, collect taxes', 'CHINH(chinh phục,đi xa,trường chinh)', 'Xích Chánh là CHinh phục.Chinh phục con đường chân chính', ARRAY['セイ'], NULL, 8, 1578, (SELECT id FROM radicals WHERE character = '60')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('性', 'N3', 'sex, gender, nature', 'TÍNH(tính cách)', 'Tâm Sinh Tính', ARRAY['セイ','ショウ'], ARRAY['さが'], 8, 104, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('成', 'N3', 'turn into, become, get, grow, elapse, reach', 'THÀNH(thành công,nên,hoàn thành)', 'có vượt QUA được muôn VẠN khó khăn thì mới THÀNH công được城:Thêm Thổ là Thành lũy.誠:Thêm ngôn là Thành thực.盛:Thêm sành là Thịnh hành', ARRAY['セイ','ジョウ'], ARRAY['な.る','な.す','-な.す'], 6, 116, (SELECT id FROM radicals WHERE character = '62')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('政', 'N3', 'politics, government', 'CHÍNH(chính phủ)', 'Chánh,CHính Phốc là Chính Phủ.CHÍNH (政) trị: hoặc làm ĐÚNG (正) hoặc bị ĐÁNH (攵).', ARRAY['セイ','ショウ'], ARRAY['まつりごと','まん'], 9, 17, (SELECT id FROM radicals WHERE character = '66')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('整', 'N1', 'organize, arranging, tune, tone, meter, key (music)', 'CHỈNH(điều chỉnh,đều,ngay ngắn,sửa sang)', 'Sắc Chính,Chánh là Chỉnh(điều chỉnh)', ARRAY['セイ'], ARRAY['ととの.える','ととの.う'], 16, 478, (SELECT id FROM radicals WHERE character = '66')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('星', 'N2', 'star, spot, dot, mark', 'TINH(ngôi sao)', 'Nhật SInh TInh sao.', ARRAY['セイ','ショウ'], ARRAY['ほし','-ぼし'], 9, 844, (SELECT id FROM radicals WHERE character = '72')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('晴', 'N3', 'clear up', 'TÌNH(trời nắng)', 'Nhật Thanh là Tình.', ARRAY['セイ'], ARRAY['は.れる','は.れ','は.れ-','-ば.れ','は.らす'], 12, 1022, (SELECT id FROM radicals WHERE character = '72')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
