INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('正', 'N4', 'correct, justice, righteous, 10**40', 'CHÍNH,CHÁNH(chính xác,phải)', 'Nhất CHỉ  CHính', ARRAY['セイ','ショウ'], ARRAY['ただ.しい','ただ.す','まさ','まさ.に'], 5, 143, (SELECT id FROM radicals WHERE character = '77')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('清', 'N2', 'pure, purify, cleanse, exorcise, Manchu dynasty', 'THANH(trong sạch,thanh liêm,trong)', 'Thủy Thanh là Thanh liêm.Nước xanh biếc thể hiện sự thanh khiết.', ARRAY['セイ','ショウ','シン'], ARRAY['きよ.い','きよ.まる','きよ.める'], 11, 705, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('牲', 'N1', 'animal sacrifice, offering', 'SINH(hy sinh)', 'Ngưu Sinh là hy sinh.con TRÂU được SINH ra là để HY SINH làm thức ăn', ARRAY['セイ'], NULL, 9, 1274, (SELECT id FROM radicals WHERE character = '93')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('生', 'N5', 'life, genuine, birth', '', '', ARRAY['セイ','ショウ'], ARRAY['い.きる','い.かす','い.ける','う.まれる','うま.れる','う.まれ','うまれ','う.む','お.う','は.える','は.やす','き','なま','なま-','な.る','な.す','む.す','-う'], 5, 29, (SELECT id FROM radicals WHERE character = '100')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('盛', 'N1', 'boom, prosper, copulate', 'THỊNH(phồn thịnh,thịnh vượng)', 'Thành mãnh là Thịnh.Thành công nằm trên đĩa thì là thịnh vượng', ARRAY['セイ','ジョウ'], ARRAY['も.る','さか.る','さか.ん'], 11, 712, (SELECT id FROM radicals WHERE character = '108')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('精', 'N3', 'refined, ghost, fairy, energy, vitality, semen, excellence, purity, skill', 'TINH(tinh thần)', 'Mễ Thanh là Tinh thần.gạo là tinh hoa mà trời xanh ban cho ta.情:Thay Tâm là Tình cảm.晴:Thay Nhật là Tình trời nắng.', ARRAY['セイ','ショウ'], ARRAY['しら.げる','くわ.しい'], 14, 752, (SELECT id FROM radicals WHERE character = '119')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('聖', 'N1', 'holy, saint, sage, master, priest', 'THÁNH(thần thánh)', 'Vua mà biết nói và lắng nghe thì đc tôn lên làm THÁNH.69. 翰 hàn lông 70. 翼 dực cánh 71. 聖 thánh thánh 72. 賢 hiền hiền', ARRAY['セイ','ショウ'], ARRAY['ひじり'], 13, 1165, (SELECT id FROM radicals WHERE character = '128')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('声', 'N3', 'voice', 'THANH(tiếng nói)', 'Binh SĨ thấy xác chết (THI) kêu thất THANH.', ARRAY['セイ','ショウ'], ARRAY['こえ','こわ-'], 7, 388, (SELECT id FROM radicals WHERE character = '33')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('製', 'N1', 'made in..., manufacture', 'CHẾ(chế tạo,làm ra)', 'Chế(phép,chế độ,quy đinh:制) Y là Chế tạo.', ARRAY['セイ'], NULL, 14, 488, (SELECT id FROM radicals WHERE character = '145')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('西', 'N5', 'west, Spain', '', '', ARRAY['セイ','サイ','ス'], ARRAY['にし'], 6, 259, (SELECT id FROM radicals WHERE character = '146')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('誠', 'N1', 'sincerity, admonish, warn, prohibit, truth, fidelity', 'THÀNH(thành thật)', 'Ngôn Thành là Thành thực.城:Thay Thổ là Thành lũy.盛:Thay Mãnh là hưng Thịnh.', ARRAY['セイ'], ARRAY['まこと'], 13, 1128, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('誓', 'N1', 'vow, swear, pledge', 'THỆ(thề ước)', 'CHiết(bẻ gãy:折Thủ Cân) Ngôn là Thệ ước.逝:Thay Sước là Thệ(chết).', ARRAY['セイ'], ARRAY['ちか.う'], 14, 1567, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('請', 'N1', 'solicit, invite, ask', 'THỈNH(thỉnh cầu)', 'Ngôn Thanh là Thỉnh cầu.Dùng lời nói ngon ngọt để thỉnh an Hoàng hậu.清:Thay Thủy là Thanh khiết.静:Thay Tranh là Tĩnh lặng.', ARRAY['セイ','シン','ショウ'], ARRAY['こ.う','う.ける'], 15, 524, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('逝', 'N1', 'departed, die', 'THỆ(chết)', 'Sước Chiết là Thệ chết.Thằng triết tuyên thệ thề chết không chạy.誓:Thay Ngôn mới là tuyên THệ.', ARRAY['セイ'], ARRAY['ゆ.く','い.く'], 10, 2018, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('醒', 'N1', 'awake, be disillusioned, sober up', 'TỈNH(tỉnh rượu)', 'Dậu Tinh là Tỉnh rượu.Uống rượu ngắm sao tỉnh sự đời', ARRAY['セイ'], ARRAY['さ.ます','さ.める'], 16, NULL, (SELECT id FROM radicals WHERE character = '164')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('青', 'N4', 'blue, green', '', '', ARRAY['セイ','ショウ'], ARRAY['あお','あお-','あお.い'], 8, 589, (SELECT id FROM radicals WHERE character = '174')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('静', 'N3', 'quiet', 'TĨNH(yên tĩnh)', 'Thanh Tranh là Tĩnh lặng.Sau chiến tranh lại thanh bình yên tĩnh như xưa.浄:Thay Thủy là thanh Tịnh.', ARRAY['セイ','ジョウ'], ARRAY['しず-','しず.か','しず.まる','しず.める'], 14, 764, (SELECT id FROM radicals WHERE character = '174')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('斉', 'N1', 'adjusted, alike, equal, similar variety of', 'TỀ(đều,đồng loạt)', 'Anh Văn ăn mặc Chỉnh TỀ đi gặp chị Nguyệt.済:Thêm Thủy là kinh Tế.剤:Thêm đao là dịch Tễ,thuốc Tễ.', ARRAY['セイ','サイ'], ARRAY['そろ.う','ひと.しい','ひと.しく','あたる','はやい'], 8, 1209, (SELECT id FROM radicals WHERE character = '67')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('税', 'N2', 'tax, duty', 'THUẾ(tiền thuế)', 'Hòa Đoài(chi trả,quẻ Đoài:兑)là Thuế.', ARRAY['ゼイ'], NULL, 12, 289, (SELECT id FROM radicals WHERE character = '115')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('隻', 'N2', 'vessels, counter for ships, fish, birds, arrows, one of a pair', 'CHÍCH(đv đếm tàu)', 'Chuy Hựu là Chích:chiếc,đv đếm tàu.LẠI là con CHIM CHÍCH', ARRAY['セキ'], NULL, 10, 1546, (SELECT id FROM radicals WHERE character = '172')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('席', 'N3', 'seat, mat, occasion, place', 'TỊCH(chỗ ngồi,chiếu)', 'sàng( 床) giường,tịch(席) chiếu,khiếm thiếu,dư thừaTrong nhà có 20(nhập) cái khănNghiễm nhập cân tịch', ARRAY['セキ'], ARRAY['むしろ'], 10, 370, (SELECT id FROM radicals WHERE character = '50')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('惜', 'N1', 'pity, be sparing of, frugal, stingy, regret', 'TÍCH(tiếc nuối,đau tiếc)', 'Tâm Tích(昔:cổ tích,ngày xưa) là Tích(nuối tiếc).Trái tim (心）TIẾC nhớ chuyện ngày xưa (昔).', ARRAY['セキ'], ARRAY['お.しい','お.しむ'], 11, 1641, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('戚', 'N1', 'grieve, relatives', 'THÍCH(thân thích,thương,lo)', 'Chú bỏ Hựu thêm Qua là THích(ngoại thích:họ hàng)', ARRAY['ソク','セキ'], ARRAY['いた.む','うれ.える','みうち'], 11, NULL, (SELECT id FROM radicals WHERE character = '62')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('斥', 'N1', 'reject, retreat, recede, withdraw, repel, repulse', 'XÍCH(đuổi,gạt ra,bài xích)', 'Cân Chủ là Xích.訴:Thêm Ngôn là TỐ cáo', ARRAY['セキ'], ARRAY['しりぞ.ける'], 5, 2231, (SELECT id FROM radicals WHERE character = '69')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('昔', 'N3', 'once upon a time, antiquity, old times', 'TÍCH(xưa cũ)', 'sự tích 20 mặt trời.', ARRAY['セキ','シャク'], ARRAY['むかし'], 8, 1197, (SELECT id FROM radicals WHERE character = '72')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('析', 'N1', 'chop, divide, tear, analyze', 'TÍCH(phân tích,gỡ,tẽ ra,chẻ)', 'Mộc Cân là Tích.Dùng rừu bổ cây ra phân tích', ARRAY['セキ'], NULL, 8, 980, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('石', 'N3', 'stone', '', '', ARRAY['セキ','シャク','コク'], ARRAY['いし'], 5, 342, (SELECT id FROM radicals WHERE character = '112')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('積', 'N3', 'volume, product (x*y), acreage, contents, pile up, stack, load, amass', 'TÍCH(chất đống,tích trữ)', 'Hòa Trách là Tích trữ.績:Thay Mịch là thành Tích.', ARRAY['セキ'], ARRAY['つ.む','-づ.み','つ.もる','つ.もり'], 16, 541, (SELECT id FROM radicals WHERE character = '115')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('籍', 'N2', 'enroll, domiciliary register, membership', 'TỊCH(quốc tịch,sổ sách để ghi chép,hộ tịch)', 'Trúc Lỗi Tích(昔:xưa) là Tịch hộ tịch.耤:Tá:nhờ giúp (Tịch điền)Ngày xưa quốc tịch đc ghi vào 3 cái cây tre', ARRAY['セキ'], NULL, 20, 907, (SELECT id FROM radicals WHERE character = '118')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('績', 'N2', 'exploits, achievements, unreeling cocoons', 'TÍCH(thành tích,xe sợi)', 'Mịch Trách là Tích đánh sợi,tích lũy.Chỉ có Trách nhiệm mới tạo ra thành Tích.積:Thay Hòa là Tích trữ.', ARRAY['セキ'], NULL, 17, 820, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('脊', 'N1', 'stature, height, spine', 'TÍCH(xương sống,có 24 đốt)', '', ARRAY['セキ'], ARRAY['せ','せい'], 10, 2299, (SELECT id FROM radicals WHERE character = '130')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('責', 'N3', 'blame, condemn, censure', 'TRÁCH(trách nhiệm)', 'Thổ Bối là Trách nhiệm.債:Thêm Nhân là Trái phiếu,khoản nợ.績:thêm Mịch là Tích(thành tích).積:Thêm Hòa là Tích trữ.漬:Thêm Thủy là Tí(ngâm tẩm).', ARRAY['セキ'], ARRAY['せ.める'], 11, 598, (SELECT id FROM radicals WHERE character = '154')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
