INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('切', 'N4', 'cut, cutoff, be sharp', 'THIẾT(cắt,cần kíp,thiết thực)', 'điều cần Thiết bây giờ là có Bảy thanh Đao,Thất Thiết kiếm', ARRAY['セツ','サイ'], ARRAY['き.る','-き.る','き.り','-き.り','-ぎ.り','き.れる','-き.れる','き.れ','-き.れ','-ぎ.れ'], 4, 324, (SELECT id FROM radicals WHERE character = '18')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('拙', 'N1', 'bungling, clumsy, unskillful', 'CHUYẾT(vụng về)', 'Thủ Xuất là CHuyết.Cầm tay chuyết mãi không xuất thì vụng về', ARRAY['セツ'], ARRAY['つたな.い'], 8, 1938, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
