INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('摂', 'N1', 'vicarious, surrogate, act in addition to, take in, absorb', 'NHIẾP(thâu vào,nhiếp chính,kiêm,thay)', 'Thủ Nhĩ .. là Nhiếp.Tay vén tai nhiếp ảnh gia lên thấy tiếp 4 đường', ARRAY['セツ','ショウ'], ARRAY['おさ.める','かね.る','と.る'], 13, 1779, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('折', 'N3', 'fold, break, fracture, bend, yield, submit', 'CHIẾT(bẻ,gấp,gập)', 'Thủ Cân là CHiết.Tay cầm búa chiết cành.哲:Thêm Khẩu là Triết học.', ARRAY['セツ','シャク'], ARRAY['お.る','おり','お.り','-お.り','お.れる'], 7, 962, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('設', 'N2', 'establishment, provision, prepare', 'THIẾT(thiết lập)', 'Ngôn Thù là Thiết lập.Lời nói chấm dứt binh đạo thiết lập hoà bình', ARRAY['セツ'], ARRAY['もう.ける'], 11, 145, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('窃', 'N1', 'stealth, steal, secret, private, hushed', 'THIẾT(ăn cắp)', 'Huyệt Thiết là THiết ăn cắp.', ARRAY['セツ'], ARRAY['ぬす.む','ひそ.か'], 9, 1871, (SELECT id FROM radicals WHERE character = '116')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('節', 'N1', 'node, season, period, occasion, verse, clause, stanza, honor, joint, knuckle, knob, knot, tune, melody', 'TIẾT(mùa,khớp xương)', 'Trúc Tức(có nghĩa là,tức là)là Tiết:đốt xương', ARRAY['セツ','セチ'], ARRAY['ふし','-ぶし','のっと'], 13, 934, (SELECT id FROM radicals WHERE character = '118')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('説', 'N3', 'opinion, theory, explanation, rumor', 'THUYẾT(thuyết phục)', 'Ngôn Đoái(quẻ Đoái,trao đổi:兌)là Thuyết(giải thích).税: Thay Hoà là Thuế má.', ARRAY['セツ','ゼイ'], ARRAY['と.く'], 14, 326, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
