INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('占', 'N2', 'fortune-telling, divining, forecasting, occupy, hold, have, get, take', 'CHIÊM,CHIẾM(xem,bói,chiếm lĩnh,chiêm tinh)', 'CHIÊM tinh gia gia cát lượng bói bằng miệngĐiểm 点(điểm số) Điếm 店(cửa hàng) Chiếm 占(chiếm lấy) Niêm 粘(dính) Thiếp 貼(dán)', ARRAY['セン'], ARRAY['し.める','うらな.う'], 5, 694, (SELECT id FROM radicals WHERE character = '25')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('宣', 'N1', 'proclaim, say, announce', 'TUYÊN(tuyên truyền)', 'Miên Tuyên(亘:phô bày) là Tuyên bố', ARRAY['セン'], ARRAY['のたま.う'], 9, 695, (SELECT id FROM radicals WHERE character = '40')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
