INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('戦', 'N3', 'war, battle, match', 'CHIẾN(chiến tranh)', 'Đơn Qua là CHiến tranh.Chiến tranh (戦) đơn giản (単) là cầm mâu (戈) đi chiến đấu', ARRAY['セン'], ARRAY['いくさ','たたか.う','おのの.く','そよ.ぐ','わなな.く'], 13, 78, (SELECT id FROM radicals WHERE character = '62')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('扇', 'N1', 'fan, folding fan', 'PHIẾN(cái quạt)', 'Hộ Vũ là Phiến.Hộ (戸)gia đình nuôi chim lấy lông vũ(羽 )làm quạt =&gt; để quạt( 扇ぐ) mát', ARRAY['セン'], ARRAY['おうぎ'], 10, 1805, (SELECT id FROM radicals WHERE character = '63')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
