INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('栓', 'N1', 'plug, bolt, cork, bung, stopper', 'XUYÊN(then cửa,nút)', 'Mộc Toàn là Xuyên then cửa.', ARRAY['セン'], NULL, 10, 2199, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('泉', 'N2', 'spring, fountain', 'TUYỀN(suối)', 'Bạch Thủy là TUyền suối.ôn tuyền là suối nước nóng.線:Thêm Mịch là Tuyến đường.腺:Thêm Nhục là TUyến(cơ thể)', ARRAY['セン'], ARRAY['いずみ'], 9, 1086, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('浅', 'N2', 'shallow, superficial, frivolous, wretched, shameful', 'THIỂN(nông cạn,thiển cận)', 'Thủy Nhị Qua là Thiển cận.践:thay Túc là thực Tiễn.銭:Thay Kim là Tiền bạc. 浅:Thêm Thủy là Thiển cận.  桟: Thay Mộc là Sạn(sàn lót gỗ,giá để đồ).Thay Đãi là Tàn dư.', ARRAY['セン'], ARRAY['あさ.い'], 9, 1253, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('洗', 'N3', 'wash, inquire into, probe', 'TẨY,TIỄN(rửa,giặt)', 'Thủy Tiên là Tẩy rửa.Muốn TẨY vết bẩn TRƯỚC tiên phải nhúng vào NƯỚC', ARRAY['セン'], ARRAY['あら.う'], 9, 1168, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('染', 'N1', 'dye, color, paint, stain, print', 'NHIỄM(nhuộm,ô nhiễm)', 'Thủy cửu Mộc Nhiễm độc.9 cái cây bị nhiễm độc bởi nước bẩn', ARRAY['セン'], ARRAY['そ.める','そ.まる','し.みる','し.み'], 9, 837, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('潜', 'N1', 'submerge, conceal, hide, lower (voice), hush', 'TIỀM(lặn,ẩn núp)', 'Thủy Thế(bỏ,thay:替) là Tiềm ẩn.', ARRAY['セン'], ARRAY['ひそ.む','もぐ.る','かく.れる','くぐ.る','ひそ.める'], 15, 1329, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('煎', 'N1', 'broil, parch, roast, boil', 'TIÊN,TIỄN(sắc,đun kỹ)', 'Tiền Hỏa là Tiên rang,sắc thuốc.', ARRAY['セン'], ARRAY['せん.じる','い.る','に.る'], 13, 2458, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('旋', 'N1', 'rotation, go around', 'TOÀN(trở lại,quay lại)', 'Phương triệt Sơ là Toàn quay lại.', ARRAY['セン'], ARRAY['め.ぐる','いばり'], 11, 1801, (SELECT id FROM radicals WHERE character = '70')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('穿', 'BEYOND', 'put on (to the feet), dig, pierce, drill', '', '', ARRAY['セン'], ARRAY['うが.つ','は.く'], 10, NULL, (SELECT id FROM radicals WHERE character = '116')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('線', 'N2', 'line, track', 'TUYẾN(đường dây)', 'Mịch Tuyền(suối:泉Bạch THủy)là Tuyến dây.sợi chỉ 糸màu trắng 白ở dưới nước水giống kim Tuyến', ARRAY['セン'], ARRAY['すじ'], 15, 382, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('繊', 'N1', 'slender, fine, thin kimono', 'TIÊM(đẹp,từ từ,nhỏ nhặt,thanh mảnh)', 'Mịch Thập Qua Nghiệp là Tiêm thanh mảnh.Muốn TIÊM được em Mịch THANH MẢNH thì phải vượt qua 10 thằng đang xếp hàng', ARRAY['セン'], NULL, 17, 1451, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('羨', 'N1', 'envious, be jealous, covet', 'TIỆN(thèm muốn)', 'Dương Thủy Khiếm là Tiện ham muốn.Tiện mộ:ái mộ.', ARRAY['セン','エン'], ARRAY['うらや.む','あまり'], 13, NULL, (SELECT id FROM radicals WHERE character = '123')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('腺', 'N1', 'gland, (kokuji)', 'TUYẾN(tuyến dịch)', 'Nhục Tuyền là Tuyến dịch.線:Thêm Mịch là Tuyến đường.', ARRAY['セン'], NULL, 13, NULL, (SELECT id FROM radicals WHERE character = '130')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('船', 'N3', 'ship, boat', 'THUYỀN(tàu,thuyền)', 'thuyền chu du qua 8 cửa khẩu)).鉛:Thay Kim là DUyên(chất chì).沿: Thay Thuỷ là Duyên dọc theo.', ARRAY['セン'], ARRAY['ふね','ふな-'], 11, 713, (SELECT id FROM radicals WHERE character = '137')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('薦', 'N1', 'recommend, mat, advise, encourage, offer', 'TIẾN(tiến hành)', 'Thảo Lộc Mã là Tiến cử.GIỚI THIỆU loại Gà Tây TIẾN hoá chỉ ăn Cỏ nuôi trong nhà', ARRAY['セン'], ARRAY['すす.める'], 16, 1082, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('詮', 'N1', 'discussion, methods called for, selection, result', 'THUYÊN(suy cho cùng,đủ)', 'Ngôn Toàn là Thuyên đủ,giải thích kỹ càng.栓:Thay Mộc là Xuyên(then chốt).', ARRAY['セン'], ARRAY['せん.ずる','かい','あき.らか'], 13, NULL, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('践', 'N1', 'tread, step on, trample, practice, carry through', 'TIỄN(thực tiễn,thực hành)', 'Cầm gươm tiễn người ra biên ải.浅:Thay Thủy là Thiển cận.銭:Thay Kim là Tiền  bạc.桟:Thay Mộc là San(giá để đồ).残:Thay Đãi là Tàn dư.', ARRAY['セン'], ARRAY['ふ.む'], 13, 1570, (SELECT id FROM radicals WHERE character = '157')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('選', 'N3', 'elect, select, choose, prefer', 'TUYỂN(lựa chọn)', 'Sước Tốn(quẻ Tốn: 巽2 Kỉ Cung)là Tuyển chọn lựa.cần TUYỂN 22 tk CỘNG tác viên', ARRAY['セン'], ARRAY['えら.ぶ','え.る','よ.る'], 15, 57, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('遷', 'N1', 'transition, move, change', 'THIÊN(dời đi,đẩy đi)', 'Sước Tây Đại Kỉ là Thiên dời,nhảy việc.Nhị Đại Ka Dẫn Đường đi Tây THIÊN', ARRAY['セン'], ARRAY['うつ.る','うつ.す','みやこがえ'], 15, 1937, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('銭', 'N1', 'coin, .01 yen, money', 'TIỀN(tiền tệ)', 'Kim Nhị Qua là Tiền tệ.践:Thay Túc là thực Tiễn.浅:thay Thủy là Thiển cận.', ARRAY['セン','ゼン'], ARRAY['ぜに','すき'], 14, 1008, (SELECT id FROM radicals WHERE character = '167')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
