INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鮮', 'N1', 'fresh, vivid, clear, brilliant, Korea', 'TIÊN(tươi,tươi sống)', 'cá và dê ăn tươi thì mới lên TIÊN', ARRAY['セン'], ARRAY['あざ.やか'], 17, 355, (SELECT id FROM radicals WHERE character = '195')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
