INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('善', 'N1', 'virtuous, good, goodness', 'THIỆN(lành,tốt,giỏi,khéo)', 'con dê ăn cỏ bằng mồm là THIỆNdương Thảo Khẩu:THiện', ARRAY['ゼン'], ARRAY['よ.い','い.い','よ.く','よし.とする'], 12, 765, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('漸', 'N1', 'steadily, gradually advancing, finally, barely', 'TIỆM(tiệm cận,dần dần)', 'Thủy Trảm(chém) là Tiệm cận.tiệm nước này chém rất cao', ARRAY['ゼン'], ARRAY['ようや.く','やや','ようよ.う','すす.む'], 14, 2115, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('然', 'N3', 'sort of thing, so, if so, in that case, well', 'NHIÊN(tự nhiên)', 'Đãi Khuyển Hỏa là thiên Nhiên.燃:Thêm Hỏa là Nhiên liệu', ARRAY['ゼン','ネン'], ARRAY['しか','しか.り','しか.し','さ'], 12, 401, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('全', 'N3', 'whole, entire, all, complete, fulfill', '', '', ARRAY['ゼン'], ARRAY['まった.く','すべ.て'], 6, 75, (SELECT id FROM radicals WHERE character = '11')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('禅', 'N1', 'Zen, silent meditation', 'THIỀN(tu thiền)', 'Thị ĐƠn là THIỀN.戦:Thay Qua là Chiến tranh.', ARRAY['ゼン','セン'], ARRAY['しずか','ゆず.る'], 13, 1902, (SELECT id FROM radicals WHERE character = '113')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('繕', 'N1', 'darning, repair, mend, trim, tidy up, adjust', 'THIỆN(vá,sửa chữa)', 'Mịch Thiện là THiện sửa chữa.膳:Thay Nguyệt là THiện(bàn ăn Nhật,Ngự Thiện Phòng)', ARRAY['ゼン'], ARRAY['つくろ.う'], 18, 2195, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('膳', 'N1', 'small low table, tray', 'THIỆN(cỗ ăn,mâm,Ngự thiện phòng)', 'Nhục Thiện là Thiện mâm.繕:Thay Mịch là Thiện(sửa chữa).', ARRAY['ゼン','セン'], ARRAY['かしわ','すす.める','そな.える'], 16, 2120, (SELECT id FROM radicals WHERE character = '130')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('噌', 'BEYOND', 'boisterous', '', '', ARRAY['ソウ','ショウ','ソ'], ARRAY['かまびす.しい'], 14, NULL, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('塑', 'N1', 'model, molding', 'TỐ(đắp,tạc tượng)', 'Thảo triệt nguyệt thổ là TốThổ nghịch ( chọc ghẹo) nguyệt nên bị tố cáo, phải bồi đắp tinh thần', ARRAY['ソ'], ARRAY['でく'], 13, NULL, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('措', 'N1', 'set aside, give up, suspend, discontinue, lay aside, except', 'THỐ(đặt để)', 'Thủ Tích(xưa:昔) là THố.Dùng tay vứt những thứ cũ ngày xưa', ARRAY['ソ'], ARRAY['お.く'], 11, 818, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('曾', 'BEYOND', 'once, before, formerly, ever, never, ex-', 'TẰNG(từng trải,chắt)', 'Cháu chắt càng ngày càng Tăng lên Tằng tằng.', ARRAY['ソウ','ソ','ゾウ'], ARRAY['かつ.て','か.って','すなわち'], 12, NULL, (SELECT id FROM radicals WHERE character = '73')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
