INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('礎', 'N1', 'cornerstone, foundation stone', 'SỞ(cơ sở,nền)', 'Thạch Sở(sở sở:duyên dáng:楚lâm Sơ)là cơ Sở.', ARRAY['ソ'], ARRAY['いしずえ'], 18, 1224, (SELECT id FROM radicals WHERE character = '112')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('祖', 'N3', 'ancestor, pioneer, founder', 'TỔ(tổ tiên)', 'Thị Thả là TỔ tiên.組:Thay Mịch là Tổ hợp.租:Thay Hòa là Tô thuế.', ARRAY['ソ'], NULL, 9, 1226, (SELECT id FROM radicals WHERE character = '113')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
