INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('粗', 'N1', 'coarse, rough, rugged', 'THÔ(cục mịch,thô tục)', 'Mễ Thả là Thô tục.THẢ bao GẠO một cách THÔ BẠO', ARRAY['ソ'], ARRAY['あら.い','あら-'], 11, 1689, (SELECT id FROM radicals WHERE character = '119')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
