INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('僧', 'N1', 'Buddhist priest, monk', 'TĂNG(tăng ni,sư nam)', 'Nhân tằng(曾,曽:cháu chắt)(tăng thêm,tằng tổ,từng,đã,có lần) làm ruộng cỏ ngày chủ nhậtNhân Tằng là tăng ni', ARRAY['ソウ'], NULL, 13, 1724, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
