INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('捜', 'N2', 'search, look for, locate', 'SƯU(tìm kiếm,sưu tầm)', 'Thủ Do Hựu là SƯu tầm.痩:Thêm Nạch là Sấu(gầy đi)', ARRAY['ソウ','シュ','シュウ'], ARRAY['さが.す'], 10, 592, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('掃', 'N2', 'sweep, brush', 'TẢO(quét dọn)', 'Thủ Trửu(帚:cái chổi) là Tảo.婦:THêm nữ  là Phụ nữ', ARRAY['ソウ','シュ'], ARRAY['は.く'], 11, 1255, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('挿', 'N1', 'insert, put in, graft, wear (sword)', 'SÁP,THÁP(cắm(cài) vào)', 'chính tay tôi SÁP nhập thêm nghìn mẫu ruộng', ARRAY['ソウ'], ARRAY['さ.す','はさ.む'], 10, 1908, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('操', 'N1', 'maneuver, manipulate, operate, steer, chastity, virginity, fidelity', 'THAO(thao tác,cầm giữ)', 'Thủ Phẩm Mộc là Thao tác.Tay thao tác.. đưa vật phẩm lên cây..', ARRAY['ソウ','サン'], ARRAY['みさお','あやつ.る'], 16, 1016, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('早', 'N4', 'early, fast', 'TẢO(sớm,nhanh chóng)', 'Nhật Thập Tảo.Ngày phải dậy trước 10h là sớm草:Thêm Thảo là Thảo(cỏ).', ARRAY['ソウ','サッ'], ARRAY['はや.い','はや','はや-','はや.まる','はや.める','さ-'], 6, 402, (SELECT id FROM radicals WHERE character = '72')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('曹', 'N1', 'office, official, comrade, fellow', 'TÀO(bầy,bọn,họ Tào)', 'Nhất Khúc Nhật là Tào tuyết cần.槽:Thêm Mộc là Tào(cái máng).遭:Thêm Sước là Tao(bắt gặp).', ARRAY['ソウ','ゾウ'], NULL, 11, 1998, (SELECT id FROM radicals WHERE character = '73')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('巣', 'N1', 'nest, rookery, hive, cobweb, den', 'SÀO(cái tổ,ổ,yến sào)', 'Có 3 SÀO RUỘNG CÂY ăn quả', ARRAY['ソウ'], ARRAY['す','す.くう'], 11, 1588, (SELECT id FROM radicals WHERE character = '47')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('槍', 'BEYOND', 'spear, lance, javelin', '', '', ARRAY['ソウ','ショウ'], ARRAY['やり'], 14, 2261, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('槽', 'N1', 'vat, tub, tank', 'TÀO(cái thùng,cái máng)', 'Mộc Tào(họ Tào:曹) là Tào cái máng.Thời xưa bể nước làm bằng gỗ sau 1 ngày đục đẽo ra được bể chửa 6 ngăn遭:Thêm Sước là Tao(bắt gặp)', ARRAY['ソウ'], ARRAY['ふね'], 15, 1809, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('漕', 'BEYOND', 'rowing, scull, paddle', '', '', ARRAY['ソウ'], ARRAY['こ.ぐ','はこ.ぶ'], 14, 2354, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('燥', 'N2', 'parch, dry up', 'TÁO(khô,táo bón,hanh hao)', 'Hỏa Phẩm Mộc là Táo khô ráo.Ba quả táo trên cây mà bị hơ lửa sẽ thành TÁO xấy khô.', ARRAY['ソウ'], ARRAY['はしゃ.ぐ'], 17, 1819, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('争', 'N3', 'contend, dispute, argue', 'TRANH(Giành nhau,gây gổ)', 'Nô lệ TRANH dành cây đao', ARRAY['ソウ'], ARRAY['あらそ.う','いか.でか'], 6, 271, (SELECT id FROM radicals WHERE character = '6')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('痩', 'N1', 'get thin', 'SẤU(gầy)', 'Nạch Thân Hựu là Sấu gầy.捜:thay Thủ là SƯu tập.', ARRAY['ソウ','チュウ','シュウ','シュ'], ARRAY['や.せる'], 12, NULL, (SELECT id FROM radicals WHERE character = '104')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('相', 'N3', 'inter-, mutual, together, each other, minister of state, councillor, aspect, phase, physiognomy', 'TƯỚNG,TƯƠNG(thủ tướng,cùng,hòa)', 'Mộc Mục là Tướng.MỤC và MỘC đọc TƯƠNG tự nhau.箱:Thêm Trúc là Tương(cái hộp).想:Thêm Tâm là Tưởng tượng.霜:Thêm Vũ là Tưởng thưởng.', ARRAY['ソウ','ショウ'], ARRAY['あい-'], 9, 45, (SELECT id FROM radicals WHERE character = '109')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('窓', 'N3', 'window, pane', 'SONG(cửa sổ)', 'Huyệt Khư Tâm là Song cửa sổ.', ARRAY['ソウ','ス'], ARRAY['まど','てんまど','けむだし'], 11, 1186, (SELECT id FROM radicals WHERE character = '116')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('総', 'N2', 'general, whole, all, full, total', 'TỔNG(tổng thể,mọi thứ)', 'Mịch Thông(gấp,vội忩:Công Tâm)là Tổng thể.Sợi chỉ công tâm, là sợi chỉ tổng hợp', ARRAY['ソウ'], ARRAY['す.べて','すべ.て','ふさ'], 14, 129, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('綜', 'BEYOND', 'rule, synthesize', '', '', ARRAY['ソウ'], ARRAY['おさ.める','す.べる'], 14, 2194, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('聡', 'BEYOND', 'wise, fast learner', '', '', ARRAY['ソウ'], ARRAY['さと.い','みみざと.い'], 14, 1507, (SELECT id FROM radicals WHERE character = '128')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('草', 'N3', 'grass, weeds, herbs, pasture, write, draft', 'THẢO(cỏ)', 'Thảo Tảo là Cỏ.Cây Cỏ thường mọc rất Nhanh (早）', ARRAY['ソウ'], ARRAY['くさ','くさ-','-ぐさ'], 9, 967, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('荘', 'N1', 'villa, inn, cottage, feudal manor, solemn, dignified', '', '', ARRAY['ソウ','ショウ','チャン'], ARRAY['ほうき','おごそ.か'], 9, 1489, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('葬', 'N1', 'interment, bury, shelve', 'TÁNG(chôn cất,mai táng)', 'Thảo Tử(chết:死)CỦng là Táng chôn.Trong lễ ăn táng đặt hoa và chắp tay cầu nguyện cho ng đã chết', ARRAY['ソウ'], ARRAY['ほうむ.る'], 12, 754, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('蒼', 'BEYOND', 'blue, pale', '', '', ARRAY['ソウ'], ARRAY['あお.い'], 13, 2276, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('藻', 'N1', 'seaweed, duckweed', 'TẢO(rong tảo)', 'Thảo Tháo,Táo(rửa tay:澡:Thủy Phẩm Mộc(Táo)là Tảo rong tảo.Tảo là sản phẩm kết hợp của cây cỏ dưới nước.燥:Thay Hỏa là Táo khô ráo.繰:Thay Mịch là Tao(kéo tơ).操:Thay Thủ là Thao tác.', ARRAY['ソウ'], ARRAY['も'], 19, 2124, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('装', 'N2', 'attire, dress, pretend, disguise, profess', 'TRANG(trang phục)', 'Tráng Y là Trang phục.Trang phục của Tráng sĩ.荘:Thay THảo là Trang(biệt thự).', ARRAY['ソウ','ショウ'], ARRAY['よそお.う','よそお.い'], 12, 657, (SELECT id FROM radicals WHERE character = '145')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('走', 'N4', 'run', '', '', ARRAY['ソウ'], ARRAY['はし.る'], 7, 626, (SELECT id FROM radicals WHERE character = '156')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('送', 'N4', 'escort, send', 'TỐNG(tiễn,gởi)', 'Sước Thảo Nhân là Tống biệt,tiễn.tống tiến mày lên tây thiên咲:Thay Khẩu là TIếu(nở hoa).Saki', ARRAY['ソウ'], ARRAY['おく.る'], 9, 311, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('遭', 'N1', 'encounter, meet, party, association, interview, join', 'TAO(gặp nạn,gặp)', 'Sước Tào(Tào Tháo:曹)là Tao gặp nạn.Gặp Tào tháo đuổi.槽:Thay Mộc là Tào(cái máng)', ARRAY['ソウ'], ARRAY['あ.う','あ.わせる'], 14, 1554, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('霜', 'N1', 'frost', 'SƯƠNG(hạt sương)', 'Vũ Tương là Sương giá.Mưa ướt thủ TƯớng là Sương.', ARRAY['ソウ'], ARRAY['しも'], 17, 2151, (SELECT id FROM radicals WHERE character = '173')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('騒', 'N1', 'boisterous, make noise, clamor, disturb, excite', 'TAO(làm ồn)', 'con ngựa chân vắt chéo ngồi lên người con sâu phát ra tiếng ồn ào.Mã Hựu Trùng là Tao làm ồn.', ARRAY['ソウ'], ARRAY['さわ.ぐ','うれい','さわ.がしい'], 18, 1069, (SELECT id FROM radicals WHERE character = '187')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('像', 'N2', 'statue, picture, image, figure, portrait', 'TƯỢNG(hình tượng,giống)', 'TƯỢNG người voi', ARRAY['ゾウ'], NULL, 14, 856, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('増', 'N3', 'increase, add, augment, gain, promote', 'TĂNG(gia tăng,thêm)', '曽：Tằng(そう、そ、ぞう)層: Tằng ở nhà nhiều tầng憎：Tằng giận tim dựng đứng lên贈：Tằng được tặng bảo bối増：Tằng mua thêm đất', ARRAY['ゾウ'], ARRAY['ま.す','ま.し','ふ.える','ふ.やす'], 14, 231, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('憎', 'N2', 'hate, detest', 'TĂNG(đáng ghét,ái yêu tăng ghét)', 'Tâm tằng là Tăng ghét', ARRAY['ゾウ'], ARRAY['にく.む','にく.い','にく.らしい','にく.しみ'], 14, 1808, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('臓', 'N2', 'entrails, viscera, bowels', 'TẠNG(nội tạng)', 'Nhục Tàng(nhà kho,cất trữ:蔵Thảo Thần Qua)là Tạng nội tạng.', ARRAY['ゾウ'], ARRAY['はらわた'], 19, 991, (SELECT id FROM radicals WHERE character = '130')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('蔵', 'N2', 'storehouse, hide, own, have, possess', 'TÀNG(nhà kho,bảo tàng)', 'Thảo Thần Mậu là Tàng kinh các.Tên gian thần TÀNG trữ giặc dưới mái nhà phủ đầy cỏ.臓:Thêm Nhục là nội Tạng.', ARRAY['ゾウ','ソウ'], ARRAY['くら','おさ.める','かく.れる'], 15, 468, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('贈', 'N2', 'presents, send, give to, award to, confer on, presenting something', 'TẶNG(tặng)', 'Bối Tằng là Tặng,đưa tặng.', ARRAY['ゾウ','ソウ'], ARRAY['おく.る'], 18, 1001, (SELECT id FROM radicals WHERE character = '154')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('造', 'N2', 'create, make, structure, physique', 'TẠO(chế tạo,làm ra)', 'Sước Cáo là Tạo ra.làm raBáo cáo đc chuyển đi để mọi người cùng chế tạo.酷:Thay Dậu là Khốc liệt', ARRAY['ゾウ'], ARRAY['つく.る','つく.り','-づく.り'], 10, 429, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('促', 'N1', 'stimulate, urge, press, demand, incite', 'XÚC(Thúc giục,vội vã, gấp)', 'Chú TÚc:có đủ chân là XÚC tiến(vội vã) thôiNhân túc:xúc', ARRAY['ソク'], ARRAY['うなが.す'], 9, 998, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('側', 'N3', 'side, lean, oppose, regret', 'TRẮC(phía,bên,trắc diện:mặt bên)', 'ng dùng tiền mua đao đi đo TRẮC địa:mặt đấtNhân Tắc Trắc', ARRAY['ソク'], ARRAY['かわ','がわ','そば'], 11, 216, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('則', 'N2', 'rule, law, follow, based on, model after', 'TẮC(phép,bắt chước,qui tắc)', 'qui TẮC dùng Tiền mua ĐaoBối Đao là TắcTrắc(phía:)側Trắc(đo lường:trắc địa):測', ARRAY['ソク'], ARRAY['のっと.る','のり','すなわち'], 9, 753, (SELECT id FROM radicals WHERE character = '18')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('即', 'N1', 'instant, namely, as is, conform, agree, adapt', 'TỨC(ngay là,có nghĩa là,tức thì)', 'TỨC khắc ko lấn Cấn tiểu Tiếtthêm bộ Trúc thành Tiết(tiết kiệm) 節', ARRAY['ソク'], ARRAY['つ.く','つ.ける','すなわ.ち'], 7, 1167, (SELECT id FROM radicals WHERE character = '26')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('息', 'N3', 'breath, respiration, son, interest (on money), rest, coming to an end', 'TỨC(hơi thở)', 'Tự Tâm là Tức(thở).Con TIM mà vẫn TỰ đập đc TỨC là vẫn còn HƠI THỞ憩:Thêm Thiệt là Khế(nghỉ ngơi)', ARRAY['ソク'], ARRAY['いき'], 10, 882, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('捉', 'N1', 'catch, capture', 'TRÓC(nắm bắt,bắt,bắt ép)', 'Thủ Túc là Tróc nã.', ARRAY['ソク','サク'], ARRAY['とら.える'], 10, 1976, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('束', 'N3', 'bundle, sheaf, ream, tie in bundles, govern, manage, control', 'THÚC(bó,gói)', 'Mộc Khẩu Thúc.THÚC đẩy cây lớn nhanh bằng cách BUỘC thân cây lại.速:Thêm Sước là Tốc độ.疎:Thêm Sơ là Sơ lược', ARRAY['ソク'], ARRAY['たば','たば.ねる','つか','つか.ねる'], 7, 918, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('測', 'N2', 'fathom, plan, scheme, measure', 'TRẮC(đo lường,trắc địa,dò)', 'Thủy Tắc(phép,bắt chước) là Trắc đo đạc.側:Thay Nhân là Trắc(phía)', ARRAY['ソク'], ARRAY['はか.る'], 12, 761, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('足', 'N4', 'leg, foot, be sufficient, counter for pairs of footwear', '', '', ARRAY['ソク'], ARRAY['あし','た.りる','た.る','た.す'], 7, 343, (SELECT id FROM radicals WHERE character = '157')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('速', 'N3', 'quick, fast', 'TỐC(nhanh)', 'Sước Thúc là Tốc nhanh chóng.Cứ THÚC vào đít là tăng TỐC ngay.疎:Thay Sơ là Sơ lược.', ARRAY['ソク'], ARRAY['はや.い','はや-','はや.める','すみ.やか'], 10, 576, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
