INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('弾', 'N1', 'bullet, twang, flip, snap', 'ĐẠN,ĐÀN(viên đạn,đánh đàn)', 'CUng ĐƠN(単:Đơn giản) là Đạn,Đàn.đơn giản hơn việc dùng cung chính là dùng đạn', ARRAY['ダン','タン'], ARRAY['ひ.く','-ひ.き','はず.む','たま','はじ.く','はじ.ける','ただ.す','はじ.きゆみ'], 12, 853, (SELECT id FROM radicals WHERE character = '57')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
