INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('暖', 'N1', 'warmth', 'NOÃN(trời ấm áp)', 'Nhật Viên(bèn,bởi vậy,cho nên:爰) là Noãn.緩:Thêm Mịch là Hoãn(trì hoãn).媛:Thay Nữ là Viện(cô gái đẹp,kỹ viện).', ARRAY['ダン','ノン'], ARRAY['あたた.か','あたた.かい','あたた.まる','あたた.める'], 13, 1371, (SELECT id FROM radicals WHERE character = '72')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('檀', 'BEYOND', 'cedar, sandalwood, spindle tree', '', '', ARRAY['ダン','タン'], ARRAY['まゆみ'], 17, 2291, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
