INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('知', 'N4', 'know, wisdom', 'TRI(hay,biết,tri thức)', 'Thỉ Khẩu là Tri biết.33. 愛 ái yêu 34. 憎 tăng ghét35. 識 thức biết 36. 知 tri hay 37. 木 mộc cây 38. 根 căn rễ .', ARRAY['チ'], ARRAY['し.る','し.らせる'], 8, 205, (SELECT id FROM radicals WHERE character = '111')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
