INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('弛', 'BEYOND', 'slacken, relax', '', '', ARRAY['チ','シ'], ARRAY['たる.む','たる.める','たゆ.む','ゆる.む','ゆる.み'], 6, 2497, (SELECT id FROM radicals WHERE character = '57')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('恥', 'N3', 'shame, dishonor', 'SỈ(mắc cỡ,xấu hổ)', 'Nhĩ Tâm Sỉkhi NGHE 耳 những lời SỈ 恥 nhục đó. trong TÂM 心 tôi cảm thấy rất là XẤU HỔ...', ARRAY['チ'], ARRAY['は.じる','はじ','は.じらう','は.ずかしい'], 10, 1575, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
