INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('置', 'N3', 'placement, put, set, deposit, leave behind, keep, employ, pawn', 'TRÍ(đặt,để)', 'Võng Trực là Trí đặt,để.Đặt cái VÕNG vào đấy rồi bố TRÍ người nằm TRỰC.値:Thay Nhân là giá Trị.', ARRAY['チ'], ARRAY['お.く','-お.き'], 13, 277, (SELECT id FROM radicals WHERE character = '122')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('致', 'N1', 'doth, do, send, forward, cause, exert, incur, engage', 'TRÍ(nhất trí,tới cùng)', 'Chí Phộc là Trí nhất trí.dùng mưu Trí đánh vào ý Chí quân địch.緻:Thêm Mịch là Trí(tỉ mỉ).', ARRAY['チ'], ARRAY['いた.す'], 10, 870, (SELECT id FROM radicals WHERE character = '133')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
