INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('貯', 'N2', 'savings, store, lay in, keep, wear mustache', 'TRỮ(tích trữ)', 'Bối Miên Đinh là Trữ tích trữ.', ARRAY['チョ'], ARRAY['た.める','たくわ.える'], 12, 1100, (SELECT id FROM radicals WHERE character = '154')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('丁', 'N1', 'street, ward, town, counter for guns, tools, leaves or cakes of something, even number, 4th calendar sign', 'ĐINH(can thứ 4 trong 10)', 'nhất quyết đóng đinh', ARRAY['チョウ','テイ','チン','トウ','チ'], ARRAY['ひのと'], 2, 1312, (SELECT id FROM radicals WHERE character = '1')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
