INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('寵', 'BEYOND', 'affection, love, patronage', '', '', ARRAY['チョウ'], ARRAY['めぐ.み','めぐ.む'], 19, NULL, (SELECT id FROM radicals WHERE character = '40')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('帖', 'BEYOND', 'quire (of paper), bundle of seaweed, counter for screens, notebook', '', '', ARRAY['チョウ','ジョウ'], ARRAY['かきもの'], 8, 2208, (SELECT id FROM radicals WHERE character = '50')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('帳', 'N1', 'notebook, account book, album, curtain, veil, net, tent', 'TRƯỚNG(sổ sách,căng lên,màn che:gọi là trướng)', '*帳: có 2 nghĩa chính: 1-rèm, màn che (như ở giường trung quốc cổ trang)2- sổ sách: vd: 手帳 sổ tayGóc Nhìn: cái Khăn (巾) Dài (長)==&gt; được dùng để làm rèm (TRƯỚNG 帳)張:Thêm CUng là Trương(kéo dài)', ARRAY['チョウ'], ARRAY['とばり'], 11, 1459, (SELECT id FROM radicals WHERE character = '50')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('庁', 'N2', 'government office', 'SẢNH(công sở)', 'Nghiễm ĐInh là Sảnh,đại sảnh', ARRAY['チョウ','テイ'], ARRAY['やくしょ'], 5, 793, (SELECT id FROM radicals WHERE character = '53')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('弔', 'N1', 'condolences, mourning, funeral', 'ĐIẾU(đi viếng,thương tiếc)', 'Thời xưa nếu có tin buồn thì cờ rủ xuống quấn quanh cột', ARRAY['チョウ'], ARRAY['とむら.う','とぶら.う'], 4, 1840, (SELECT id FROM radicals WHERE character = '57')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('張', 'N1', 'counter for bows & stringed instruments, stretch, spread, put up (tent)', 'TRƯƠNG(căng ra)', 'Cung muốn bắn dài thì phải kéo căng ra.帳:Bỏ Cung thêm Cân là Trướng(căng lên,cái trướng bằng vải).張飛:Trương Phi', ARRAY['チョウ'], ARRAY['は.る','-は.り','-ば.り'], 11, 403, (SELECT id FROM radicals WHERE character = '57')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('彫', 'N1', 'carve, engrave, chisel', 'ĐIÊU(chạm,khắc)', 'Chu(vùng xung quanh,quanh,chu vi) Sam là Điêu khắc.Chu chỉ nhược để tóc đuôi Sam nhìn rất Điêu', ARRAY['チョウ'], ARRAY['ほ.る','-ぼ.り'], 11, 1533, (SELECT id FROM radicals WHERE character = '59')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('徴', 'N1', 'indications, sign, omen, symptom, collect, seek, refer to, question', 'TRƯNG(đặc trưng)', 'XÍch SƠn Vương Phốc là Trưng.Hai Bà Trưng lên vương đánh đuổi quân ĐÔng Hán.懲:Trưng thêm tâm là Trừng(trừng phạt)', ARRAY['チョウ','チ'], ARRAY['しるし'], 14, 850, (SELECT id FROM radicals WHERE character = '60')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('懲', 'N1', 'penal, chastise, punish, discipline', 'TRỪNG(trừng phạt,răn bảo)', '徴 :Trưng(đặc trưng,đánh dấu) Tâm Là Trừng phạt.Đặc TRƯNG của vua là TRỪNG trị kẻ làm điều trái với lương TÂM', ARRAY['チョウ'], ARRAY['こ.りる','こ.らす','こ.らしめる'], 18, 1303, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('挑', 'N1', 'challenge, contend for, make love to', 'THIÊU,KHIÊU(thử thách,thách thức)', 'Thủ Triệu là THiêu,Khiêu khích.眺:Thêm Mục là Thiếu(tầm nhìn)', ARRAY['チョウ'], ARRAY['いど.む'], 9, 989, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('暢', 'BEYOND', 'stretch', '', '', ARRAY['チョウ'], ARRAY['のび.る'], 14, 2144, (SELECT id FROM radicals WHERE character = '72')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('朝', 'N4', 'morning, dynasty, regime, epoch, period, (North) Korea', 'TRIỀU(buổi sáng)', 'Đó là buổi sáng ngày 10 tháng 10.潮:Thêm Thủy là thủy Triều.嘲:Thêm Khẩu là Trào phúng', ARRAY['チョウ'], ARRAY['あさ'], 12, 248, (SELECT id FROM radicals WHERE character = '74')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('潮', 'N1', 'tide, salt water, opportunity', 'TRIỀU(thủy triều)', 'Thủy Triều là Triều dâng.', ARRAY['チョウ'], ARRAY['しお','うしお'], 15, 1231, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('牒', 'BEYOND', 'label, genealogy, circular', '', '', ARRAY['チョウ','ジョウ'], ARRAY['ふだ'], 13, NULL, (SELECT id FROM radicals WHERE character = '91')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('町', 'N4', 'town, village, block, street', 'ĐINH(thị xã)', 'Điền ĐInh là ĐInh xã.', ARRAY['チョウ'], ARRAY['まち'], 7, 292, (SELECT id FROM radicals WHERE character = '102')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('眺', 'N1', 'stare, watch, look at, see, scrutinize', 'THIẾU(nhìn xa)', 'Mục Triệu là THiếu nhìn xa.挑:Thay Thủ là Khiêu chiến.跳:Thay Túc là Khiêu vũ.', ARRAY['チョウ'], ARRAY['なが.める'], 11, 1726, (SELECT id FROM radicals WHERE character = '109')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('聴', 'N1', 'listen, headstrong, naughty, careful inquiry', 'THÍNH(nghe,thính giác)', 'Nhĩ Thập Võng Tâm là Thính giác.Tai muốn nghe thính phải tập trung bằng cả trái tim và 10 con mắ', ARRAY['チョウ','テイ'], ARRAY['き.く','ゆる.す'], 17, 781, (SELECT id FROM radicals WHERE character = '128')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('脹', 'BEYOND', 'dilate, distend, bulge, fill out, swell', '', '', ARRAY['チョウ'], ARRAY['は.れる','ふく.らむ','ふく.れる'], 12, NULL, (SELECT id FROM radicals WHERE character = '130')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('腸', 'N1', 'intestines, guts, bowels, viscera', 'TRƯỜNG(ruột,đoạn trường)', 'Nhục Dương là Trường ruột.Đến tháng dương đau đại tràng', ARRAY['チョウ'], ARRAY['はらわた','わた'], 13, 1807, (SELECT id FROM radicals WHERE character = '130')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('蝶', 'BEYOND', 'butterfly', '', '', ARRAY['チョウ'], NULL, 15, 2011, (SELECT id FROM radicals WHERE character = '142')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('調', 'N3', 'tune, tone, meter, key (music), writing style, prepare, exorcise, investigate, harmonize, mediate', 'ĐIỀU(điều tra,điệu nhạc)', 'Ngôn Chu là Điều tra.Đi vòng quanh(周り) lẩm bẩm (言う) như kiếm tìm gì đó(調べる).彫:Thay Sam là Điêu khắc.週:Thay Sước là Chu(tuần)', ARRAY['チョウ'], ARRAY['しら.べる','しら.べ','ととの.う','ととの.える'], 15, 87, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('超', 'N2', 'transcend, super-, ultra-', 'SIÊU(siêu đẳng)', 'Tẩu Triệu là Siêu siêu đẳng.招:Thay Thủ là Chiêu đãi.昭:Thay Nhật là Chiêu sáng.紹:Thay Mịch là giới Thiệu.', ARRAY['チョウ'], ARRAY['こ.える','こ.す'], 12, 597, (SELECT id FROM radicals WHERE character = '156')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('跳', 'N1', 'hop, leap up, spring, jerk, prance, buck, splash, sputter, snap', 'KHIÊU(nhảy lên)', 'Túc Triệu là Khiêu vũ.挑:Thay Thủ là Khiêu chiến.眺:Thay Mục là Thiếu(tầm nhìn).桃:Thay Mộc là cây Đào.逃:Thay Sước là Đào tẩu.', ARRAY['チョウ'], ARRAY['は.ねる','と.ぶ','-と.び'], 13, 1716, (SELECT id FROM radicals WHERE character = '157')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('長', 'N5', 'long, leader, superior, senior', '', '', ARRAY['チョウ'], ARRAY['なが.い','おさ'], 8, 12, (SELECT id FROM radicals WHERE character = '168')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('頂', 'N3', 'place on the head, receive, top of head, top, summit, peak', 'ĐỈNH(đỉnh cao)', 'Đinh Hiệt là Đỉnh cao.', ARRAY['チョウ'], ARRAY['いただ.く','いただき'], 11, 1350, (SELECT id FROM radicals WHERE character = '181')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
