INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鎮', 'N1', 'tranquilize, ancient peace-preservation centers', 'TRẤN(làm cho êm,trấn áp,bình định)', 'Kim Chân là Trấn.Trấn áp.trấn áp người chân chính bằng tiền.慎:Thay Tâm là Thận trọng.', ARRAY['チン'], ARRAY['しず.める','しず.まる','おさえ'], 18, 1617, (SELECT id FROM radicals WHERE character = '167')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
