INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('停', 'N2', 'halt, stopping', '', '', ARRAY['テイ'], ARRAY['と.める','と.まる'], 11, 733, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('偵', 'N1', 'spy', 'TRINH(trinh thám,rình xét)', 'TRinh thám : Người còn Trinh(trung thành,trong trắng 貞:bói kiếm tiền) đi dò xét,Bốc bỐi là TRinh', ARRAY['テイ'], NULL, 11, 1857, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('貞', 'N1', 'upright, chastity, constancy, righteousness', 'TRINH(trinh tiết,trong trắng)', 'Bốc Bối là Trinh tiết.偵:Thêm Nhân là Trinh thám.', ARRAY['テイ','ジョウ'], ARRAY['ただし.い','さだ'], 9, 1389, (SELECT id FROM radicals WHERE character = '154')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('呈', 'N1', 'display, offer, present, send, exhibit', 'TRÌNH(bảo,tỏ ra,tờ trình,trình bày)', 'dùng miệng TRÌNH tấu với vuaThêm Hòa thành Trình độ 程', ARRAY['テイ'], NULL, 7, 1571, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('堤', 'N1', 'dike, bank, embankment', 'ĐÊ(bờ đê)', 'Đất(土) ở Đê (堤) là đất Thị(是) phi.Thổ nhật Sơ Đê', ARRAY['テイ'], ARRAY['つつみ'], 12, 1658, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('定', 'N3', 'determine, fix, establish, decide', 'ĐỊNH(dự định,quyết định)', 'MIên SƠ là Định', ARRAY['テイ','ジョウ'], ARRAY['さだ.める','さだ.まる','さだ.か'], 8, 48, (SELECT id FROM radicals WHERE character = '40')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('帝', 'N1', 'sovereign, the emperor, god, creator', 'ĐẾ(vua,trời,thượng đế)', 'Lập Cân là Đế締:Thêm Chỉ là Đế(ràng buộc)諦:Thêm Ngôn là Đế(từ bỏ)', ARRAY['テイ'], ARRAY['みかど'], 9, 1276, (SELECT id FROM radicals WHERE character = '50')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('底', 'N2', 'bottom, sole, depth, bottom price, base, kind, sort', 'ĐỂ(đáy,đến,để chỉ:đình chỉ)', 'Nghiễm Đê: là Để:phần thấp nhất Mái nhà là sàn nhà低:Đê(thấp)', ARRAY['テイ'], ARRAY['そこ'], 8, 867, (SELECT id FROM radicals WHERE character = '53')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('庭', 'N3', 'courtyard, garden, yard', 'ĐÌNH(sân,tòa án)', 'Nghiễm ĐÌnh(triều đình廷) là ĐÌnh(sân vườn)Sân đình có mái che nơi vuaa đi lại', ARRAY['テイ'], ARRAY['にわ'], 10, 816, (SELECT id FROM radicals WHERE character = '53')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('廷', 'N1', 'courts, imperial court, government office', 'ĐÌNH(triều đình,pháp đình:tòa án)', 'Dẫn Nhâm(can Nhâm Thìn) là ĐÌnh.庭:Nghiễm Đình là sân vườn.艇:Châu Đình là Đĩnh(thuyền nhỏ)', ARRAY['テイ'], NULL, 7, 1439, (SELECT id FROM radicals WHERE character = '54')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('弟', 'N4', 'younger brother, faithful service to elders', 'ĐỆ(em trai)', 'Thảo Điếu thêm 1 triệt là Đệ.', ARRAY['テイ','ダイ','デ'], ARRAY['おとうと'], 7, 1161, (SELECT id FROM radicals WHERE character = '57')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('悌', 'BEYOND', 'serving our elders', '', '', ARRAY['テイ','ダイ'], NULL, 10, 2474, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('抵', 'N1', 'resist, reach, touch', 'ĐỂ(chống lại,đề kháng)', 'Thủ Đê là Để,Đề.hạ THẤP TAY ĐỂ chống cự bọn dê xồm.低:Thêm nhân là Đê hèn,cúi thấp', ARRAY['テイ'], NULL, 8, 1182, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('挺', 'BEYOND', 'bravely volunteer, counter for guns, inksticks, palanquins, rickshaws', '', '', ARRAY['チョウ','テイ'], ARRAY['ぬ.く'], 10, 2189, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('提', 'N1', 'propose, take along, carry in hand', 'ĐỀ(trình lên,đề đạt,nâng đỡ,đề nghị)', 'Thủ THị(phải: 是)Nhật Sơ là Đề nghị.', ARRAY['テイ','チョウ','ダイ'], ARRAY['さ.げる'], 12, 254, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('梯', 'BEYOND', 'ladder, stairs, insatiable drinking', '', '', ARRAY['テイ','タイ'], ARRAY['はしご'], 11, 2218, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('汀', 'BEYOND', 'water''s edge, shore, bank', '', '', ARRAY['テイ'], ARRAY['みぎわ','なぎさ'], 5, NULL, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('禎', 'BEYOND', 'happiness, blessed, good fortune, auspicious', '', '', ARRAY['テイ'], ARRAY['さいわ.い'], 13, 2083, (SELECT id FROM radicals WHERE character = '113')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('程', 'N3', 'extent, degree, law, formula, distance, limits, amount', 'TRÌNH(trình độ)', 'Hòa Trình(bảo,bẩm tấu:呈)là Trình độ.TRÌNH độ nịnh VUA bằng MIỆNG của HÒA thân thì không ai sánh được', ARRAY['テイ'], ARRAY['ほど','-ほど'], 12, 514, (SELECT id FROM radicals WHERE character = '115')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('締', 'N1', 'tighten, tie, shut, lock, fasten', 'ĐẾ(siết chặt,thắt)', 'Mịch Đế là Đế buộc chặt.Lấy sợi DÂY BUỘC tên hoàng ĐẾ lại.諦:Thay Ngôn là Đế(từ bỏ)', ARRAY['テイ'], ARRAY['し.まる','し.まり','し.める','-し.め','-じ.め'], 15, 797, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('艇', 'N1', 'rowboat, small boat', 'ĐĨNH(thuyền nhỏ)', 'Chu ĐÌnh(tòa án,triều đình:廷Dẫn Nhâm)là Đĩnh thuyền nhỏ.', ARRAY['テイ'], NULL, 13, 1433, (SELECT id FROM radicals WHERE character = '137')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('訂', 'N1', 'revise, correct, decide', 'ĐÍNH(sửa cho đúng,đính chính)', 'Ngôn ĐInh là ĐÍnh chính.tôi ĐÍNH chính lại những lời tôi vừa phát NGÔN chắc như ĐINH đóng cột...', ARRAY['テイ'], ARRAY['ただ.す'], 9, 1690, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('諦', 'N1', 'truth, clarity, abandon, give up', 'ĐẾ(từ bỏ)', 'Ngôn Đế là Đế từ bỏ.ông vua nói rằng sẽ từ bỏ chức vua.締:Thay Mịch là Đế(ràng buộc).', ARRAY['テイ','タイ'], ARRAY['あきら.める','つまびらか','まこと'], 16, 2457, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('蹄', 'BEYOND', 'hoof', '', '', ARRAY['テイ'], ARRAY['ひづめ'], 16, 2469, (SELECT id FROM radicals WHERE character = '157')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('逓', 'N1', 'relay, in turn, sending', 'ĐỆ(đổi phiên,tuần tự)', 'cầm 2 cái khăn và búa đi đệ trình trên con đường này', ARRAY['テイ'], ARRAY['かわ.る','たがいに'], 10, 1957, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('邸', 'N1', 'residence, mansion', 'ĐỂ(dinh thự)', 'Để,Đê(nền,gốc:氐) Ấp là Để dinh thự(Cái nhà cho các nước chư hầu đến chầu ở)', ARRAY['テイ'], ARRAY['やしき'], 8, 905, (SELECT id FROM radicals WHERE character = '163')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鄭', 'BEYOND', 'an ancient Chinese province', '', '', ARRAY['テイ','ジョウ'], NULL, 15, 1732, (SELECT id FROM radicals WHERE character = '163')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('釘', 'BEYOND', 'nail, tack, peg', '', '', ARRAY['テイ','チョウ'], ARRAY['くぎ'], 10, 2496, (SELECT id FROM radicals WHERE character = '167')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鼎', 'BEYOND', 'three legged kettle', '', '', ARRAY['テイ'], ARRAY['かなえ'], 13, NULL, (SELECT id FROM radicals WHERE character = '206')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('泥', 'N2', 'mud, mire, adhere to, be attached to', 'NÊ(bùn)', 'Thủy Ni(ni cô,bà xơ :尼) là Nê bùn.', ARRAY['デイ','ナイ','デ','ニ'], ARRAY['どろ','なず.む'], 8, 1589, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('摘', 'N1', 'pinch, pick, pluck, trim, clip, summarize', 'TRÍCH(ngắt,hái,chọn lấy)', 'Thủ ĐÍch(cái gốc:啇.Lập Quynh Cổ) là TRÍCH đoạn.嫡:Thêm Nữ là ĐÍch tôn敵:Thêm Phốc là kẻ ĐỊch...適:Thêm Sước là Thích hợp.滴:Thêm Thủy là Trích(nhỏ giọt)', ARRAY['テキ'], ARRAY['つ.む'], 14, 564, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('擢', 'BEYOND', 'excel in, surpass, pull out, select', '', '', ARRAY['テキ','タク'], ARRAY['ぬ.く','ぬき.んでる'], 17, NULL, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('敵', 'N1', 'enemy, foe, opponent', 'ĐỊCH(kẻ thù)', 'Đích(cái gốc:啇) Phộc là Địch thủ', ARRAY['テキ'], ARRAY['かたき','あだ','かな.う'], 15, 1205, (SELECT id FROM radicals WHERE character = '66')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('滴', 'N2', 'drip, drop', 'TRÍCH(giọt nước)', 'Thủy ĐÍch(gốc,cội:啇) là Trích giọt nước.嫡:Thay Nữ là ĐÍch tôn摘:Thay Thủ là Trích(hái,tỉa).敵:Thay Phốc là kẻ Địch.適:Thay Sước là Thích hợp.', ARRAY['テキ'], ARRAY['しずく','したた.る'], 14, 2019, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('的', 'N4', 'bull''s eye, mark, target, object, adjective ending', 'ĐÍCH(mục đích)', 'Bạch Chước(cái muôi: 勺) là ĐÍch.', ARRAY['テキ'], ARRAY['まと'], 8, 105, (SELECT id FROM radicals WHERE character = '106')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('笛', 'N1', 'flute, clarinet, pipe, whistle, bagpipe, piccolo', 'ĐỊCH(ống sáo)', 'Trúc Do là Địch ống sáo.cây tre đc thổi tự do gọi là sáo', ARRAY['テキ'], ARRAY['ふえ'], 11, 1928, (SELECT id FROM radicals WHERE character = '118')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('適', 'N3', 'suitable, occasional, rare, qualified, capable', 'THÍCH(thích hợp)', 'Sước Lập Quynh Cổ là Thích hợp.敵:Thay Phốc là kẻ Địch.摘:Thay Thủ là Trích(hái,tỉa).滴:Thay Thủy là Trích(nhỏ giọt).嫡:Thay Nữ là ĐÍch tôn.', ARRAY['テキ'], ARRAY['かな.う'], 14, 670, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('溺', 'N1', 'drown, indulge', 'NỊCH(đuối nước)', 'Thủy Nhược là Nịch.chết đuốiYẾU mà còn xuống NƯỚC thì chết đuối là chắc', ARRAY['デキ','ジョウ','ニョウ'], ARRAY['いばり','おぼ.れる'], 13, NULL, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('哲', 'N1', 'philosophy, clear', 'TRIẾT(khôn,hiền triết,triết học,triết lý)', 'Khẩu chiết(bẻ gãy) trong TRiết học: dùng lời nói bẻ cong sự thậtChiết(bẻ gãy)折 thêm Khẩu là Triết học', ARRAY['テツ'], ARRAY['さとい','あきらか'], 10, 1093, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('徹', 'N1', 'penetrate, clear, pierce, strike home, sit up (all night)', 'TRIỆT(triệt để,suốt,thấu,đến tận cùng)', 'Xích Dục Phốc là TRiệt.Người xưa quán TRIỆT (徹) cách dạy con: luôn ĐI (彳) bên cạnh để giáo DỤC (育) và phải ĐÁNH (攵) nó lúc cần thiết.撤:Bỏ XÍch thêm THủ là Triệt(Bỏ,từ đi)', ARRAY['テツ'], NULL, 15, 968, (SELECT id FROM radicals WHERE character = '60')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('撤', 'N1', 'remove, withdraw, disarm, dismantle, reject, exclude', 'TRIỆT(triệt bỏ,bỏ đi,trừ đi)', 'Thủ Dục Phốc là Triệt để.Làm giáo Dục là phải TRIỆT thẳng Tay XOÁ BỎ mù chữ徹:Thêm Xích là Triệt để', ARRAY['テツ'], NULL, 15, 811, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('迭', 'N1', 'transfer, alternation', 'ĐIỆT(lần lượt đổi)', 'Sước Thất là Điệt lần lượt đổi.ĐIỆT, lại thất bại, thôi đi cho thằng khác đến thay phiên', ARRAY['テツ'], NULL, 8, 1907, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鉄', 'N2', 'iron', 'THIẾT(chất sắt)', 'Kim Thất là Thiết là sắt.', ARRAY['テツ'], ARRAY['くろがね'], 13, 672, (SELECT id FROM radicals WHERE character = '167')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('典', 'N1', 'code, ceremony, law, rule', 'ĐIỂN(giữ,kinh điển,từ điển,cổ điển:sự cũ)', 'nhạc cổ ĐIỂN:Khúc nhạc quãng 8 8 KHÚC', ARRAY['テン','デン'], ARRAY['ふみ','のり'], 8, 1055, (SELECT id FROM radicals WHERE character = '12')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('填', 'BEYOND', 'fill in', 'ĐIỀN(lấp kín)', 'dùng đúng 10 cái dụng cụ để lấp vào chỗ trống trên đấtThổ Chân là ĐIỀN(lấp kín)慎: Thay Tâm là cẩn Thận.', ARRAY['テン','チン'], ARRAY['は.まる','は.める','うず.める','しず.める','ふさ.ぐ'], 13, NULL, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('天', 'N5', 'heavens, sky, imperial', '', '', ARRAY['テン'], ARRAY['あまつ','あめ','あま-'], 4, 512, (SELECT id FROM radicals WHERE character = '37')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('展', 'N1', 'unfold, expand', 'TRIỂN(giải,mở,thăm,xem xét,phát triển)', 'Chắp tay cúng xác chết để xin được phát triểnThi Củng Triển.殿: Điện cung điện.gần giống nhau', ARRAY['テン'], NULL, 10, 352, (SELECT id FROM radicals WHERE character = '44')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('店', 'N4', 'store, shop', 'ĐIẾM(cửa hàng,tiệm)', 'Nghiễm CHiếm,Chiêm là ĐIếm(tiệm)', ARRAY['テン'], ARRAY['みせ','たな'], 8, 378, (SELECT id FROM radicals WHERE character = '53')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('添', 'N1', 'annexed, accompany, marry, suit, meet, satisfy, attach, append, garnish, imitate', 'THIÊM(thêm vào)', 'Thủy Thiểm(nhục:忝) là THiêm vào.', ARRAY['テン'], ARRAY['そ.える','そ.う'], 11, 1501, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('纏', 'BEYOND', 'wear, wrap, tie, follow around, collect', '', '', ARRAY['テン','デン'], ARRAY['まつ.わる','まと.う','まと.める','まと.まる','まと.い'], 21, NULL, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('貼', 'N1', 'stick, paste, apply', 'THIẾP(dán)', 'Bối Chiêm là Thiếp dán.có Tiền DÁN khắp nhà mới Chiếm được nhiều Thê THIẾP', ARRAY['テン','チョウ'], ARRAY['は.る','つ.く'], 12, 2444, (SELECT id FROM radicals WHERE character = '154')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('転', 'N4', 'revolve, turn around, change', 'CHUYỂN(di chuyển,chuyển động)', 'Xa Vân là Chuyển động.Vân di CHUYỂN bằng Xe máy', ARRAY['テン'], ARRAY['ころ.がる','ころ.げる','ころ.がす','ころ.ぶ','まろ.ぶ','うたた','うつ.る','くる.めく'], 11, 327, (SELECT id FROM radicals WHERE character = '159')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('点', 'N3', 'spot, point, mark, speck, decimal point', 'ĐIỂM(điểm số,dấu chấm)', 'Chiêm Hỏa là ĐIểm số.', ARRAY['テン'], ARRAY['つ.ける','つ.く','た.てる','さ.す','とぼ.す','とも.す','ぼち'], 9, 165, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('伝', 'N3', 'transmit, go along, walk along, follow, report, communicate, legend, tradition', 'TRUYỀN(Truyền đạt, truyền động)', 'Người đứng Truyền lời theo mây gió(Vân)', ARRAY['デン','テン'], ARRAY['つた.わる','つた.える','つた.う','つだ.う','-づた.い','つて'], 6, 416, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('殿', 'N2', 'Mr., hall, mansion, palace, temple, lord', 'ĐIỆN(cung điện)', 'Thi Cộng Thù là ĐIện hạ.Cùng nhau cầm vũ khí tấn công vào cung điện cướp xác ướp.塀: Thay Thổ là Biên tường rào.', ARRAY['デン','テン'], ARRAY['との','-どの'], 13, 1199, (SELECT id FROM radicals WHERE character = '79')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('田', 'N4', 'rice field, rice paddy', '', '', ARRAY['デン'], ARRAY['た'], 5, 90, (SELECT id FROM radicals WHERE character = '102')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('電', 'N5', 'electricity', 'ĐIỆN(điện)', 'Mưa (雨) trên Đồng (田) tạo ra Dòng (乚) ĐIỆN (電).', ARRAY['デン'], NULL, 13, 268, (SELECT id FROM radicals WHERE character = '173')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('兎', 'BEYOND', 'rabbit, hare', '', '', ARRAY['ト','ツ'], ARRAY['うさぎ'], 8, NULL, (SELECT id FROM radicals WHERE character = '10')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('吐', 'N1', 'spit, vomit, belch, confess, tell (lies)', 'THỔ(nhả ra,vứt bỏ,nôn mửa,thổ huyết,hộc)', 'Thổ nôn ra từ miệng xuống đất', ARRAY['ト'], ARRAY['は.く','つ.く'], 6, 1674, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('堵', 'BEYOND', 'fence, railing, enclosure', '', '', ARRAY['ト'], ARRAY['かき'], 11, NULL, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('塗', 'N2', 'paint, plaster, daub, smear, coating', 'ĐỒ(sơn phết,)', 'Thuỷ Dư thổ Đồ sơnNgày xưa người ta thường đổ DƯ một chút NƯỚC vào ĐẤT cho nhão ra rồi đem chát, bôi vào đồ sứ để tạo mầu', ARRAY['ト'], ARRAY['ぬ.る','ぬ.り','まみ.れる'], 13, 1414, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('妬', 'N1', 'jealous, envy', 'ĐỐ(đố kỵ,ấm ức)', 'Phụ nữ đố kị thường ném đá nhau', ARRAY['ト','ツ'], ARRAY['ねた.む','そね.む','つも.る','ふさ.ぐ'], 8, NULL, (SELECT id FROM radicals WHERE character = '38')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('徒', 'N3', 'on foot, junior, emptiness, vanity, futility, uselessness, ephemeral thing, gang, set, party, people', 'ĐỒ(học trò,sinh đồ)', 'Xích Tẩu là ĐỒ(học trò).Khi ta đi 走 đến nơi nào, cũng có kẻ 彳bước chân đi lẽo đẽo bên cạnh ta. Ấy chính là đồ đệ.', ARRAY['ト'], ARRAY['いたずら','あだ'], 10, 817, (SELECT id FROM radicals WHERE character = '60')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('斗', 'N1', 'Big Dipper, ten sho (vol), sake dipper, dots and cross radical (no. 68)', '', '', ARRAY['ト','トウ'], NULL, 4, 1885, (SELECT id FROM radicals WHERE character = '68')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
