INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('登', 'N3', 'ascend, climb up', 'ĐĂNG(leo lên,đăng ký)', 'Bát Đậu là Đăng lên.澄:Thêm Thủy là Trừng phạt.', ARRAY['トウ','ト','ドウ','ショウ','チョウ'], ARRAY['のぼ.る','あ.がる'], 12, 566, (SELECT id FROM radicals WHERE character = '105')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
