INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('途', 'N3', 'route, way, road', 'ĐỒ(đường,lối,tiền đồ)', 'Sước Dư là ĐỒ đường lối,tiền đồ.塗:Thay THủy THổ là ĐỒ(sơn phết)', ARRAY['ト'], ARRAY['みち'], 10, 717, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
