INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('唐', 'N1', 'T''ang, China, foreign', 'ĐƯỜNG(nói khoác,nhà Đường)', 'cái mồm như cái mõm heo ngồi trong hiên nhà nói khoác,nói chuyện hoang ĐƯờngĐường thêm Mễ là Đường(chất đường) 糖.Nghiễm Quân Đường nói khoác', ARRAY['トウ'], ARRAY['から'], 10, 1727, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
