INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('搭', 'N1', 'board, load (a vehicle), ride', 'ĐÁP(cưỡi,đi xe,đáp tái:trang bị)', 'Thủ Đáp(荅)Thảo Hợp là Đáp máy bay.塔:Thêm Thổ là Tháp(cái tháp)', ARRAY['トウ'], NULL, 12, 1472, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
