INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('湯', 'N2', 'hot water, bath, hot spring', 'THANG(nước nóng,vua Thang)', 'Thủy DƯơng là Thang.Nước để dưới mặt trời (陽) thì nóng là điều tất nhiên', ARRAY['トウ'], ARRAY['ゆ'], 12, 1356, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('灯', 'N2', 'lamp, a light, light, counter for lights', 'ĐĂNG(cái đèn,hoa đăng)', 'Hỏa ĐInh là Đăng,hoa đăng', ARRAY['トウ'], ARRAY['ひ','ほ-','ともしび','とも.す','あかり'], 6, 1605, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('燈', 'BEYOND', 'lamp, light, counter for lights', '', '', ARRAY['トウ'], ARRAY['ひ','ほ-','ともしび','とも.す','あかり'], 16, 2456, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('当', 'N3', 'hit, right, appropriate, himself', '', '', ARRAY['トウ'], ARRAY['あ.たる','あ.たり','あ.てる','あ.て','まさ.に','まさ.にべし'], 6, 91, (SELECT id FROM radicals WHERE character = '58')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('痘', 'N1', 'pox, smallpox', 'ĐẬU(đậu mùa)', 'Nạch Đậu là Đậu mùa', ARRAY['トウ'], NULL, 12, NULL, (SELECT id FROM radicals WHERE character = '104')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('祷', 'BEYOND', 'pray', '', '', ARRAY['トウ'], ARRAY['いの.る','いの.り','まつ.る'], 11, NULL, (SELECT id FROM radicals WHERE character = '113')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('等', 'N3', 'etc., and so forth, class (first), quality, equal, similar', 'ĐẲNG(bình đẳng,bực,cùng,đều,ngang)', 'Trúc Tự là Đẳng bình đẳng.Ở Trúc lâm Tự mọi người đều bình Đẳng', ARRAY['トウ'], ARRAY['ひと.しい','など','-ら'], 12, 798, (SELECT id FROM radicals WHERE character = '118')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('答', 'N4', 'solution, answer', 'ĐÁP(trả lời)', 'Trúc Hợp là Đáp trả.Thấy hợp lý thì trả lời bằng cách ghi lên đốt tre', ARRAY['トウ'], ARRAY['こた.える','こた.え'], 12, 486, (SELECT id FROM radicals WHERE character = '118')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('筒', 'N2', 'cylinder, pipe, tube, gun barrel, sleeve', 'ĐỒNG(ống tròn)', 'Trúc Đồng là ĐỒng ống tre.洞:Thay Thủy là hang Động.胴:Thay Nhục là Đỗng(cơ thể).銅:Thay KIm là Đồng Cu64.', ARRAY['トウ'], ARRAY['つつ'], 12, 1631, (SELECT id FROM radicals WHERE character = '118')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('糖', 'N1', 'sugar', 'ĐƯỜNG(sugar)', 'Mễ Đường(nhà Đường:唐)là Sugar.', ARRAY['トウ'], NULL, 16, 1471, (SELECT id FROM radicals WHERE character = '119')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('統', 'N1', 'overall, relationship, ruling, governing', 'THỐNG(truyền thống)', 'Minh Sung là Thống truyền thống.', ARRAY['トウ'], ARRAY['す.べる'], 12, 125, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('到', 'N3', 'arrival, proceed, reach, attain, result in', 'ĐÁO(đến nơi,khắp đủ,mã đáo thành công)', 'Muốn đến đích ý CHÍ phải sắc như dao,nhân đáo là đảo chính', ARRAY['トウ'], ARRAY['いた.る'], 8, 1032, (SELECT id FROM radicals WHERE character = '18')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('董', 'BEYOND', 'correct', '', '', ARRAY['トウ'], ARRAY['ただ.す'], 12, NULL, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('藤', 'N1', 'wisteria', 'ĐẰNG(dây leo,hoa tử đằng)', 'hai người ngồi dưới ánh trắng và ngắm hoa tử đằng qua mặt nuớc騰:Thay Mã là Đằng(tiến lên).謄:Thay Ngôn là Đằng(sao chép)', ARRAY['トウ','ドウ'], ARRAY['ふじ'], 18, 291, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('討', 'N1', 'chastise, attack, defeat, destroy, conquer', 'THẢO(thảo luận)', 'Ngôn Thốn là Thảo luận.Lời nói thảo luận gì mà nghe rất thốn', ARRAY['トウ'], ARRAY['う.つ'], 10, 528, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('謄', 'N1', 'mimeograph, copy', 'ĐẰNG(sao chép)', 'nguyệt 月 nói 言 1 đằng chồng 夫 sao chép 1 kiểu騰:Thay Mã là Đằng(tiến lên).勝:Thay Lực là Thắng lợi.藤Thay Thảo Thủy là hoa tử Đằng.', ARRAY['トウ'], NULL, 17, 2295, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('豆', 'N1', 'beans, pea, midget', '', '', ARRAY['トウ','ズ'], ARRAY['まめ','まめ-'], 7, 1422, (SELECT id FROM radicals WHERE character = '151')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('踏', 'N1', 'step, trample, carry through, appraise, evade payment', 'ĐẠP(dẫm đạp)', 'Túc Đạp(chồng chất:沓Thủy Nhật)là Đạp nước cả ngày.', ARRAY['トウ'], ARRAY['ふ.む','ふ.まえる'], 15, 723, (SELECT id FROM radicals WHERE character = '157')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('逃', 'N3', 'escape, flee, shirk, evade, set free', 'ĐÀO(chạy trốn,đào tẩu)', 'Sước Triệu là Đào tẩu.桃:Thay Mộc là cây Đào.', ARRAY['トウ'], ARRAY['に.げる','に.がす','のが.す','のが.れる'], 9, 931, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('透', 'N1', 'transparent, permeate, filter, penetrate', 'THẤU(trong suốt)', 'Sước TÚ(tú tài,ưu việt,siêu:秀)là Thấu trong suốt.người ưu Tú là có thể nhìn Thấu được con đường mình đi.誘:Thay Ngôn là DỤ(mời,dụ khị)', ARRAY['トウ'], ARRAY['す.く','す.かす','す.ける','とう.る','とう.す'], 10, 1035, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('陶', 'N1', 'pottery, porcelain', 'ĐÀO(đồ sành sứ)', 'Phụ Bao Phẫu là Đào đồ sành sứ.Họ Đào.Sau bờ bao can làm gốm', ARRAY['トウ'], ARRAY['すえ'], 11, 1680, (SELECT id FROM radicals WHERE character = '170')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('頭', 'N3', 'head, counter for large animals', 'ĐẦU(cái đầu)', 'Đậu Hiệt là Đầu lâu.ĐẦU óc HIỆT như bã ĐẬU.', ARRAY['トウ','ズ','ト'], ARRAY['あたま','かしら','-がしら','かぶり'], 16, 433, (SELECT id FROM radicals WHERE character = '181')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('騰', 'N1', 'leaping up, jumping up, rising, advancing, going', 'ĐẰNG(tăng giá,tiến lên)', 'Nhục Đại Mã là Đằng:tiến lên,tăng giá.', ARRAY['トウ'], ARRAY['あが.る','のぼ.る'], 20, 1420, (SELECT id FROM radicals WHERE character = '187')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('闘', 'N1', 'fight, war', 'ĐẤU(chiến đấu)', 'Môn Đậu Thốn là Đấu.Chiến đấu để được ăn món đậu thật thốn.', ARRAY['トウ'], ARRAY['たたか.う','あらそ.う'], 18, 751, (SELECT id FROM radicals WHERE character = '169')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('働', 'N3', 'work, (kokuji)', '&nbsp;ĐỘNG(làm việc,lao động)', 'người dùng sức lực kéo vật nặng', ARRAY['ドウ'], ARRAY['はたら.く'], 13, 417, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('動', 'N4', 'move, motion, change, confusion, shift, shake', 'ĐỘNG(di chuyển,làm,cảm động)', 'trọng lực làm trái đất chuyển Động quanh mặt trời', ARRAY['ドウ'], ARRAY['うご.く','うご.かす'], 11, 73, (SELECT id FROM radicals WHERE character = '19')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('同', 'N4', 'same, agree, equal', 'ĐỒNG(cùng như một,hòa,hợp lại,giống nhau)', 'Nhất khẩu ĐỒNG quynh', ARRAY['ドウ'], ARRAY['おな.じ'], 6, 15, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('堂', 'N4', 'public chamber, hall', 'ĐƯỜNG(nhà lớn,)', 'Hoà THƯỢNG từ đông THỔ là ĐƯỜNG tăngSảnh đường', ARRAY['ドウ'], NULL, 11, 1010, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('導', 'N2', 'guidance, leading, conduct, usher', 'ĐẠO(chỉ đạo,dẫn đưa)', 'chỉ đường đắc ĐẠO thật là thốn', ARRAY['ドウ'], ARRAY['みちび.く'], 15, 354, (SELECT id FROM radicals WHERE character = '41')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('憧', 'N1', 'yearn after, long for, aspire to, admire, adore', 'SUNG(ngưỡng mộ,mong ước)', 'Tâm Đồng(nhi ĐỒng:童) lập lý là Sung(ngưỡng mộ).鐘:Thêm Kim là Chung(chuông).瞳:Thêm Mục là ĐỒng tử.', ARRAY['ショウ','トウ','ドウ'], ARRAY['あこが.れる'], 15, 2259, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('撞', 'BEYOND', 'thrust, pierce, stab, prick', '', '', ARRAY['ドウ','トウ','シュ'], ARRAY['つ.く'], 15, NULL, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('洞', 'N1', 'den, cave, excavation', 'ĐỘNG(hang động)', 'Thủy ĐỒng là ĐỘng phong nha', ARRAY['ドウ'], ARRAY['ほら'], 9, 1618, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('瞳', 'N1', 'pupil (of eye)', 'ĐỒNG(con ngươi,đồng tử)', 'Mục Đồng(trẻ thơ:童Lập lý) là Đồng tử.', ARRAY['ドウ','トウ'], ARRAY['ひとみ'], 17, 2069, (SELECT id FROM radicals WHERE character = '109')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('童', 'N2', 'juvenile, child', 'ĐỒNG(nhi đồng,trẻ thơ)', 'Lập Lí là Đồng trẻ con.Lập立nghiệp trên quê hương 里 từ lúc là nhi Đồng.瞳:Thêm Mục là ĐỒng tử.鐘:Thêm Kim là Chung(chuông).憧:Thêm Tâm là Sung(mong ước)', ARRAY['ドウ'], ARRAY['わらべ'], 12, 1138, (SELECT id FROM radicals WHERE character = '117')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('胴', 'N1', 'trunk, torso, hull (ship), hub of wheel', 'ĐỖNG(thân mình)', 'Nhục ĐỒng là ĐỖng thân người.', ARRAY['ドウ'], NULL, 10, 1904, (SELECT id FROM radicals WHERE character = '130')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
