INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('篤', 'N1', 'fervent, kind, cordial, serious, deliberate', 'ĐỐC(trầm trọng,dày)', 'Trúc Mã là ĐỐC thúc.thanh mai Trúc Mã ĐỐc thúc cưới sớm.', ARRAY['トク'], ARRAY['あつ.い'], 16, 1942, (SELECT id FROM radicals WHERE character = '118')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('毒', 'N2', 'poison, virus, venom, germ, harm, injury, spite', 'ĐỘC(chất độc,ác,làm hại)', 'Thổ Vô là ĐỘC tố.Đất không thể trồng được là Độc tố.', ARRAY['ドク'], NULL, 8, 1419, (SELECT id FROM radicals WHERE character = '80')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
