INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('読', 'N5', 'read', 'ĐỘC(đọc)', 'Ngôn Mại là ĐỘC đọc giả.Người Độc giả là người dám Bán đi tiếng nói của mình.続:Thay Mịch là Tục(liên tục).', ARRAY['ドク','トク','トウ'], ARRAY['よ.む','-よ.み'], 14, 618, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
