INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('頓', 'N1', 'suddenly, immediately, in a hurry, arrange, stay in place, bow, kowtow', 'ĐỐN(chỉnh đốn,Cúi xuống sát đất)', 'Đồn Hiệt là Đốn(chỉnh đốn).cho vào Đồn để chỉnh ĐỐN lại cái đầu ngang ngược.鈍:Thay Kim là Độn(cùn).純:Thay Mịch là đơn Thuần.', ARRAY['トン','トツ'], ARRAY['にわか.に','とん.と','つまず.く','とみ.に','ぬかずく'], 13, NULL, (SELECT id FROM radicals WHERE character = '181')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('曇', 'N2', 'cloudy weather, cloud up', 'ĐÀM(trời âm u,có mây)', 'Nhật Vân(mây:雲:Vũ vân) là Đàm', ARRAY['ドン'], ARRAY['くも.る'], 16, 1899, (SELECT id FROM radicals WHERE character = '72')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
