INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('燃', 'N2', 'burn, blaze, glow', 'NHIÊN(nhiên liệu,đốt)', 'Hỏa Nhiên(tự nhiên:然:khuyển hỏa) là Nhiên liệu.Thịt chó muốn ngon tự NHIÊN phải thui 2 lần lửa', ARRAY['ネン'], ARRAY['も.える','も.やす','も.す'], 16, 948, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
