INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('伐', 'N1', 'fell, strike, attack, punish', 'PHẠT(Đánh, đem binh đi đánh nước người gọi là phạt. Nện. Chặt. Khoe công. Đâm chém đánh giết cũng gọi là phạt.Chinh phạt)', 'Người cầm vũ khí(QUA) đi chinh phạt nước khác', ARRAY['バツ','ハツ','カ','ボチ'], ARRAY['き.る','そむ.く','う.つ'], 6, 1816, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
