INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('抜', 'N3', 'slip out, extract, pull out, pilfer, quote, remove, omit', 'BẠT(nhổ đi,rút ra,loại bỏ)', 'Thủ Hữu là Bạt.Lấy TAY đẩy bạn HỮU BẠT ra xa', ARRAY['バツ','ハツ','ハイ'], ARRAY['ぬ.く','-ぬ.く','ぬ.き','ぬ.ける','ぬ.かす','ぬ.かる'], 7, 726, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
