INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('氾', 'N1', 'spread out, wide', 'PHIẾM(tràn lan)', 'Thủy Tiết Phiếm.Thuỷ tiết ra nước một cách tràn lan.', ARRAY['ハン'], ARRAY['ひろ.がる'], 5, NULL, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('汎', 'N1', 'pan-', 'PHIẾM(mênh mông,phù phiếm,rộng)', 'Thủy Phàm là Phiếm.thủy nói chuyện phàm phiếm帆:Thêm Cân là Phàm(thuyền buồm)', ARRAY['ハン','ブ','フウ','ホウ','ホン'], ARRAY['ただよ.う','ひろ.い'], 6, 2014, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('版', 'N2', 'printing block, printing plate, edition, impression, label', 'BẢN(xuất bản)', 'Phiến Phản là bản.xuất BẢN cuốn sách về bọn Phiến quân Phảnđộng板:Thay Mộc là Bản tấm ván.阪:Thay Phụ là Phản(tên phủ Osaka)', ARRAY['ハン'], NULL, 8, 802, (SELECT id FROM radicals WHERE character = '91')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('犯', 'N3', 'crime, sin, offense', 'PHẠM(phạm tội,xâm phạm)', 'Khuyển Tiết là Phạm tội.', ARRAY['ハン','ボン'], ARRAY['おか.す'], 5, 874, (SELECT id FROM radicals WHERE character = '94')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('班', 'N1', 'squad, corps, unit, group', 'BAN(nhóm,ban phát)', 'Nước hai vua phải chia ra ban cầm đao hoà giải ở giữa.斑:Thay giữa là Văn là Ban(lốm đốm,phát ban)', ARRAY['ハン'], NULL, 10, 1592, (SELECT id FROM radicals WHERE character = '96')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('畔', 'N1', 'paddy ridge, levee', 'BẠN(bờ ruộng)', 'Điền Bán là Bạn(bờ ruộng).Bán 1 Nửa BỜ Ruộng cho BẠN.伴:Thay Nhân là Bạn bè.', ARRAY['ハン'], ARRAY['あぜ','くろ','ほとり'], 10, 2049, (SELECT id FROM radicals WHERE character = '102')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('繁', 'N1', 'luxuriant, thick, overgrown, frequency, complexity, trouble', 'PHỒN(phồn thịnh,nhiều)', 'Mẫn(minh mẫn:敏:Mỗi Phốc)Mịch là Phồn thịnh.', ARRAY['ハン'], ARRAY['しげ.る','しげ.く'], 16, 1198, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('般', 'N2', 'carrier, carry, all, general, sort, kind', 'BAN,BÁT(tổng quát,chung,bát thúng:chèo thúng)', 'Chu THù là Ban quanh co.', ARRAY['ハン'], NULL, 10, 649, (SELECT id FROM radicals WHERE character = '137')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('藩', 'N1', 'clan, enclosure', 'PHIÊN(bộ lạc)', 'Thảo Phan(họ Phan,nước vo gạo:潘Thủy Phiên)là Phiên bộ lạc.đến Phiên lãnh chúa tưới Nước cho Cỏ rồi', ARRAY['ハン'], NULL, 18, 1896, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('販', 'N2', 'marketing, sell, trade', 'PHIẾN(buôn bán)', 'Bối Phản là Phiến mua bán.', ARRAY['ハン'], NULL, 11, 627, (SELECT id FROM radicals WHERE character = '154')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('範', 'N1', 'pattern, example, model', 'PHẠM(phạm vi,phép,giới hạn của sự vật)', 'Trúc Xa Tiết là Phạm vi.Ở rừng TRÚC Xe chỉ được chạy trong PHẠM VI cho phép', ARRAY['ハン'], NULL, 15, 1088, (SELECT id FROM radicals WHERE character = '118')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('煩', 'N1', 'anxiety, trouble, worry, pain, ill, annoy, nuisance, irksome', 'PHIỀN(lo âu)', 'Hỏa Hiệt là Phiền, nhọc.Đầu buồn phiền như đang rực lửa', ARRAY['ハン','ボン'], ARRAY['わずら.う','わずら.わす','うるさ.がる','うるさ.い'], 13, 2081, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('頒', 'N1', 'distribute, disseminate, partition, understand', 'BAN(chia,phát)', 'Phân Hiệt là Ban phát,chia.phân đầu người ra ban thưởng.', ARRAY['ハン'], ARRAY['わ.かつ','わ.ける'], 13, 2287, (SELECT id FROM radicals WHERE character = '181')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('飯', 'N4', 'meal, boiled rice', 'PHẠN(cơm)', 'Thực Phản là Phạn cơm.PHẢN đối ĂN nhiều CƠM, để dành tiền cho gái.返:Thay Sước là Phản(trả lại).坂:thay Thổ là Phản(cái dốc).', ARRAY['ハン'], ARRAY['めし'], 12, 1046, (SELECT id FROM radicals WHERE character = '184')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
