INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('悲', 'N3', 'grieve, sad, deplore, regret', 'BI(đau buồn,bi thảm)', 'Phi Tâm là Bi.tâm mà đầy thị phi thì buồn', ARRAY['ヒ'], ARRAY['かな.しい','かな.しむ'], 12, 1014, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('扉', 'N1', 'front door, title page, front page', 'PHI(cánh cửa)', 'Hộ Phi PHi cánh cửa.Người PHI ( 非 ) thường mở CÁNH CỬA ( 扉', ARRAY['ヒ'], ARRAY['とびら'], 12, 1866, (SELECT id FROM radicals WHERE character = '63')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('批', 'N1', 'criticism, strike', 'PHÊ(phê bình)', 'Thủ Bỉ là Phê bình.Tay so sánh tỉ lệ rồi PHÊ bình', ARRAY['ヒ'], NULL, 7, 568, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
