INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('彪', 'BEYOND', 'spotted, mottled, patterned, small tiger', '', '', ARRAY['ヒョウ','ヒュウ'], ARRAY['あや'], 11, 2397, (SELECT id FROM radicals WHERE character = '59')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('標', 'N1', 'signpost, seal, mark, stamp, imprint, symbol, emblem, trademark, evidence, souvenir, target', 'TIÊU(mục tiêu,Ngọn)', 'Mộc Phiếu(chứng chỉ:Tây Thị 票 ) là TIêu bản.Dán phiếu lên cây để làm tiêu chuẩn đánh giá ( cây tốt hay k,vv).漂:Thêm THủy là Phiêu lưu', ARRAY['ヒョウ'], ARRAY['しるべ','しるし'], 15, 686, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('氷', 'N2', 'icicle, ice, hail, freeze, congeal', 'BĂNG(nước đá)', 'Thủy Chủ là Băng.Thêm 1 giọt bên trái Nước sẽ đóng thành BĂNG', ARRAY['ヒョウ'], ARRAY['こおり','ひ','こお.る'], 5, 1450, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('漂', 'N1', 'drift, float (on liquid)', 'PHIÊU(phảng phất)', 'Thủy Phiếu(lá phiếu,chứng chỉ:票)là Phiêu diêu,phảng phất.標:Thay Mộc là Tiêu phí', ARRAY['ヒョウ'], ARRAY['ただよ.う'], 14, 1492, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('瓢', 'BEYOND', 'gourd', '', '', ARRAY['ヒョウ'], ARRAY['ひさご','ふくべ'], 17, NULL, (SELECT id FROM radicals WHERE character = '97')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('票', 'N1', 'ballot, label, ticket, sign', 'PHIẾU(lá phiếu,chứng chỉ)', 'Tây Thị là Phiếu.標:Thêm Mộc là Tiêu phí.漂:Thêm Thủy là Phiêu lưu.', ARRAY['ヒョウ'], NULL, 11, 489, (SELECT id FROM radicals WHERE character = '113')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('表', 'N3', 'surface, table, chart, diagram', 'BIỂU(biểu hiện)', 'Thổ Y là Biểu hiện.Người nhân sĩ 士 thể hiện 表す qua y phục 衣.俵:Thêm Nhân là Biếu.', ARRAY['ヒョウ'], ARRAY['おもて','-おもて','あらわ.す','あらわ.れる','あら.わす'], 8, 77, (SELECT id FROM radicals WHERE character = '145')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('評', 'N1', 'evaluate, criticism, comment', 'BÌNH(bình luận)', 'Ngôn Bình là Bình luận.坪:Thay Thổ là Bình(đv đo sàn nhà).', ARRAY['ヒョウ'], NULL, 12, 454, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
