INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('描', 'N1', 'sketch, compose, write, draw, paint', 'MIÊU(miêu tả,vẽ)', 'Thủ Miêu(cây con,cây giống:苗) là Miêu tả.猫:Thêm Khuyển là thành Miêu(con mèo)', ARRAY['ビョウ'], ARRAY['えが.く','か.く'], 11, 876, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('病', 'N4', 'ill, sick', 'BỆNH(bệnh)', 'Nạch Bính là Bệnh ốm.', ARRAY['ビョウ','ヘイ'], ARRAY['や.む','-や.み','やまい'], 10, 384, (SELECT id FROM radicals WHERE character = '104')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('秒', 'N2', 'second (1/60 minute)', 'MIỂU(đv đếm giây)', 'Hòa Thiểu là Miểu giây.妙:Thay Nữ là Diệu(huyền diệu)', ARRAY['ビョウ'], NULL, 9, 1015, (SELECT id FROM radicals WHERE character = '115')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('苗', 'N1', 'seedling, sapling, shoot', 'MIÊU(cây non,lúa non)', 'Thảo ĐIền là Miêu cây non.猫:Thêm Khuyển là Miêu con mèo.描:Thêm Thủ là Miêu tả.', ARRAY['ビョウ','ミョウ'], ARRAY['なえ','なわ-'], 8, 1713, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
