INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('彬', 'BEYOND', 'refined, gentle', '', '', ARRAY['ヒン','フン'], ARRAY['うるわ.しい','あき.らか'], 11, 2174, (SELECT id FROM radicals WHERE character = '59')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('浜', 'N1', 'seacoast, beach, seashore', 'BANH,BINH(bờ biển,kênh cho tàu bè đỗ)', 'Thủy Binh(兵:vũ khí,quân lính.Khâu Bát) là Banh,Binh bờ biển.Binh lính đánh Thuỷ đang tập trận ở BỜ BIỂN', ARRAY['ヒン'], ARRAY['はま'], 10, 645, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('瀕', 'BEYOND', 'shore, brink, verge', '', '', ARRAY['ヒン'], ARRAY['ほとり'], 20, 2367, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('貧', 'N3', 'poverty, poor', 'BẦN(nghèo)', 'Phân Bối là Bần hàn.Tiền phân tán đi hết=&gt; bần cùng', ARRAY['ヒン','ビン'], ARRAY['まず.しい'], 11, 1211, (SELECT id FROM radicals WHERE character = '154')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('賓', 'N1', 'V.I.P., guest', 'TÂN(khách quý,tân khách)', 'Miên Nhất Thiểu Bối là Tân khách quý.', ARRAY['ヒン'], ARRAY['まろうど','したがう'], 15, 1677, (SELECT id FROM radicals WHERE character = '154')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('頻', 'N1', 'repeatedly, recur', 'TẦN(luôn,thường)', 'Bộ Hiệt là Tần:luôn.Tần suất người đi bộ đếm bằng đầu.渉:Thay Thủy là Tần suất.', ARRAY['ヒン'], ARRAY['しき.りに'], 17, 1590, (SELECT id FROM radicals WHERE character = '181')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('敏', 'N1', 'cleverness, agile, alert', 'MẪN(sáng suốt,minh mẫn)', 'Mỗi Phộc là Mẫn tiệp.Mẫn cảm với việc đánh nhau mỗi ngày.繁:Thêm Mịch là Phồn thịnh', ARRAY['ビン'], ARRAY['さとい'], 10, 1042, (SELECT id FROM radicals WHERE character = '66')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('瓶', 'N2', 'bottle, vial, jar, jug, vat, urn', 'BÌNH(chai lọ)', 'Tịnh Ngõa là Bình lọ.', ARRAY['ビン','ヘイ'], ARRAY['かめ'], 11, 1528, (SELECT id FROM radicals WHERE character = '98')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('不', 'N4', 'negative, non-, bad, ugly, clumsy', 'BẤT(Chẳng,chẳng thể..)', 'cây cụt ngọn chẳng thể(Bất) lớn', ARRAY['フ','ブ'], NULL, 4, 101, (SELECT id FROM radicals WHERE character = '1')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('付', 'N3', 'adhere, attach, refer to, append', 'PHÓ(Giao phó cho. Tiêu ra.)', 'Thằng lớp PHÓ có dáng NGƯỜI ĐỨNG nhìn rất THỐN.', ARRAY['フ'], ARRAY['つ.ける','-つ.ける','-づ.ける','つ.け','つ.け-','-つ.け','-づ.け','-づけ','つ.く','-づ.く','つ.き','-つ.き','-つき','-づ.き','-づき'], 5, 322, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('夫', 'N3', 'husband, man', 'PHU(chồng)', 'Nhất 一 đại 大 trượng phu 夫', ARRAY['フ','フウ','ブ'], ARRAY['おっと','それ'], 4, 335, (SELECT id FROM radicals WHERE character = '37')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('婦', 'N3', 'lady, woman, wife, bride', 'PHỤ(đàn bà)', 'Nữ Trửu là Phụ nữ.Sau khi về nhà (帰) và vứt bỏ cây đao (リ)người con gái 女 trở thành PHỤ nữ 婦Nữ ký mịch cân Phụ nữ', ARRAY['フ'], ARRAY['よめ'], 11, 671, (SELECT id FROM radicals WHERE character = '38')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('富', 'N3', 'wealth, enrich, abundant', 'PHÚ(giàu có)', 'Miên Phó(phó giám đốc) bỏ đao là PHÚ quý.Phó giám đốc khi nào chả giàu', ARRAY['フ','フウ'], ARRAY['と.む','とみ'], 12, 644, (SELECT id FROM radicals WHERE character = '40')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('冨', 'BEYOND', 'enrich, wealthy, abundant', '', '', ARRAY['フ','フウ'], ARRAY['と.む','とみ'], 11, 1906, (SELECT id FROM radicals WHERE character = '14')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
