INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('幅', 'N2', 'hanging scroll, width', 'PHÚC(bề rộng)', '福:Thêm Thị(cho xem) là Phúc(may mắn,hạnh phúc)副:Thêm Đao là Phó(phó giám đốc)Cân Nhất Khẩu Điền là Phúc', ARRAY['フク'], ARRAY['はば'], 12, 641, (SELECT id FROM radicals WHERE character = '50')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('服', 'N4', 'clothing, admit, obey, discharge', 'PHỤC(trang phục)', 'y phục trên mặt trăng có chữ F x', ARRAY['フク'], NULL, 8, 873, (SELECT id FROM radicals WHERE character = '74')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('福', 'N3', 'blessing, fortune, luck, wealth', 'PHÚC(hạnh phúc)', '幅:Thay Cân là Phúc(bề dày).副:Thay Đao là Phó giám đốc.', ARRAY['フク'], NULL, 13, 467, (SELECT id FROM radicals WHERE character = '113')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('腹', 'N3', 'abdomen, belly, stomach', 'PHÚC(bụng)', 'Nhục Phục(phục hồi:复Triệt Nhật Tri)là Phúc bụng.複:Thay Y là Phức tạp.復:Thay Xích là Phục hồi.', ARRAY['フク'], ARRAY['はら'], 13, 1286, (SELECT id FROM radicals WHERE character = '130')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('複', 'N2', 'duplicate, double, compound, multiple', 'PHỨC(phức tạp,nhiều lớp,áo kép)', 'Y PHục(phục hồi:复Triệt Nhật Tri)là Phức tạp.腹:Thay Nhục là Phúc(cái bụng).復:Thay Xích là Phục hồi.', ARRAY['フク'], NULL, 14, 915, (SELECT id FROM radicals WHERE character = '145')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('覆', 'N1', 'capsize, cover, shade, mantle, be ruined', 'PHÚC(che phủ,gói)', 'Tây Phúc,Phục(lại,báo đáp,phục hồi:復)là Phúc che phủ.履:Thay Thi là Lý lịch.', ARRAY['フク'], ARRAY['おお.う','くつがえ.す','くつがえ.る'], 18, 1378, (SELECT id FROM radicals WHERE character = '146')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('淵', 'BEYOND', 'abyss, edge, deep pool, the depths', '', '', ARRAY['エン','カク','コウ'], ARRAY['ふち','かた.い','はなわ'], 12, 1593, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('払', 'N3', 'pay, clear out, prune, banish, dispose of', 'PHẤT(trả tiền,phủi)', 'Thủ Khư là Phất.phất tay lên cứ khư khư đòi trả tiền', ARRAY['フツ','ヒツ','ホツ'], ARRAY['はら.う','-はら.い','-ばら.い'], 5, 813, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('沸', 'N2', 'seethe, boil, ferment, uproar, breed', 'PHÍ(đun sôi)', 'Thủy Phất(chẳng,trừ đi:弗) là Phí đun sôi.費:Thay Bối là Phí tổn', ARRAY['フツ'], ARRAY['わ.く','わ.かす'], 8, 1709, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('仏', 'N2', 'Buddha, the dead, France', 'PHẬT(Phật giáo,Nước Pháp)', 'phật :người ngồi 1 mình', ARRAY['ブツ','フツ'], ARRAY['ほとけ'], 4, 819, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('物', 'N4', 'thing, object, matter', 'VẬT(động vật)', 'Ngưu Vật(chớ,không được:勿) là động Vật.', ARRAY['ブツ','モツ'], ARRAY['もの','もの-'], 8, 215, (SELECT id FROM radicals WHERE character = '93')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('分', 'N5', 'part, minute of time, segment, share, degree, one''s lot, duty, understand, know, rate, 1%, chances, shaku/100', '', '', ARRAY['ブン','フン','ブ'], ARRAY['わ.ける','わ.け','わ.かれる','わ.かる','わ.かつ'], 4, 24, (SELECT id FROM radicals WHERE character = '18')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('吻', 'BEYOND', 'proboscis', '', '', ARRAY['フン','ブン'], ARRAY['くちわき','くちさき'], 7, NULL, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('噴', 'N1', 'erupt, spout, emit, flush out', 'PHÚN(xì ra,phun ra,thổi)', 'ăn sò lông ăn luôn 10 cộng cỏ không được PHÚN phun ra :vPhún thổi miệng mua mười nhánh hoa bằng tiềnPhần(mộ phần):墳Phẫn(phẫn nộ):憤', ARRAY['フン'], ARRAY['ふ.く'], 15, 1270, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('墳', 'N1', 'tomb, mound', 'PHẦN(mộ phần)', 'Phần(mộ phần):墳Phẫn(phẫn nộ):憤Phún(xì ra,phun thổi):噴dùng tiền mua 10 nhánh cỏ:Bí(rực rỡ,sáng sủa)', ARRAY['フン'], NULL, 15, 1822, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('憤', 'N1', 'aroused, resent, be indignant, anger', 'PHẪN(phẫn nộ)', 'Tâm Thập Thảo Bối là PhẫnTâm Bí,BÔn(賁:rực rỡ,sáng sủa) là Phẫn nộ.噴:thêm Khẩu là Phún(phun ra).墳:Thêm Thổ là Phần(mộ phần).', ARRAY['フン'], ARRAY['いきどお.る'], 15, 1863, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('焚', 'BEYOND', 'burn, kindle, build a fire, boil, cook', '', '', ARRAY['フン','ホン','ハン'], ARRAY['た.く','や.く','やきがり'], 12, NULL, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('奮', 'N1', 'stirred up, be invigorated, flourish', 'PHẤN(hăng hái)', 'Cảm giác phấn khích khi thấy chim lớn ngoài đồngĐoạt được ruộng thấy phấn khởi', ARRAY['フン'], ARRAY['ふる.う'], 16, 1521, (SELECT id FROM radicals WHERE character = '37')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('粉', 'N2', 'flour, powder, dust', 'PHẤN(bột)', 'Mễ Phân là Phấn bột gạo.紛:Thay Mịch là Phân(lộn xộn).', ARRAY['フン'], ARRAY['デシメートル','こ','こな'], 10, 1484, (SELECT id FROM radicals WHERE character = '119')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('紛', 'N1', 'distract, be mistaken for, go astray, divert', 'PHÂN(bối rối,phân vân)', 'Mịch Phân là Phân vân,bối rối.', ARRAY['フン'], ARRAY['まぎ.れる','-まぎ.れ','まぎ.らす','まぎ.らわす','まぎ.らわしい'], 10, 994, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('雰', 'N1', 'atmosphere, fog', 'PHÂN(bầu không khí)', 'Vũ Phân là Phân:bầu không khí.Xuán phân.Mưa phân ra thành sương mù', ARRAY['フン'], NULL, 12, 1341, (SELECT id FROM radicals WHERE character = '173')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('文', 'N4', 'sentence, literature, style, art, decoration, figures, plan, literary radical (no. 67)', '', '', ARRAY['ブン','モン'], ARRAY['ふみ','あや'], 4, 190, (SELECT id FROM radicals WHERE character = '67')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('聞', 'N5', 'hear, ask, listen', 'VĂN(nghe,hỏi)', 'Môn Nhĩ Văn nghe,hỏi.', ARRAY['ブン','モン'], ARRAY['き.く','き.こえる'], 14, 319, (SELECT id FROM radicals WHERE character = '128')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('丙', 'N1', 'third class, 3rd, 3rd calendar sign', 'BÍNH(can,Bính Tý)', 'Nhất là TRONG năm Bính Tý(1996) phải đẻ con gái', ARRAY['ヘイ'], ARRAY['ひのえ'], 5, NULL, (SELECT id FROM radicals WHERE character = '1')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('併', 'N1', 'join, get together, unite, collective', '', '', ARRAY['ヘイ'], ARRAY['あわ.せる'], 8, 966, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('兵', 'N2', 'soldier, private, troops, army, warfare, strategy, tactics', '', '', ARRAY['ヘイ','ヒョウ'], ARRAY['つわもの'], 7, 522, (SELECT id FROM radicals WHERE character = '12')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('塀', 'N1', 'fence, wall, (kokuji)', 'BIÊN(tường rào)', 'Biên giới làm bằng đất đắp thành khai ở cổng phòngThổ thi bính Biên', ARRAY['ヘイ','ベイ'], NULL, 12, 1991, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('幣', 'N1', 'cash, bad habit, humble prefix, gift, Shinto offerings of cloth, rope, cut paper', 'TỆ(tiền tệ)', 'Tệ(nát,hẹp hòi) 敝 và Cân là Tệ(tiền tệ)弊:Thêm Củng là Tệ(tệ bạc)', ARRAY['ヘイ'], ARRAY['ぬさ'], 15, 1803, (SELECT id FROM radicals WHERE character = '50')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('平', 'N3', 'even, flat, peace', 'BÌNH(bằng phẳng,hòa bình)', '評:Thêm Ngôn là Bình(bình luận)坪:Thêm Thổ là Bình(đơn vị đo sàn nhà)呼:Thêm Khẩu là Hô(gọi,thở ra ngược với hấp)', ARRAY['ヘイ','ビョウ','ヒョウ'], ARRAY['たい.ら','たい.らげる','ひら'], 5, 128, (SELECT id FROM radicals WHERE character = '51')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('弊', 'N1', 'abuse, evil, vice, breakage', 'TỆ(tệ nạn,xấu,hại,rách)', 'Ngày xưa Lấy Gạo của người khác mà không chắp tay xin phép là tồi TỆ.幣:Bỏ CỦng thêm Cân là Tệ(tiền tệ)', ARRAY['ヘイ'], NULL, 15, 1750, (SELECT id FROM radicals WHERE character = '55')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('柄', 'N1', 'design, pattern, build, nature, character, handle, crank, grip, knob, shaft', 'BÍNH(kiểu,tính cách,quyền bính)', 'Mộc Bính là Bính病:Thêm Nạch là Bệnh tật', ARRAY['ヘイ'], ARRAY['がら','え','つか'], 9, 1140, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('並', 'N2', 'row, and, besides, as well as, line up, rank with, rival, equal', 'TỊNH(Gồm, đều,giống)', 'Hai người đều đứng hát giống nhau', ARRAY['ヘイ','ホウ'], ARRAY['な.み','なみ','なら.べる','なら.ぶ','なら.びに'], 8, 599, (SELECT id FROM radicals WHERE character = '1')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('蔽', 'N1', 'cover, shade, mantle, capsize, be ruined', 'TẾ(che phủ,lấp)', 'Thảo Tệ(nát:敝)là Tệ che phủ.dùng cỏ che lấp gạo 1 cách tinh tế.弊:Thay Củng là Tệ bạc.幣:Thay Cân là tiền Tệ.', ARRAY['ヘイ','ヘツ','フツ'], ARRAY['おお.う','おお.い'], 15, NULL, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('閉', 'N3', 'closed, shut', 'BẾ(đóng)', 'Môn Tài là Bế đóng.Đóng CỬA(MÔN) BẾ (ĐÓNG) quan luyện công mới thành TÀI.', ARRAY['ヘイ'], ARRAY['と.じる','と.ざす','し.める','し.まる','た.てる'], 11, 951, (SELECT id FROM radicals WHERE character = '169')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('陛', 'N1', 'highness, steps (of throne)', 'BỆ(vua)', 'Phụ Tỉ Thổ là Bệ hạ.thiên tử.Bệ hạ có hàng Tỉ miếng Đất', ARRAY['ヘイ'], NULL, 10, 1429, (SELECT id FROM radicals WHERE character = '170')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('米', 'N3', 'rice, USA, metre', '', '', ARRAY['ベイ','マイ','メエトル'], ARRAY['こめ','よね'], 6, 61, (SELECT id FROM radicals WHERE character = '119')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('頁', 'BEYOND', 'page, leaf', '', '', ARRAY['ケツ'], ARRAY['ぺえじ','おおがい','かしら'], 9, NULL, (SELECT id FROM radicals WHERE character = '181')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('壁', 'N1', 'wall, lining (stomach), fence', 'BÍCH(bức tường)', 'Thi khẩu tân thổ là BíchTường của Lầu ngưng Bích được xây từ đất và đá cay đắng', ARRAY['ヘキ'], ARRAY['かべ'], 16, 1037, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('癖', 'N1', 'mannerism, habit, vice, trait, fault, kink', 'PHÍCH(tật xấu)', 'Nạch Tích(trừ bỏ đi:辟) là Phích tật xấu.Trong giường bệnh mở mồm trước cửa nói lời cay đắng đó là thói xấu tật hư.璧:Thay Ngọc là Bích(ngọc bích).壁:Thay Thổ là Bích tường.', ARRAY['ヘキ'], ARRAY['くせ','くせ.に'], 18, 1973, (SELECT id FROM radicals WHERE character = '104')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('碧', 'BEYOND', 'blue, green', '', '', ARRAY['ヘキ','ヒャク'], NULL, 14, 2455, (SELECT id FROM radicals WHERE character = '112')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('別', 'N4', 'separate, branch off, diverge, fork, another, extra, specially', 'BIỆT(chia tay,ly biệt,tống biệt,chia)', 'Lúc ly biệt nói vạn lời sắc như dao đâm', ARRAY['ベツ'], ARRAY['わか.れる','わ.ける'], 7, 214, (SELECT id FROM radicals WHERE character = '18')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('瞥', 'BEYOND', 'glance at', '', '', ARRAY['ベツ','ヘツ'], NULL, 17, NULL, (SELECT id FROM radicals WHERE character = '109')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('蔑', 'N1', 'ignore, despise, neglect, ridicule', 'MIỆT(miệt thị,khinh thường)', 'Thảo Võng Tuất(Mậu Nhất) là Miệt thị.cô giáo Thảo có ánh mắt miệt thị người thành công', ARRAY['ベツ'], ARRAY['ないがしろ','なみ.する','くらい','さげす.む'], 14, 2483, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('偏', 'N1', 'partial, side, left-side radical, inclining, biased', 'THIÊN(lệch,nghiêng hẳn về 1 bên,thiên vị)', 'Người(trọng tài) THiên vị mở toang cánh cửa(hộ) cho đội bạn vào chung kếtNhân Biên(dẹt, mỏng, bẹp) THiên(lệch) vị', ARRAY['ヘン'], ARRAY['かたよ.る'], 11, 1340, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('変', 'N3', 'unusual, change, strange', 'BIẾN(thay đổi,biến thiên)', 'Chạy nhanh khi màu đỏ biến đổi', ARRAY['ヘン'], ARRAY['か.わる','か.わり','か.える'], 9, 238, (SELECT id FROM radicals WHERE character = '34')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('片', 'N2', 'one-sided, leaf, sheet, right-side kata radical (no. 91)', '', '', ARRAY['ヘン'], ARRAY['かた-','かた'], 4, 1076, (SELECT id FROM radicals WHERE character = '91')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('篇', 'BEYOND', 'volume, chapter, book, editing, compilation', '', '', ARRAY['ヘン'], NULL, 15, 2076, (SELECT id FROM radicals WHERE character = '118')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('編', 'N2', 'compilation, knit, plait, braid, twist, editing, completed poem, part of a book', 'BIÊN(biên tập,đan,Cái lề sách)', 'Mịch Thiên(mỏng,giẹt:扁:Hộ Sách)là Biên tập,lề sách.偏:Thay Nhân là THiên vị.遍:Thay SƯớc là phổ Biến.', ARRAY['ヘン'], ARRAY['あ.む','-あ.み'], 15, 591, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('辺', 'N2', 'environs, boundary, border, vicinity', 'BIÊN(lân cận)', 'Sước Đao là Biên giới.đi qua đường BIÊN giới sẻ ăn đao', ARRAY['ヘン'], ARRAY['あた.り','ほと.り','-べ'], 5, 428, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('返', 'N3', 'return, answer, fade, repay', 'PHẢN(trả lại)', 'Sước Phản là Phản trả lại,trở lại.Có nên mở ĐƯỜNG (辶) cho kẻ PHẢN (反) bội TRỞ LẠI (返)? Đánh kẻ chạy đi chứ không ai đánh người chạy lại...飯:Thay Thực là Phạn(cơm).坂:Thay Thổ là Phản(cái dốc).', ARRAY['ヘン'], ARRAY['かえ.す','-かえ.す','かえ.る','-かえ.る'], 7, 685, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('遍', 'N1', 'everywhere, times, widely, generally', 'BIẾN(khắp cùng,lần)', 'Sước Biển(giẹt,mỏng:扁Hộ Sách)là Biến khắp.phổ biến.偏:Thay Nhân là Thiên vị.編:Thay Mịch là Biên tập.', ARRAY['ヘン'], ARRAY['あまね.く'], 12, 1845, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('便', 'N3', 'convenience, facility, excrement, feces, letter, chance', 'TIỆN(Tiện lợi,phân)', 'ĐTdđ càng(canh)TIỆN lợi để người xem canh giờ(canh :更,giống sử 史)', ARRAY['ベン','ビン'], ARRAY['たよ.り'], 9, 729, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('勉', 'N4', 'exertion, endeavour, encourage, strive, make effort, diligent', 'MIỄN(cố gắng)', 'miễn(免) lực là MIỄN hết sức LỰC cũng phải cố gắng học kanji@@Miễn Lực là Miễn(cố gắng)', ARRAY['ベン'], ARRAY['つと.める'], 10, 1066, (SELECT id FROM radicals WHERE character = '19')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('娩', 'BEYOND', 'bear (children)', '', '', ARRAY['ベン'], NULL, 11, NULL, (SELECT id FROM radicals WHERE character = '38')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('弁', 'N1', 'valve, petal, braid, speech, dialect, discrimination, dispose of, distinguish, conical cap', 'BIỆN(hùng biện)', 'Khư Củng là Biện.chấp tay biện minh (hùng biện) cho hành động của mình (tư)', ARRAY['ベン','ヘン'], ARRAY['かんむり','わきま.える','わ.ける','はなびら','あらそ.う'], 5, 619, (SELECT id FROM radicals WHERE character = '55')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鞭', 'BEYOND', 'whip, rod, counter for whippings', '', '', ARRAY['ベン','ヘン'], ARRAY['むち','むちうつ'], 18, NULL, (SELECT id FROM radicals WHERE character = '177')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('保', 'N1', 'protect, guarantee, keep, preserve, sustain, support', 'BẢO(giữ,gánh vác,Kẻ làm thuê,Bầu)', 'BẢO kê là người có mồm khi nào cũng ở trên cây(bốc phét)', ARRAY['ホ','ホウ'], ARRAY['たも.つ'], 9, 146, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('舗', 'N1', 'shop, store, pave', 'PHỐ(cửa hàng)', 'Xá(舎) thêm Phủ là Phố xá.', ARRAY['ホ'], NULL, 15, 1412, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('圃', 'BEYOND', 'garden, field', '', '', ARRAY['ホ','フ'], ARRAY['はたけ','にわ'], 10, NULL, (SELECT id FROM radicals WHERE character = '31')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('捕', 'N3', 'catch, capture', 'BỔ,BỘ(bắt,nắm bắt)', 'Thủ Phủ(甫:tên gọi tôn quý của đàn ông,ĐỖ phủ) là Bổ đầu(bắt trộm)補:Thêm Y là Bổ sung哺:Thêm Khẩu là Bộ(mớm)', ARRAY['ホ'], ARRAY['と.らえる','と.らわれる','と.る','とら.える','とら.われる','つか.まえる','つか.まる'], 10, 604, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('歩', 'N4', 'walk, counter for steps', '', '', ARRAY['ホ','ブ','フ'], ARRAY['ある.く','あゆ.む'], 8, 554, (SELECT id FROM radicals WHERE character = '77')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('甫', 'BEYOND', 'for the first time, not until', '', '', ARRAY['ホ','フ'], ARRAY['はじ.めて'], 7, 2270, (SELECT id FROM radicals WHERE character = '101')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('補', 'N2', 'supplement, supply, make good, offset, compensate, assistant, learner', 'BỔ(bổ sung,bù,vá áo)', 'Y PHủ là Bổ sung.捕:Thay Thủ là Bổ,Bộ(bắt).哺:Thay Khẩu là Bộ mớm.浦:Thay Thủy là Phổ(bến sông).舗:Thay.. là Phố xá.', ARRAY['ホ'], ARRAY['おぎな.う'], 12, 332, (SELECT id FROM radicals WHERE character = '145')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('輔', 'BEYOND', 'help', '', '', ARRAY['ホ','フ'], ARRAY['たす.ける'], 14, 1898, (SELECT id FROM radicals WHERE character = '159')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('穂', 'N1', 'ear, ear (grain), head, crest (wave)', '', '', ARRAY['スイ'], ARRAY['ほ'], 15, 1656, (SELECT id FROM radicals WHERE character = '115')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('募', 'N2', 'recruit, campaign, gather (contributions), enlist, grow violent', 'MỘ(tìm,xin,chiêu mộ)', 'Chiêu MỘ một lực lượng to lớn để dọn cỏ trong 1 ngàyTHảo nhật đại lực:Mộ dung phụcthêm Nhật là Mộ(trời tối):暮thêm Tâm là Mộ(hâm mộ):慕thêm Thổ là Mộ(ngôi mộ):墓', ARRAY['ボ'], ARRAY['つの.る'], 12, 809, (SELECT id FROM radicals WHERE character = '19')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('墓', 'N1', 'grave, tomb', 'MỘ(ngôi mộ,mả)', 'Trên là cỏ hoa mặt trời chiếu dưới có mái đất che là ngội mộ', ARRAY['ボ'], ARRAY['はか'], 13, 1337, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('慕', 'N1', 'pining, yearn for, love dearly, adore', 'MỘ(ái mộ)', 'Mạc,Mộ(莫:mộc mạc,tuyệt không) Tâm là MỘ(ái mộ).墓:thêm thổ là MỘ(ngôi mộ).暮:thêm Nhật là Mộ(trời tối).募:thêm Lực là chiêu Mộ.幕:Thêm Cân là Mạc(cái rèm).', ARRAY['ボ'], ARRAY['した.う'], 14, 2100, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
