INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('褒', 'N1', 'praise, extol', 'BAO(khen ngợi)', 'Y Bảo là Bao khen ngợi.Đầu Bảo Y là Bao khenKhen ngợi người bảo vệ y phục trong nhà', ARRAY['ホウ'], ARRAY['ほ.める'], 15, 2073, (SELECT id FROM radicals WHERE character = '145')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('訪', 'N3', 'call on, visit, look up, offer sympathy', 'PHỎNG(thăm hỏi,đi thăm chơi)', 'Ngôn Phương là Phỏng đến .Nói bạn ở Phương nào để Phỏng ( Viếng Thăm ).房:Thay Nghiễm là căn Phòng.防:Thay Phụ là Phòng chống.', ARRAY['ホウ'], ARRAY['おとず.れる','たず.ねる','と.う'], 11, 372, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('豊', 'N2', 'bountiful, excellent, rich', 'PHONG(phong phú)', 'Khúc Đậu là Phong phú.Bài hát về đậu rất là PHONG phú.艶:Thêm Sắc là Diễm lệ.', ARRAY['ホウ','ブ'], ARRAY['ゆた.か','とよ'], 13, 762, (SELECT id FROM radicals WHERE character = '151')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
