INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('乏', 'N1', 'destitution, scarce, limited', 'PHẠP(Thiếu,không có đủ)', 'Thiếu ngủ(PHẠP) ngáp zzz', ARRAY['ボウ'], ARRAY['とぼ.しい','とも.しい'], 4, 1646, (SELECT id FROM radicals WHERE character = '4')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
