INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('剖', 'N1', 'divide', 'PHẪU(phanh ra,giải phẫu,mổ)', 'Bác sĩ dùng dao Đứng giải PHẪU vị trí MiệngBộ(bộ phận):部Bội(bội số):倍Bộ đao là phẫu', ARRAY['ボウ'], NULL, 10, 1918, (SELECT id FROM radicals WHERE character = '18')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('坊', 'N2', 'boy, priest''s residence, priest', 'PHƯỜNG(thầy tu,cậu bé)', 'Vùng đất địa phương Phương --&gt; PhườngThổ phương Phường', ARRAY['ボウ','ボッ'], NULL, 7, 1832, (SELECT id FROM radicals WHERE character = '32')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('妨', 'N1', 'disturb, prevent, hamper, obstruct', 'PHƯƠNG(ngăn cản,hại,ngại)', 'Phụ Nữ đơn PHƯƠNG CẢN TRỞ các mối quan hệ của chồng', ARRAY['ボウ'], ARRAY['さまた.げる'], 7, 1482, (SELECT id FROM radicals WHERE character = '38')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('帽', 'N2', 'cap, headgear', 'MẠO(cái mũ)', 'Lấy khăn thay mũ che ánh nắng mặt trời khỏi chói mắtMạo(冒:mạo hiểm) thêm Cân là Mạo Tử(cái mũ)', ARRAY['ボウ','モウ'], ARRAY['ずきん','おお.う'], 12, 1742, (SELECT id FROM radicals WHERE character = '50')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('忘', 'N3', 'forget', 'VONG(quên)', 'Vong,Vô Tâm là VOng(quên)Con tim chỉ khi chết đi sẽ quên được mọi thứ', ARRAY['ボウ'], ARRAY['わす.れる'], 7, 1129, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('忙', 'N3', 'busy, occupied, restless', 'MANG(bận rộn)', 'Tâm Vong là Mang.Người ta chỉ BẬN (忙) với bạn khi trong TIM (忄) của họ đã MẤT (亡) đi bạn rồi.', ARRAY['ボウ','モウ'], ARRAY['いそが.しい','せわ.しい','おそ.れる','うれえるさま'], 6, 1475, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('房', 'N1', 'tassel, tuft, fringe, bunch, lock (hair), segment (orange), house, room', 'PHÒNG(cái buồng,chùm)', 'Hộ Phương mở cửa Phòng', ARRAY['ボウ'], ARRAY['ふさ'], 8, 808, (SELECT id FROM radicals WHERE character = '63')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('暴', 'N2', 'outburst, rave, fret, force, violence, cruelty, outrage', 'BẠO(bạo lực,tàn bạo,làm hại)', 'Nhật Cung,Cộng THủy là Bạo lực爆:Thêm Hỏa là BỘc phá', ARRAY['ボウ','バク'], ARRAY['あば.く','あば.れる'], 15, 692, (SELECT id FROM radicals WHERE character = '72')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('望', 'N3', 'ambition, full moon, hope, desire, aspire to, expect', 'VỌNG(hy vọng)', 'Vong Nguyệt Vương là Vọng tưởng.Nguyện vọng của vua trước khi chết là nhìn thấy ánh trăng', ARRAY['ボウ','モウ'], ARRAY['のぞ.む','もち'], 11, 470, (SELECT id FROM radicals WHERE character = '74')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('某', 'N1', 'so-and-so, one, a certain, that person', 'MỖ(tôi)', 'Cam Mộc là Mỗ(tôi).謀:Thêm Ngôn là Mưu mô.媒:Thêm Nữ là Môi giới.', ARRAY['ボウ'], ARRAY['それがし','なにがし'], 9, 2106, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('棒', 'N2', 'rod, stick, cane, pole, club, line', 'BỔNG(cây gậy)', 'Mộc Phụng(奉:dâng hiến,vâng,phụng sự) là Bổng(đả cẩu bổng)俸:Thêm Nhân là Bổng lộc', ARRAY['ボウ'], NULL, 12, 1455, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('冒', 'N1', 'risk, face, defy, dare, damage, assume (a name)', 'MẠO(mạo hiểm,trùm đậy,phạm)', 'Viết Mục Mạo hiểm.帽:Thêm Cân là Mạo(mũ)', ARRAY['ボウ'], ARRAY['おか.す'], 9, 1317, (SELECT id FROM radicals WHERE character = '13')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('紡', 'N1', 'spinning', 'PHƯỞNG(se chỉ,dệt vải)', 'Mịch Phương là Phưởng dệt vải.Phương dùng sợi chỉ dệt vải.妨:Thay Nữ là Phương hại', ARRAY['ボウ'], ARRAY['つむ.ぐ'], 10, 1876, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('肪', 'N1', 'obese, fat', 'PHƯƠNG(mỡ)', 'Nhục Phương là Phương mỡ.', ARRAY['ボウ'], NULL, 8, 1878, (SELECT id FROM radicals WHERE character = '130')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('膨', 'N1', 'swell, get fat, thick', 'BÀNH(phình lên,trương lên,bành trướng)', 'Nhục Bành(họ Bành:彭)là Bành phình lên.', ARRAY['ボウ'], ARRAY['ふく.らむ','ふく.れる'], 16, 1293, (SELECT id FROM radicals WHERE character = '130')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('謀', 'N1', 'conspire, cheat, impose on, plan, devise, scheme, have in mind, deceive', 'MƯU(âm mưu)', 'Ngôn Mỗ(ông này:某Cam Mộc)là Mưu kế.MƯU mẹo phải dùng NGÔN từ MỘC mạc mà NGỌT ngào!媒:Thay Nữ là Môi giới.', ARRAY['ボウ','ム'], ARRAY['はか.る','たばか.る','はかりごと'], 16, 1370, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('貌', 'N1', 'form, appearance, countenance', 'MẠO(dung mạo)', 'Trãi Bạch Nhân là Mạo dáng mặt.Dung maooj con lửng màu trắng đi bằng 2 chân.', ARRAY['ボウ','バク'], ARRAY['かたち','かたどる'], 14, NULL, (SELECT id FROM radicals WHERE character = '153')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('貿', 'N2', 'trade, exchange', 'MẬU(mậu dịch)', 'Mão Bối là Mậu dịch.Tuổi Mão làm Mậu dịch.', ARRAY['ボウ'], NULL, 12, 652, (SELECT id FROM radicals WHERE character = '154')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('防', 'N2', 'ward off, defend, protect, resist', 'PHÒNG(ngăn ngừa,cái đê)', 'Phụ Phương là Phòng bị,ngừa.Chị PHƯƠNG phải dựa mình vào tường để PHÒNG thủ', ARRAY['ボウ'], ARRAY['ふせ.ぐ'], 7, 331, (SELECT id FROM radicals WHERE character = '170')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('北', 'N5', 'north', 'BẮC(phía bắc,trái,thua)', 'Hai người ngồi đối lưng vào nhau bởi vì phương Bắc rất lạnh', ARRAY['ホク'], ARRAY['きた'], 5, 153, (SELECT id FROM radicals WHERE character = '21')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('僕', 'N1', 'me, I (male), servant, manservant', 'BỘC(tôi,nam xưng,đầy tớ)', 'Hình ảnh người đội mũ kéo xe như con dê chính là nô BỘCthay bằng Thủ(tay) là PHÁC: đánh nhau 撲', ARRAY['ボク'], ARRAY['しもべ'], 14, 1236, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
