INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('明', 'N4', 'bright, light', 'MINH(sáng sủa)', 'Nhật Nguyệt là Minh sáng.', ARRAY['メイ','ミョウ','ミン'], ARRAY['あ.かり','あか.るい','あか.るむ','あか.らむ','あき.らか','あ.ける','-あ.け','あ.く','あ.くる','あ.かす'], 8, 67, (SELECT id FROM radicals WHERE character = '72')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('盟', 'N1', 'alliance, oath', 'MINH(đồng minh,thề)', 'Minh Mãnh là Minh.Nếu là ĐỒNG MINH thì NGÀY MAI ăn chung một cái ĐĨA', ARRAY['メイ'], NULL, 13, 587, (SELECT id FROM radicals WHERE character = '108')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('迷', 'N3', 'astray, be perplexed, in doubt, lost, err, illusion', 'MÊ(lạc đường)', 'Sước Mễ là Mê lạc.Tấm phải phân biệt GẠO với thóc lâu quá nên MÊ man đi k vững.謎:Thêm Ngôn là Mê(câu đố)', ARRAY['メイ'], ARRAY['まよ.う'], 9, 942, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('銘', 'N1', 'inscription, signature (of artisan)', 'MINH(ghi khắc)', 'Kim Danh là Minh ghi khắc.', ARRAY['メイ'], NULL, 14, 1394, (SELECT id FROM radicals WHERE character = '167')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('鳴', 'N3', 'chirp, cry, bark, sound, ring, echo, honk', 'MINH(kêu,hót)', 'Khẩu Điểu là Minh hót.Chim hót bằng mồm Minh.', ARRAY['メイ'], ARRAY['な.く','な.る','な.らす'], 14, 1279, (SELECT id FROM radicals WHERE character = '196')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('姪', 'BEYOND', 'niece', '', '', ARRAY['テツ','チツ','ジチ','イツ','イチ'], ARRAY['めい','おい'], 9, NULL, (SELECT id FROM radicals WHERE character = '38')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('滅', 'N1', 'destroy, ruin, overthrow, perish', 'DIỆT(tiêu diệt,tắt,hết)', 'Thủy Tuất Hỏa là Diệt.ngọn lửa nhỏ mà chiến đấu với dòng nước lớn thì sẽ thành diệt vong', ARRAY['メツ'], ARRAY['ほろ.びる','ほろ.ぶ','ほろ.ぼす'], 13, 1222, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('免', 'N1', 'excuse, dismissal', 'MIỄN(bỏ,khỏi,truất,cách,bãi miễn)', 'gô mên,Miễn:Sắc có chân', ARRAY['メン'], ARRAY['まぬか.れる','まぬが.れる'], 8, 1080, (SELECT id FROM radicals WHERE character = '10')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('綿', 'N2', 'cotton', 'MIÊN(bông vải)', 'Mịch Bạch(lụa:帛:Bạch Cân)là Miên bông vải.Miếng vải có sợi chỉ trắng dài MIÊN man.錦:Thay Kim là Cẩm(vải vóc,thổ cẩm)', ARRAY['メン'], ARRAY['わた'], 14, 1495, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('面', 'N3', 'mask, face, features, surface', '', '', ARRAY['メン','ベン'], ARRAY['おも','おもて','つら'], 9, 186, (SELECT id FROM radicals WHERE character = '176')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('麺', 'N1', 'noodles, wheat flour', 'MIẾN(sợi mì,miến)', 'Mạch DIện là Miến:mì sợi.Mặt của lúa mì là sợi Miến.', ARRAY['メン','ベン'], ARRAY['むぎこ'], 16, 2331, (SELECT id FROM radicals WHERE character = '199')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('模', 'N1', 'imitation, copy, mock', 'MÔ(khuôn mẫu,mô hình,mô phỏng)', 'Mộc Mạc(莫:tuyệt không,chẳng không) là Mô hình.膜:Thêm Nhục là Mô,màng.摸:Thêm Thủ là Mạc(sao lại).漠:Thêm Thủy là sa MẠc.', ARRAY['モ','ボ'], NULL, 14, 668, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('茂', 'N1', 'overgrown, grow thick, be luxuriant', 'MẬU(mọc tốt)', 'Thảo Mậu(can 5:戊Triệt Qua)là Mậu mọc tốt.', ARRAY['モ'], ARRAY['しげ.る'], 8, 1188, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
