INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('猛', 'N1', 'fierce, rave, rush, become furious, wildness, strength', 'MÃNH(mãnh liệt,mạnh,nghiêm ngặt)', 'Khuyển Mạnh(孟:lớn,mới) là Mãnh tướng.chó 犬 con 子 liếm đĩa cháo 皿 dũng mãnh 猛 lạ thường', ARRAY['モウ'], NULL, 11, 1301, (SELECT id FROM radicals WHERE character = '94')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('盲', 'N1', 'blind, blind man, ignoramus', 'MANH(mù,lòa)', 'Vong Mục là Manh mù.Mắt chết là mù', ARRAY['モウ'], ARRAY['めくら'], 8, 1767, (SELECT id FROM radicals WHERE character = '109')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('網', 'N1', 'netting, network', 'VÕNG(lưới)', 'Mịch Võng(cái lưới:罔VÕng网 Vô)là VÕng lưới.Mịch Quynh Thảo Vong là Võng lưới.dùng chỉ móc thành tấm lưới, cá nhảu vào trong thì chỉ có chết', ARRAY['モウ'], ARRAY['あみ'], 14, 1194, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('耗', 'N1', 'decrease', 'HAO(tiêu hao,hao hụt)', 'Lỗi Mao là Hao sút.Ông Mao phạm Lỗi làm HAO tài tốn của', ARRAY['モウ','コウ'], NULL, 10, NULL, (SELECT id FROM radicals WHERE character = '127')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
