INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('勿', 'BEYOND', 'not, must not, do not, be not', '', '', ARRAY['モチ','ブツ','ボツ'], ARRAY['なか.れ','なし'], 4, NULL, (SELECT id FROM radicals WHERE character = '20')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('餅', 'N1', 'mochi rice cake', 'BÍNH(bánh)', 'Thực Tịnh là Bính(bánh).tịnh dùng thức ăn để làm bánh giày併:Thay Nhân là Tính:hợp lại,gộp.', ARRAY['ヘイ','ヒョウ'], ARRAY['もち','もちい'], 14, 2152, (SELECT id FROM radicals WHERE character = '184')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('尤', 'BEYOND', 'reasonable, just, natural, superb, outstanding, plausible', '', '', ARRAY['ユウ'], ARRAY['もっと.も','とが.める'], 4, NULL, (SELECT id FROM radicals WHERE character = '43')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('戻', 'N3', 're-, return, revert, resume, restore, go backwards', 'LỆ(quay lại)', 'Hộ Đại là Lệ.Xin HỘ chiếu ở ĐẠI sứ quán thì theo luật Lệ phải QUAY LẠI Việt Nam xin.涙:Thêm Thủy là LỆ(nước mắt)', ARRAY['レイ'], ARRAY['もど.す','もど.る'], 7, 890, (SELECT id FROM radicals WHERE character = '63')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
