INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('野', 'N4', 'plains, field, rustic, civilian life', 'DÃ(hoang dã)', 'Lí Dư là Dã(đồng,cõi,quê mùa).tôi dự予 định về làng 里　sống thôn dã野, trồng rau　野菜', ARRAY['ヤ','ショ'], ARRAY['の','の-'], 11, 120, (SELECT id FROM radicals WHERE character = '166')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('弥', 'N1', 'all the more, increasingly', 'DI,MY(khắp,đầy,)', 'Cung Nhĩ(尔:vậy..) là DI,MỴ.Người Nhỏ như cây Cung thì có thể DI chuyển KHẮP NƠI.a di đà phậtThay Hoà là Xưng danh xưng,tên gọi.', ARRAY['ミ','ビ'], ARRAY['や','いや','いよ.いよ','わた.る'], 8, 1687, (SELECT id FROM radicals WHERE character = '57')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('矢', 'N1', 'dart, arrow', '', '', ARRAY['シ'], ARRAY['や'], 5, 1294, (SELECT id FROM radicals WHERE character = '111')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('厄', 'N1', 'unlucky, misfortune, bad luck, disaster', 'ÁCH(tai ương,thảm họa,xấu)', 'Hán+ Tiết  bằng ÁCH:tai ương', ARRAY['ヤク'], NULL, 4, 2123, (SELECT id FROM radicals WHERE character = '27')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('役', 'N3', 'duty, war, campaign, drafted labor, office, service, role', 'DỊCH(vai trò,quân dịch,chiến dịch)', 'Xích Thù là Dịch.Chiến dịch lên đường đánh kẻ thù.', ARRAY['ヤク','エキ'], NULL, 7, 315, (SELECT id FROM radicals WHERE character = '60')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('約', 'N3', 'promise, approximately, shrink', 'ƯỚC(khoảng,hứa)', 'Sợi chỉ buộc chặt Bao hẹn ƯỚC.酌:Chước rót rượu.', ARRAY['ヤク'], ARRAY['つづ.まる','つづ.める','つづま.やか'], 9, 94, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('薬', 'N3', 'medicine, chemical, enamel, gunpowder, benefit', 'DƯỢC(thuốc)', 'Thảo Lạc là DƯợc thuốc.Loại cỏ (艹) làm cho thoải mái, dễ chịu (楽) thì là thuốc (薬)', ARRAY['ヤク'], ARRAY['くすり'], 16, 702, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('訳', 'N1', 'translate, reason, circumstance, case', 'DỊCH(phiên dịch)', 'Ngôn Xích là Dịch thuật.Phiên Dịch 訳 là dùng Ngôn 言 từ làm mọi người Xích 尺 lại gần nhau.駅: Thay Mã là Dịch nhà ga.', ARRAY['ヤク'], ARRAY['わけ'], 11, 1050, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('躍', 'N1', 'leap, dance, skip', 'DƯỢC(nhảy)', 'Chân chim tập trung nhảy múa hót yoyo( ヨヨ.濯:Thay Thủy là Trạc(tẩy rữa).曜:Thay Nhật là Diệu ngày.', ARRAY['ヤク'], ARRAY['おど.る'], 21, 900, (SELECT id FROM radicals WHERE character = '157')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('靖', 'BEYOND', 'peaceful', '', '', ARRAY['セイ','ジョウ'], ARRAY['やす.んじる'], 13, 1390, (SELECT id FROM radicals WHERE character = '174')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('柳', 'N1', 'willow', 'LIỄU(cây liễu)', 'Mộc Mão,Mẹo(卯:Chi Mão) là Liễu.', ARRAY['リュウ'], ARRAY['やなぎ'], 9, 1169, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('愉', 'N1', 'pleasure, happy, rejoice', 'DU(vui vẻ,du hí)', 'Tâm Nhân Nhất Nguyệt Đao Du hí.Tâm Du(俞:phải vâng lời.兪) là DU hí vui vẻ.喩:Thêm Khẩu là Khẩu DỤ(ẩn dụ)諭:Thêm Khẩu là DỤ(chỉ bảo)', ARRAY['ユ'], ARRAY['たの.しい','たの.しむ'], 12, 1974, (SELECT id FROM radicals WHERE character = '61')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('油', 'N2', 'oil, fat', 'DU(dầu,mỡ,trơn tru)', 'Thủy Do là DU dầu ăn.袖:Thay Y là ống tay áo.', ARRAY['ユ','ユウ'], ARRAY['あぶら'], 8, 690, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('癒', 'N1', 'healing, cure, quench (thirst), wreak', 'DŨ(hết bệnh,khỏi ốm)', 'nạch Dũ(du tâm:愈:càng ngày càng..) là DŨ hết bệnh.bệnh viện từ Dũ chữa hết bệnh.諭:Thay Ngôn là DỤ (chỉ bảo).喩:Thay Khẩu là ẩn DỤ.愉:Thay Tâm là Du(vui vẻ)', ARRAY['ユ'], ARRAY['い.える','いや.す','い.やす'], 18, 1667, (SELECT id FROM radicals WHERE character = '104')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('諭', 'N1', 'rebuke, admonish, charge, warn, persuade', 'DỤ(rầy la)', 'Ngôn Du là DỤ rầy.dạy bảo(chỉ dụ).愉:Thay Tâm là Du(vui vẻ).輸:Thay Xa là Thâu(nhập khẩu).', ARRAY['ユ'], ARRAY['さと.す'], 16, 1461, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('輸', 'N2', 'transport, send, be inferior', 'THÂU(chuyên chở)', 'Xa Du là Thâu chở.Xe trước nhà dùng để vận chuyển hàng nhập khẩu.愉:Thay Tâm là Du(vui vẻ).諭:Thay Ngôn là DỤ(chỉ bảo).', ARRAY['ユ','シュ'], NULL, 16, 371, (SELECT id FROM radicals WHERE character = '159')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('唯', 'N1', 'solely, only, merely, simply', 'DUY(độc,chỉ,duy nhất)', 'Con chim chỉ có DUY nhất một cái mồmKhẩu Chuy là Duy nhất', ARRAY['ユイ','イ'], ARRAY['ただ'], 11, 1292, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('佑', 'BEYOND', 'help, assist', '', '', ARRAY['ユウ','ウ'], ARRAY['たす.ける'], 7, 2250, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('優', 'N3', 'tenderness, excel, surpass, actor, superiority, gentleness', 'ƯU(nhiều,thừa,hơn,Ưu việt)', 'Nhân bách mịch tâm truy :ƯU việtNhân Ưu(ưu tư:buồn rầu,lo)người ưu tư là siêu việt:GS Ngô Bảo Châu tóc trắng,tâm trở lại VN cống hiến', ARRAY['ユウ','ウ'], ARRAY['やさ.しい','すぐ.れる','まさ.る'], 17, 334, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('勇', 'N2', 'courage, cheer up, be in high spirits, bravery, heroism', 'DŨNG(mạnh,gan lỳ,dũng cảm)', 'dũng(giống chữ giác) lực:là DŨNG cảmất điền lực là DŨng', ARRAY['ユウ'], ARRAY['いさ.む'], 9, 1319, (SELECT id FROM radicals WHERE character = '19')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('友', 'N5', 'friend', 'HỮU(bạn,thuận)', 'đơn giản', ARRAY['ユウ'], ARRAY['とも'], 4, 622, (SELECT id FROM radicals WHERE character = '29')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
