INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('誘', 'N1', 'entice, lead, tempt, invite, ask, call for, seduce, allure', 'DỤ(rủ rê)', 'Ngôn Tú(ưu tú,ưu việt:秀Hòa Nãi)là Dụ rủ rê.dụ khị.透:Thay Sước là Thấu(trong suốt).', ARRAY['ユウ'], ARRAY['さそ.う','いざな.う'], 14, 993, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
