INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('邑', 'BEYOND', 'village, rural community, right village radical (no. 163)', '', '', ARRAY['ユウ'], ARRAY['むら'], 7, 2452, (SELECT id FROM radicals WHERE character = '163')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('郵', 'N2', 'mail, stagecoach stop', 'BƯU(bưu điện)', 'Thùy Ấp là Bưu điện.nhà trạm.睡:Thay Mục là Thụy(ngủ).唾:Thay Khẩu là THóa mạ.', ARRAY['ユウ'], NULL, 11, 917, (SELECT id FROM radicals WHERE character = '163')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('雄', 'N1', 'masculine, male, hero, leader, superiority, excellence', 'HÙNG(giống đực,hùng kê:gà trống)', 'Quăng(厷) Chuy là Hùng:con đực.NAM(ナム） nhi có CHYM（隹） giống đực là anh HÙNG.雌:Thay Chỉ,Chủy là Thư(giống cái).Thư Hùng:Cái đực.@@', ARRAY['ユウ'], ARRAY['お-','おす','おん'], 12, 669, (SELECT id FROM radicals WHERE character = '172')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
