INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('誉', 'N1', 'reputation, praise, honor, glory', 'DỰ(danh dự)', 'Lời Nói To và có Lửa thể hiện Danh DỰ của bản thân.挙:Thay Thủ là Cử(tuyển cử)', ARRAY['ヨ'], ARRAY['ほま.れ','ほ.める'], 13, 1064, (SELECT id FROM radicals WHERE character = '149')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
