INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('預', 'N2', 'deposit, custody, leave with, entrust to', 'DỰ(gửi,giữ)', 'Dư Hiệt là Dự gửi.Nếu có DƯ một cái đầu để trông nom nhà cửa thì hay quá.序:Thay Nghiễm là thứ Tự.野:Thay Lí là hoang Dã.', ARRAY['ヨ'], ARRAY['あず.ける','あず.かる'], 13, 981, (SELECT id FROM radicals WHERE character = '181')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('傭', 'BEYOND', 'employ, hire', '', '', ARRAY['ヨウ','チョウ'], ARRAY['やと.う','あた.い','ひと.しい'], 13, NULL, (SELECT id FROM radicals WHERE character = '9')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('幼', 'N2', 'infancy, childhood', 'ẤU(non nớt,nhỏ bé)', 'Lực(力) mà nhỏ (幺) thì là bọn trẻ con (幼 )- ấu', ARRAY['ヨウ'], ARRAY['おさな.い'], 5, 1227, (SELECT id FROM radicals WHERE character = '52')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('妖', 'N1', 'attractive, bewitching, calamity', 'YÊU(yêu tinh,quái lạ,yêu nữ)', 'NỮ 女 giới mà YỂU 夭 điệu con trai mới YÊU 妖...', ARRAY['ヨウ'], ARRAY['あや.しい','なま.めく','わざわ.い'], 7, 1964, (SELECT id FROM radicals WHERE character = '38')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('容', 'N3', 'contain, form, looks', 'DUNG(nội dung)', 'Miên Cốc là Dung(nội dung)', ARRAY['ヨウ'], ARRAY['い.れる'], 10, 264, (SELECT id FROM radicals WHERE character = '40')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('庸', 'N1', 'commonplace, ordinary, employment', 'DUNG(tầm thường,xoàng xĩnh,ngu hèn)', 'ngồi trong nhà sử dụng Bút vẽ chân dung tầm thường', ARRAY['ヨウ'], NULL, 11, 2038, (SELECT id FROM radicals WHERE character = '53')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('揚', 'N1', 'raise, elevate, hoist, praise, extol, fry in deep fat', 'DƯƠNG(chiên,rán,khen,tuyên dương)', 'Thủ Dương(昜:mặt trời(陽)) là tuyên dương.Hãy Vỗ TAY tuyên DƯƠNG những người có MÓN CHIÊN ngon nhất NGÀY hôm nay!!!**Trong lĩnh vực nấu ăn, chữ DƯƠNG này có nghĩa là CHIÊN 揚げる(あげる)', ARRAY['ヨウ'], ARRAY['あ.げる','-あ.げ','あ.がる'], 12, 1316, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('揺', 'N1', 'swing, shake, sway, rock, tremble, vibrate', 'DAO(dao động)', 'Thủ trảo Phẫu là Dao động.tay và móng tay đè lên 2 quả núi đôi==&gt;dao động, rung lắc.謡:Thêm Ngôn là ca Dao.', ARRAY['ヨウ'], ARRAY['ゆ.れる','ゆ.る','ゆ.らぐ','ゆ.るぐ','ゆ.する','ゆ.さぶる','ゆ.すぶる','うご.く'], 12, 1079, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('擁', 'N1', 'hug, embrace, possess, protect, lead', 'ỦNG(ủng hộ,giúp đỡ,ôm,cầm)', 'Thủ Đầu yêu Chùy là Ủng hộ.Thủ Ung(họ Ung:雍) là Ủng hộ', ARRAY['ヨウ'], NULL, 16, 1213, (SELECT id FROM radicals WHERE character = '64')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
