INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('沃', 'N1', 'fertility', 'ỐC(bón,tưới)', 'Thủy Yêu(夭:chết sớm) là ỐC.con ỐC 沃 này sống dưới THỦY 氵cung thịt rất mềm đc ng dân YÊU 夭 mếm...', ARRAY['ヨウ','ヨク','オク'], ARRAY['そそ.ぐ'], 7, NULL, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('浴', 'N2', 'bathe, be favored with, bask in', 'DỤC(tắm)', 'Thủy Cốc,Dục là DỤc tắm.Bạn gái DỤC đi TẮM ở tuyệt tình CỐC.欲:Thay Khiếm là Dục vọng', ARRAY['ヨク'], ARRAY['あ.びる','あ.びせる'], 10, 1136, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
