INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('酪', 'N1', 'dairy products, whey, broth, fruit juice', 'LẠC(bơ sữa)', 'Dậu Các là Lạc bơ sữa.Chị DẬU trồng CÁC loại LẠC làm BƠ SỮA', ARRAY['ラク'], NULL, 13, 2012, (SELECT id FROM radicals WHERE character = '164')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('乱', 'N2', 'riot, war, disorder, disturb', 'LOẠN(Lẫn lộn,rối,phá hoại)', 'Lưỡi liếm L mới là loạn :)', ARRAY['ラン','ロン'], ARRAY['みだ.れる','みだ.る','みだ.す','みだ','おさ.める','わた.る'], 7, 755, (SELECT id FROM radicals WHERE character = '5')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('卵', 'N2', 'egg, ovum, spawn, roe', 'NOÃN(trứng)', 'NOÃn:trứng bổ đôi', ARRAY['ラン'], ARRAY['たまご'], 7, 1342, (SELECT id FROM radicals WHERE character = '26')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('嵐', 'N1', 'storm, tempest', 'LAM(giông tố)', 'Khí núi bốc lên là nghĩa của 嵐 trong Tiếng Trung. Còn trong Tiếng Nhật là bão nhé.Sơn Phong là Lam', ARRAY['ラン'], ARRAY['あらし'], 12, 1910, (SELECT id FROM radicals WHERE character = '46')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('欄', 'N1', 'column, handrail, blank, space', 'LAN(lan can,cột)', 'Mộc Lan(lan tràn:闌) là Lan can.', ARRAY['ラン'], ARRAY['てすり'], 20, 1523, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('濫', 'N1', 'excessive, overflow, spread out', 'LẠM(đầy tràn,quá mức,lạm phát)', 'Thủy Giám(giám đốc:監) là Lạm phát.監:Thần triệt Nhất Mảnh là Giam cầm,tù,giám đốc.藍:Thêm Thảo là Lam(màu chàm).鑑:Thay Kim là Giám(gương).艦:Thay Chu là chiến Hạm.', ARRAY['ラン'], ARRAY['みだ.りに','みだ.りがましい'], 18, NULL, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('藍', 'N1', 'indigo', 'LAM(xanh lam)', 'Thảo Giam,Giám(bắt giữ,giám sát:監Thần Triệt Nhất Mãnh)là Lam xanh lam.濫:Thay Thủy là Lạm phát/鑑:Thay Kim là Giám gương.艦:Thay Chu là chiến Hạm.', ARRAY['ラン'], ARRAY['あい'], 18, 2043, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('蘭', 'BEYOND', 'orchid, Holland', '', '', ARRAY['ラン','ラ'], NULL, 19, 1886, (SELECT id FROM radicals WHERE character = '140')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
