INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('利', 'N3', 'profit, advantage, benefit', 'LỢI(lợi ích)', 'Lợi ích việc cắt lúa bằng đao', ARRAY['リ'], ARRAY['き.く'], 7, 203, (SELECT id FROM radicals WHERE character = '18')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('吏', 'N1', 'officer, an official', 'LẠI(quan lại)', 'Sử thêm 1 gạch ngang là quan LẠI.Quan LẠI là bậc trượng(nhất nghệ丈 ) phu không chỉ nói bằng cái miệngquan Lại(吏) Sử(使) dụng lịch sử(史)', ARRAY['リ'], NULL, 6, NULL, (SELECT id FROM radicals WHERE character = '30')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('履', 'N1', 'perform, complete, footgear, shoes, boots, put on (the feet)', 'LÝ(lý lịch,mặc đồ,giầy da)', 'Phục Hồi lại LÍ lịch để đi THIThi Phục là Lí lịch', ARRAY['リ'], ARRAY['は.く'], 15, 1619, (SELECT id FROM radicals WHERE character = '44')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('李', 'BEYOND', 'plum', '', '', ARRAY['リ'], ARRAY['すもも'], 7, 1147, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('梨', 'N1', 'pear tree', 'LÊ(trái lê)', 'Lợi Mộc Lê.痢:Thêm Nạch là bệnh kiết Lị.', ARRAY['リ'], ARRAY['なし'], 11, 1331, (SELECT id FROM radicals WHERE character = '75')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
