INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('璃', 'N1', 'glassy, lapis lazuli', 'Li(ngọc lưu li)', 'Ngọc Đầu Hung Nhựu là Li ngọc lưu li."Quân vương đội mũ rèn gươmĐặt trong cối đá màu cườm lưu li."離:Thay Chuy là Li biệt', ARRAY['リ'], NULL, 15, NULL, (SELECT id FROM radicals WHERE character = '96')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('痢', 'N1', 'diarrhea', 'LỊ(kiết lị,tả lị)', 'Nạch Lợi là Lị kiết lị.Lợi bị bệnh kiết lị', ARRAY['リ'], NULL, 12, 2037, (SELECT id FROM radicals WHERE character = '104')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
