INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('離', 'N1', 'detach, separation, disjoin, digress', 'Li(rời xa)', 'Đầu Hung Nhựu Chuy là Li:rời xa,chia li.璃:Thay Ngọc là lưu Li', ARRAY['リ'], ARRAY['はな.れる','はな.す'], 19, 555, (SELECT id FROM radicals WHERE character = '172')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('陸', 'N2', 'land, six', 'LỤC(đất liền,châu lục)', 'Phụ Thổ Nhân Thổ là Lục châu Lục.Họ Lục.陵:Thay Tri là lăng tẩm.', ARRAY['リク','ロク'], ARRAY['おか'], 11, 736, (SELECT id FROM radicals WHERE character = '170')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('律', 'N2', 'rhythm, law, regulation, gauge, control', 'LUẬT(pháp luật)', 'Xích Duật là Luật(Kỷ luật).Họ DUẬT có LUẬT riêng, ai làm sai bị XÍCH ngay', ARRAY['リツ','リチ','レツ'], NULL, 9, 992, (SELECT id FROM radicals WHERE character = '60')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('率', 'N1', 'ratio, rate, proportion, %, factor, lead, spearhead, command', 'SUẤT(tỷ lệ,lãnh đạo,công suất)', 'Huyền chảy nước gấp 10 lần. Đó chính là công suất.Huyền Thập tứ hướng là công Suất.', ARRAY['ソツ','リツ','シュツ'], ARRAY['ひき.いる'], 11, 383, (SELECT id FROM radicals WHERE character = '95')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
