INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('略', 'N2', 'abbreviation, omission, outline, shorten, capture, plunder', 'LƯỢC(tóm lược,mưu lược,lấy)', 'ĐIền Các là Lược.Các vị đang suy tính chiến lược ngoài ruộng', ARRAY['リャク'], ARRAY['ほぼ','はぶ.く','おか.す','おさ.める','はかりごと','はか.る'], 11, 774, (SELECT id FROM radicals WHERE character = '102')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('劉', 'BEYOND', 'weapon of war, logging axe, kill en masse, peeling (paint off a wall, etc), sparse, faded', '', '', ARRAY['リュウ','ル'], ARRAY['ころ.す'], 15, 1947, (SELECT id FROM radicals WHERE character = '18')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('流', 'N3', 'current, a sink, flow, forfeit', 'LƯU(dòng chảy,hải lưu)', 'Thủy Đầu Duẩn thêm Cổn là Lưu.Dòng hải Lưu của Đầu sông nước.硫:Thay Thạch là LƯu huỳnh', ARRAY['リュウ','ル'], ARRAY['なが.れる','なが.れ','なが.す','-なが.す'], 10, 280, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('溜', 'BEYOND', 'collect, gather, be in arrears', '', '', ARRAY['リュウ'], ARRAY['た.まる','たま.る','た.める','したた.る','たまり','ため'], 13, 2451, (SELECT id FROM radicals WHERE character = '85')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('琉', 'BEYOND', 'precious stone, gem, lapis lazuli', '', '', ARRAY['リュウ','ル'], NULL, 11, 2036, (SELECT id FROM radicals WHERE character = '96')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('留', 'N3', 'detain, fasten, halt, stop', 'LƯU(ở lại,lưu trú,lưu ban)', 'Mão(Chi thứ 4:卯) Điền là Lưu trú.瑠:Thêm Ngọc là ngọc Lưu ly.', ARRAY['リュウ','ル'], ARRAY['と.める','と.まる','とど.める','とど.まる','るうぶる'], 10, 731, (SELECT id FROM radicals WHERE character = '102')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
