INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('隆', 'N1', 'hump, high, noble, prosperity', 'LONG(phồn thịnh,long mạch)', 'Phụ Tri Sinh là Long.Hưng Long:sự phồn vinh.Vùng đất có long mạch chạy qua thì sinh sống phồn thịnh', ARRAY['リュウ'], NULL, 11, 1109, (SELECT id FROM radicals WHERE character = '170')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('竜', 'N1', 'dragon, imperial', 'LONG(con rồng)', 'Lập đuôi Điện là Long rồng.滝:thêm Thủy là Lang(thác nước).', ARRAY['リュウ','リョウ','ロウ'], ARRAY['たつ','いせ'], 10, 1195, (SELECT id FROM radicals WHERE character = '117')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
