INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('瞭', 'N1', 'clear', 'LIỆU(rõ ràng)', 'Mục Liêu là Liệu(rõ ràng).療:Thêm Nạch là trị Liệu.僚:Thêm Nhân là đồng Liêu.寮:Thêm Miên là Liêu ktx.', ARRAY['リョウ'], ARRAY['あきらか'], 17, NULL, (SELECT id FROM radicals WHERE character = '109')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
