INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('齢', 'N2', 'age', 'LINH(tuổi tác)', 'Xỉ Lệnh là Linh:tuổi tác.零:Thay Vũ là Linh(âm độ).鈴:thay Kim là Linh(cái chuông).', ARRAY['レイ'], ARRAY['よわい','とし'], 17, 770, (SELECT id FROM radicals WHERE character = '211')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('暦', 'N1', 'calendar, almanac', 'LỊCH(dương lịch,tấm lịch,niên đại)', 'Hán Lâm Nhật là Lịch.歴:Thêm CHỉ là Lịch sử.', ARRAY['レキ','リャク'], ARRAY['こよみ'], 14, 1765, (SELECT id FROM radicals WHERE character = '72')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('歴', 'N2', 'curriculum, continuation, passage of time', 'LỊCH(lịch sử)', 'Hán Lâm CHỉ là Lịch sử.DỪNG lại bên hang động ở sườn núi của khu RỪNG để nghĩ về LỊCH sử của nó暦:Thêm Nhật là Lịch treo tường.', ARRAY['レキ','レッキ'], NULL, 14, 632, (SELECT id FROM radicals WHERE character = '77')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('列', 'N3', 'file, row, rank, tier, column', 'LIỆT(hàng lối,số nhiều,bày,liệt kê)', 'ĐÃI đao là LIỆT kê ra kế hoạch tuần', ARRAY['レツ','レ'], NULL, 6, 927, (SELECT id FROM radicals WHERE character = '18')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('劣', 'N1', 'inferiority, be inferior to, be worse', 'LIỆT(yếu kém)', 'Thiếu lực là LIỆT dương công tử:yếu kém tình dục', ARRAY['レツ'], ARRAY['おと.る'], 6, 1620, (SELECT id FROM radicals WHERE character = '19')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('烈', 'N1', 'ardent, violent, vehement, furious, severe, extreme', 'LIỆT(mãnh liệt,bạo lực)', 'Liệt Hỏa là Liệt bạo lực', ARRAY['レツ'], ARRAY['はげ.しい'], 10, 1397, (SELECT id FROM radicals WHERE character = '86')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('裂', 'N1', 'split, rend, tear', 'LIỆT(xé nát,chia ra)', 'Liệt Y là Liệt xé rách.LIỆT kê những bộ Y phục bị RÁCH.烈:Thay Hỏa là mãnh Liệt.例:Thay Nhân là Lệ(ví dụ).', ARRAY['レツ'], ARRAY['さ.く','さ.ける','-ぎ.れ'], 12, 1041, (SELECT id FROM radicals WHERE character = '145')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('廉', 'N1', 'bargain, reason, charge, suspicion, point, account, purity, honest, low price, cheap, rested, contented, peaceful', 'LIÊM(trong sạch,liêm khiết,trung thực,thanh liêm)', 'Nghiễm Kiêm là Liêm khiết.Ở dưới mái nhà kiêm 兼 nhiều việc một lúc là liêm khiết', ARRAY['レン'], NULL, 13, 2066, (SELECT id FROM radicals WHERE character = '53')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
