INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('練', 'N2', 'practice, gloss, train, drill, polish, refine', 'LUYỆN(luyện tập)', 'Mịch Đông là Luyện luyện tập.Đông(東) phương bất bại dùng sợi Chỉ (糸) để Luyện (練) tịch tà kiếm phổ.錬:Thay Kim là tinh Luyện.', ARRAY['レン'], ARRAY['ね.る','ね.り'], 14, 788, (SELECT id FROM radicals WHERE character = '120')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
