INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('連', 'N3', 'take along, lead, join, connect, party, gang, clique', 'LIÊN(liên tục,liền)', 'Sước Xa là Liên lạc.ngày xưa dùng XE ngựa chạy khắp nơi để LIÊN lạc với nhau.運:Thêm Mịch là Vận chuyển.庫:Thay Nghiễm là Khố(cái kho).', ARRAY['レン'], ARRAY['つら.なる','つら.ねる','つ.れる','-づ.れ'], 10, 30, (SELECT id FROM radicals WHERE character = '162')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('錬', 'N1', 'tempering, refine, drill, train, polish', 'LUYỆN(rèn đúc)', 'Kim Đông là Luyện tinh luyện,rèn luyện.Luyện kim ở phía đông練:Thay Mịch là Luyện tập', ARRAY['レン'], ARRAY['ね.る'], 16, 2221, (SELECT id FROM radicals WHERE character = '167')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
