INSERT INTO kanji (character, jlpt_level, meaning_en, meaning_vi, mnemonic_vi, onyomi, kunyomi, stroke_count, frequency, radical_id) VALUES ('賂', 'N1', 'bribe', 'LỘ(hối lộ,mãi lộ)', 'Bối Các là Lộ hối lộ.Đem tiền貝 đi hối LỘ cho các各 quan.路:Thay Túc là Lộ(con đường).露:Thêm Vũ là Lộ(sương).', ARRAY['ロ'], ARRAY['まいな.い','まいな.う'], 13, NULL, (SELECT id FROM radicals WHERE character = '154')) ON CONFLICT (character) DO UPDATE SET jlpt_level = EXCLUDED.jlpt_level, meaning_vi = EXCLUDED.meaning_vi, mnemonic_vi = EXCLUDED.mnemonic_vi, stroke_count = EXCLUDED.stroke_count, frequency = EXCLUDED.frequency, radical_id = EXCLUDED.radical_id;
